CREATE TABLE `ai_agent_executions` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `agent_id` int(11) DEFAULT NULL COMMENT '智能体ID',
  `agent_code` varchar(30) NOT NULL DEFAULT '' COMMENT '智能体编码',
  `trigger_type` varchar(20) NOT NULL DEFAULT 'manual' COMMENT 'event/timer/manual',
  `input_data` json DEFAULT NULL COMMENT '输入数据',
  `decision_result` varchar(20) DEFAULT NULL COMMENT 'approved/rejected/pending',
  `execution_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=待执行 1=执行中 2=成功 3=失败 4=需人工介入',
  `output_data` json DEFAULT NULL COMMENT '输出数据',
  `error_message` text COMMENT '错误信息',
  `executed_at` datetime DEFAULT NULL COMMENT '执行时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_agent_code` (`agent_code`),
  KEY `idx_status` (`execution_status`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COMMENT='智能体执行记录表';

CREATE TABLE `ai_agent_publish_approvals` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `approval_id` varchar(32) NOT NULL DEFAULT '' COMMENT '审批唯一标识(UUID)',
  `version_id` varchar(32) NOT NULL DEFAULT '' COMMENT '版本ID（关联 ai_agent_versions）',
  `agent_id` varchar(32) NOT NULL DEFAULT '' COMMENT '智能体ID（关联 ai_agents）',
  `applicant_id` int(11) NOT NULL DEFAULT '0' COMMENT '申请人ID',
  `applicant_name` varchar(50) NOT NULL DEFAULT '' COMMENT '申请人姓名（冗余）',
  `approval_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '审批状态：pending/approved/rejected/canceled',
  `approver_id` int(11) DEFAULT NULL COMMENT '审批人ID',
  `approver_name` varchar(50) DEFAULT NULL COMMENT '审批人姓名',
  `approval_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approval_comment` varchar(500) DEFAULT NULL COMMENT '审批意见',
  `security_scan_result` json DEFAULT NULL COMMENT '安全扫描结果(JSON)',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_approval_id` (`approval_id`),
  KEY `idx_version_id` (`version_id`),
  KEY `idx_agent_status` (`agent_id`,`approval_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI智能体发布审批记录表';

CREATE TABLE `ai_agent_tasks` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `agent_id` int(11) DEFAULT NULL COMMENT '智能体ID',
  `task_type` varchar(30) NOT NULL DEFAULT '' COMMENT 'approval/churn/order',
  `task_target_id` int(11) NOT NULL DEFAULT '0' COMMENT '目标业务ID',
  `task_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=待处理 1=处理中 2=已完成 3=失败',
  `priority` tinyint(1) NOT NULL DEFAULT '2' COMMENT '1=低 2=中 3=高',
  `assigned_to` int(11) DEFAULT NULL COMMENT '指派给',
  `processed_at` datetime DEFAULT NULL COMMENT '处理时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_task_type` (`task_type`),
  KEY `idx_task_status` (`task_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='智能体任务表';

CREATE TABLE `ai_agent_versions` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `version_id` varchar(32) NOT NULL DEFAULT '' COMMENT '版本唯一标识(UUID)',
  `agent_id` varchar(32) NOT NULL DEFAULT '' COMMENT '智能体ID（关联 ai_agents）',
  `version_number` varchar(20) NOT NULL DEFAULT '' COMMENT '版本号（如 1.0.0）',
  `version_name` varchar(100) DEFAULT NULL COMMENT '版本名称',
  `version_desc` varchar(500) DEFAULT NULL COMMENT '版本描述',
  `config_snapshot` json NOT NULL COMMENT '配置快照（该版本的完整智能体配置）',
  `status` varchar(20) NOT NULL DEFAULT 'draft' COMMENT '状态：draft/reviewing/approved/published/offline',
  `publish_type` varchar(20) DEFAULT NULL COMMENT '发布类型：full（全量）/gray（灰度）',
  `gray_ratio` int(11) NOT NULL DEFAULT '0' COMMENT '灰度比例（0-100）',
  `gray_users` json DEFAULT NULL COMMENT '灰度用户列表(JSON数组)',
  `channels` json DEFAULT NULL COMMENT '发布渠道配置(JSON，各渠道配置与状态)',
  `is_current` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否当前版本：1是 0否',
  `published_by` int(11) DEFAULT NULL COMMENT '发布人ID',
  `published_by_name` varchar(50) DEFAULT NULL COMMENT '发布人姓名',
  `published_at` datetime DEFAULT NULL COMMENT '发布时间',
  `reviewed_by` int(11) DEFAULT NULL COMMENT '审核人ID',
  `reviewed_by_name` varchar(50) DEFAULT NULL COMMENT '审核人姓名',
  `reviewed_at` datetime DEFAULT NULL COMMENT '审核时间',
  `review_comment` varchar(500) DEFAULT NULL COMMENT '审核意见',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_version_id` (`version_id`),
  KEY `idx_agent_status` (`agent_id`,`status`),
  KEY `idx_agent_create` (`agent_id`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI智能体版本表';

CREATE TABLE `ai_agents` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `agent_id` varchar(32) NOT NULL DEFAULT '' COMMENT '智能体唯一标识',
  `agent_name` varchar(100) NOT NULL DEFAULT '' COMMENT '智能体名称',
  `agent_icon` varchar(255) DEFAULT NULL COMMENT '头像（图标类名或图片URL）',
  `description` varchar(255) DEFAULT NULL COMMENT '描述',
  `system_prompt` text COMMENT '系统提示词（人设）',
  `model_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联模型ID（ai_models.id）',
  `knowledge_base_ids` json DEFAULT NULL COMMENT '绑定的知识库ID列表(JSON数组)',
  `tool_ids` json DEFAULT NULL COMMENT '绑定的工具ID列表(JSON数组)',
  `is_system` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否系统预置：1是 0否',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_agent_id` (`agent_id`),
  KEY `idx_created_create` (`created_by`,`create_time`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COMMENT='AI智能体表';

CREATE TABLE `ai_alert_history` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `alert_id` varchar(32) NOT NULL DEFAULT '' COMMENT '告警唯一标识(UUID)',
  `rule_id` varchar(32) NOT NULL DEFAULT '' COMMENT '规则ID（关联 ai_alert_rules）',
  `rule_name` varchar(100) NOT NULL DEFAULT '' COMMENT '规则名称（冗余）',
  `metric` varchar(50) NOT NULL DEFAULT '' COMMENT '监控指标（冗余）',
  `level` varchar(20) NOT NULL DEFAULT 'info' COMMENT '告警级别',
  `current_value` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '触发时指标值',
  `threshold` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '阈值',
  `message` varchar(500) DEFAULT NULL COMMENT '告警消息',
  `trigger_time` datetime NOT NULL COMMENT '触发时间',
  `recover_time` datetime DEFAULT NULL COMMENT '恢复时间',
  `status` varchar(20) NOT NULL DEFAULT 'triggered' COMMENT '状态：triggered/confirmed/recovered',
  `notified` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已通知：1是0否',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_alert_id` (`alert_id`),
  KEY `idx_rule_id` (`rule_id`),
  KEY `idx_status_create` (`status`,`create_time`),
  KEY `idx_trigger_time` (`trigger_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI告警历史表';

CREATE TABLE `ai_alert_notifications` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `alert_id` varchar(32) NOT NULL DEFAULT '' COMMENT '告警ID（关联 ai_alert_history）',
  `channel` varchar(20) NOT NULL DEFAULT 'inbox' COMMENT '通知渠道：inbox/email/dingtalk/workwx',
  `receiver_id` int(11) NOT NULL DEFAULT '0' COMMENT '接收人ID',
  `receiver_name` varchar(50) NOT NULL DEFAULT '' COMMENT '接收人姓名（冗余）',
  `send_time` datetime DEFAULT NULL COMMENT '发送时间',
  `send_status` varchar(20) NOT NULL DEFAULT 'success' COMMENT '发送状态：success/failed',
  `error_message` text COMMENT '错误信息',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_alert_id` (`alert_id`),
  KEY `idx_receiver_id` (`receiver_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='AI告警通知记录表';

CREATE TABLE `ai_alert_rules` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `rule_id` varchar(32) NOT NULL DEFAULT '' COMMENT '规则唯一标识(UUID)',
  `rule_name` varchar(100) NOT NULL DEFAULT '' COMMENT '规则名称',
  `metric` varchar(50) NOT NULL DEFAULT '' COMMENT '监控指标：error_rate/response_time/call_count/token_consumption/service_availability/cpu_usage/memory_usage',
  `operator` varchar(10) NOT NULL DEFAULT '>' COMMENT '比较运算符：>/>=/</<=/==',
  `threshold` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '阈值',
  `duration` int(11) NOT NULL DEFAULT '1' COMMENT '持续时间（分钟），指标持续异常N分钟后触发',
  `level` varchar(20) NOT NULL DEFAULT 'info' COMMENT '告警级别：info/warning/critical/emergency',
  `channels` json NOT NULL COMMENT '通知渠道列表（["inbox","email","dingtalk","workwx"]）',
  `receivers` json DEFAULT NULL COMMENT '接收人ID列表',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `description` varchar(255) DEFAULT NULL COMMENT '描述说明',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rule_id` (`rule_id`),
  KEY `idx_metric` (`metric`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI告警规则表';

CREATE TABLE `ai_api_key_call_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `log_id` varchar(32) NOT NULL DEFAULT '' COMMENT '日志唯一标识(UUID)',
  `key_id` int(11) NOT NULL DEFAULT '0' COMMENT 'API密钥ID',
  `key_name` varchar(100) NOT NULL DEFAULT '' COMMENT '密钥名称（冗余）',
  `app_id` varchar(32) NOT NULL DEFAULT '' COMMENT '应用ID',
  `caller_ip` varchar(50) NOT NULL DEFAULT '' COMMENT '调用人IP',
  `request_path` varchar(255) NOT NULL DEFAULT '' COMMENT '请求路径',
  `duration` int(11) DEFAULT NULL COMMENT '耗时（毫秒）',
  `status` varchar(20) NOT NULL DEFAULT 'success' COMMENT '状态：success/error',
  `error_message` text COMMENT '错误信息',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_log_id` (`log_id`),
  KEY `idx_key_create` (`key_id`,`create_time`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI API密钥调用日志表';

CREATE TABLE `ai_api_keys` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `key_id` varchar(32) NOT NULL DEFAULT '' COMMENT '密钥唯一标识(UUID)',
  `app_id` varchar(32) NOT NULL DEFAULT '' COMMENT '所属应用ID',
  `key_name` varchar(100) NOT NULL DEFAULT '' COMMENT '密钥名称',
  `key_prefix` varchar(50) NOT NULL DEFAULT '' COMMENT '密钥展示前缀（前8+后4，含掩码）',
  `key_hash` varchar(255) NOT NULL DEFAULT '' COMMENT '密钥加密值（CryptHelper 可逆加密，不存明文）',
  `key_expire` datetime DEFAULT NULL COMMENT '过期时间（空=永不过期）',
  `ip_whitelist` json DEFAULT NULL COMMENT 'IP白名单',
  `call_count` int(11) NOT NULL DEFAULT '0' COMMENT '调用次数',
  `last_call_time` datetime DEFAULT NULL COMMENT '最后调用时间',
  `last_call_ip` varchar(50) NOT NULL DEFAULT '' COMMENT '最后调用IP',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_key_id` (`key_id`),
  KEY `idx_app_id` (`app_id`),
  KEY `idx_creator_create` (`created_by`,`create_time`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI应用API密钥表';

CREATE TABLE `ai_app_call_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `log_id` varchar(32) NOT NULL DEFAULT '' COMMENT '日志唯一标识(UUID)',
  `app_id` varchar(32) NOT NULL DEFAULT '' COMMENT '应用ID',
  `app_name` varchar(100) NOT NULL DEFAULT '' COMMENT '应用名称（冗余）',
  `api_key_id` int(11) DEFAULT NULL COMMENT 'API密钥ID',
  `caller_id` int(11) DEFAULT NULL COMMENT '调用人ID',
  `caller_ip` varchar(50) NOT NULL DEFAULT '' COMMENT '调用人IP',
  `request_path` varchar(255) NOT NULL DEFAULT '' COMMENT '请求路径',
  `duration` int(11) DEFAULT NULL COMMENT '耗时（毫秒）',
  `status` varchar(20) NOT NULL DEFAULT 'success' COMMENT '状态：success/error',
  `error_message` text COMMENT '错误信息',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_log_id` (`log_id`),
  KEY `idx_app_create` (`app_id`,`create_time`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI应用调用日志表';

CREATE TABLE `ai_approval_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_key` varchar(50) NOT NULL DEFAULT '',
  `config_value` text,
  `description` varchar(255) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_config_key` (`config_key`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='AI审批规则配置表';

CREATE TABLE `ai_approval_recommendations` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `approval_instance_id` int(11) NOT NULL DEFAULT '0' COMMENT '审批实例ID',
  `recommendation` varchar(10) NOT NULL DEFAULT '' COMMENT 'pass/reject/transfer',
  `confidence` varchar(10) DEFAULT NULL COMMENT 'high/medium/low',
  `reason` text COMMENT '建议理由',
  `user_accepted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=否 1=是',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_approval_instance_id` (`approval_instance_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='审批建议表';

CREATE TABLE `ai_apps` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `app_id` varchar(32) NOT NULL DEFAULT '' COMMENT '应用唯一标识(UUID)',
  `app_name` varchar(100) NOT NULL DEFAULT '' COMMENT '应用名称',
  `app_type` varchar(20) NOT NULL DEFAULT 'chat' COMMENT '应用类型：agent/workflow/chat',
  `description` varchar(255) NOT NULL DEFAULT '' COMMENT '应用描述',
  `config` json NOT NULL COMMENT '应用配置（agent存agent_id；workflow存workflow_id；chat存model_id/system_prompt等）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `call_count` int(11) NOT NULL DEFAULT '0' COMMENT '调用次数',
  `last_call_time` datetime DEFAULT NULL COMMENT '最后调用时间',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_app_id` (`app_id`),
  KEY `idx_creator_create` (`created_by`,`create_time`),
  KEY `idx_status` (`status`),
  KEY `idx_app_type` (`app_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI应用表';

CREATE TABLE `ai_chat_messages` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `session_id` varchar(32) NOT NULL DEFAULT '' COMMENT '会话ID',
  `message_id` varchar(32) NOT NULL DEFAULT '' COMMENT '消息唯一标识（UUID去横线）',
  `role` varchar(20) NOT NULL DEFAULT '' COMMENT '角色：user/assistant/system/tool',
  `content` text COMMENT '消息内容',
  `sources` json DEFAULT NULL COMMENT '引用来源列表',
  `feedback` tinyint(1) NOT NULL DEFAULT '0' COMMENT '用户反馈：0=无 1=有用 2=无用',
  `feedback_reason` varchar(500) DEFAULT NULL COMMENT '反馈原因（无用时填写）',
  `reasoning_content` text COMMENT 'DeepSeek思考内容（需原样回传）',
  `tool_calls` json DEFAULT NULL COMMENT '工具调用记录(JSON)',
  `tool_call_id` varchar(50) DEFAULT NULL COMMENT '工具调用ID',
  `status` varchar(20) NOT NULL DEFAULT 'completed' COMMENT '状态：pending/completed/error',
  `token_count` int(11) NOT NULL DEFAULT '0' COMMENT 'Token消耗数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `tool_calls_display` json DEFAULT NULL COMMENT '工具调用展示数据(JSON)',
  `tool_call_results` json DEFAULT NULL COMMENT '工具调用结果(JSON)',
  `tool_call_status` varchar(20) DEFAULT NULL COMMENT '工具调用状态：pending/executing/success/failed/cancelled',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_message_id` (`message_id`),
  KEY `idx_session_create` (`session_id`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=643 DEFAULT CHARSET=utf8mb4 COMMENT='AI对话消息表';

CREATE TABLE `ai_chat_sessions` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `session_id` varchar(32) NOT NULL DEFAULT '' COMMENT '会话唯一标识（UUID去横线）',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `title` varchar(100) NOT NULL DEFAULT '新对话' COMMENT '会话标题',
  `tool_call_count` int(11) NOT NULL DEFAULT '0' COMMENT '工具调用次数',
  `total_tokens` int(11) NOT NULL DEFAULT '0' COMMENT 'Token消耗总数',
  `status` varchar(20) NOT NULL DEFAULT 'active' COMMENT '状态：active活跃/archived已归档',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  `agent_id` varchar(32) DEFAULT NULL COMMENT '智能体ID（关联 ai_agents.agent_id）',
  `agent_name` varchar(100) DEFAULT NULL COMMENT '智能体名称（冗余）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_session_id` (`session_id`),
  KEY `idx_user_update` (`user_id`,`update_time`)
) ENGINE=InnoDB AUTO_INCREMENT=180 DEFAULT CHARSET=utf8mb4 COMMENT='AI对话会话表';

CREATE TABLE `ai_churn_records` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `task_type` varchar(30) NOT NULL DEFAULT '' COMMENT '任务类型',
  `task_id` int(11) NOT NULL DEFAULT '0' COMMENT '任务ID',
  `task_title` varchar(200) DEFAULT '' COMMENT '任务标题（冗余）',
  `target_user_id` int(11) NOT NULL DEFAULT '0' COMMENT '目标用户ID',
  `churn_count` int(11) NOT NULL DEFAULT '1' COMMENT '催办次数',
  `churn_channel` varchar(20) DEFAULT NULL COMMENT 'inbox/sms/email',
  `churn_content` text COMMENT '催办内容',
  `is_read` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=否 1=是',
  `is_handled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=否 1=是',
  `escalated_at` datetime DEFAULT NULL COMMENT '升级时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_task` (`task_type`,`task_id`),
  KEY `idx_target_user` (`target_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='催办记录表';

CREATE TABLE `ai_datasource_sync_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `log_id` varchar(32) NOT NULL DEFAULT '',
  `ds_id` varchar(32) NOT NULL DEFAULT '',
  `start_time` datetime DEFAULT NULL,
  `end_time` datetime DEFAULT NULL,
  `duration` int(11) DEFAULT NULL,
  `total_count` int(11) NOT NULL DEFAULT '0',
  `success_count` int(11) NOT NULL DEFAULT '0',
  `failed_count` int(11) NOT NULL DEFAULT '0',
  `skipped_count` int(11) NOT NULL DEFAULT '0',
  `status` varchar(20) NOT NULL DEFAULT 'running',
  `error_message` text,
  `error_details` json DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_log_id` (`log_id`),
  KEY `idx_ds_create` (`ds_id`,`create_time`),
  KEY `idx_status_create` (`status`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI数据源同步日志表';

CREATE TABLE `ai_datasources` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `ds_id` varchar(32) NOT NULL DEFAULT '',
  `ds_name` varchar(100) NOT NULL DEFAULT '',
  `ds_type` varchar(30) NOT NULL DEFAULT '',
  `kb_id` varchar(32) NOT NULL DEFAULT '',
  `config` json NOT NULL,
  `sync_config` json DEFAULT NULL,
  `field_mapping` json DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `sync_status` varchar(20) NOT NULL DEFAULT 'idle',
  `last_sync_time` datetime DEFAULT NULL,
  `last_sync_count` int(11) NOT NULL DEFAULT '0',
  `total_sync_count` int(11) NOT NULL DEFAULT '0',
  `sync_count` int(11) NOT NULL DEFAULT '0',
  `created_by` int(11) NOT NULL DEFAULT '0',
  `created_by_name` varchar(50) NOT NULL DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ds_id` (`ds_id`),
  KEY `idx_kb_id` (`kb_id`),
  KEY `idx_creator_create` (`created_by`,`create_time`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='AI数据源表';

CREATE TABLE `ai_eval_cases` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `case_id` varchar(32) NOT NULL DEFAULT '' COMMENT '用例唯一标识(UUID)',
  `case_name` varchar(100) NOT NULL DEFAULT '' COMMENT '用例名称',
  `input` text NOT NULL COMMENT '输入内容',
  `expected_output` text COMMENT '期望输出',
  `expected_tools` json DEFAULT NULL COMMENT '期望调用的工具ID列表(JSON数组)',
  `tags` json DEFAULT NULL COMMENT '标签列表(JSON数组)',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_case_id` (`case_id`),
  KEY `idx_creator_create` (`created_by`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI评测测试用例表';

CREATE TABLE `ai_eval_tasks` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `task_id` varchar(32) NOT NULL DEFAULT '' COMMENT '任务唯一标识(UUID)',
  `agent_id` varchar(32) NOT NULL DEFAULT '' COMMENT '智能体ID（关联 ai_agents）',
  `agent_name` varchar(100) NOT NULL DEFAULT '' COMMENT '智能体名称（冗余）',
  `task_name` varchar(100) DEFAULT NULL COMMENT '任务名称',
  `case_ids` json NOT NULL COMMENT '测试用例ID列表(JSON数组)',
  `total_count` int(11) NOT NULL DEFAULT '0' COMMENT '总用例数',
  `passed_count` int(11) NOT NULL DEFAULT '0' COMMENT '通过数',
  `failed_count` int(11) NOT NULL DEFAULT '0' COMMENT '失败数',
  `pass_rate` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '通过率(%)',
  `avg_score` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '平均匹配度评分',
  `tool_accuracy` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '工具调用准确率(%)',
  `knowledge_recall` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '知识库召回率(%)',
  `avg_response_time` int(11) NOT NULL DEFAULT '0' COMMENT '平均响应时间(ms)',
  `total_tokens` int(11) NOT NULL DEFAULT '0' COMMENT 'Token消耗总量',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态：pending/running/completed/failed',
  `result` json DEFAULT NULL COMMENT '评测结果（每个用例的详细结果）',
  `report_path` varchar(500) DEFAULT NULL COMMENT '报告文件路径',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_id` (`task_id`),
  KEY `idx_agent_id` (`agent_id`),
  KEY `idx_creator_create` (`created_by`,`create_time`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI评测任务表';

CREATE TABLE `ai_favorite_categories` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `category_name` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名称',
  `category_color` varchar(20) NOT NULL DEFAULT '#409EFF' COMMENT '分类颜色',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户ID（0=系统预置）',
  `is_system` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否系统预置：1是 0否',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_sort` (`user_id`,`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='AI收藏分类表';

CREATE TABLE `ai_favorites` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `favorite_id` varchar(32) NOT NULL DEFAULT '' COMMENT '收藏唯一标识（UUID去横线）',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `session_id` varchar(32) DEFAULT NULL COMMENT '来源会话ID',
  `message_id` varchar(32) DEFAULT NULL COMMENT '收藏的AI回复消息ID',
  `question` text COMMENT '用户问题内容（冗余存储）',
  `answer` text COMMENT 'AI回答内容（冗余存储）',
  `category_id` int(11) DEFAULT NULL COMMENT '分类ID',
  `tags` json DEFAULT NULL COMMENT '标签列表(JSON)',
  `summary` varchar(255) NOT NULL DEFAULT '' COMMENT '摘要（自动从问题提取）',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  `source` varchar(20) NOT NULL DEFAULT 'chat' COMMENT '来源：chat对话收藏/manual手动录入',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_favorite_id` (`favorite_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='AI收藏问答表';

CREATE TABLE `ai_forecast_cache` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `dimension` varchar(20) NOT NULL DEFAULT '' COMMENT '预测维度：overall/category/customer_level/sales_person',
  `dimension_value` varchar(50) DEFAULT NULL COMMENT '维度值',
  `forecast_data` json DEFAULT NULL COMMENT '预测数据（日期/预测值/下限/上限）',
  `factors` json DEFAULT NULL COMMENT '因子贡献度',
  `accuracy` decimal(5,2) DEFAULT NULL COMMENT '模型准确率（%）',
  `generated_at` datetime NOT NULL COMMENT '生成时间',
  `expires_at` datetime NOT NULL COMMENT '过期时间（缓存24h）',
  PRIMARY KEY (`id`),
  KEY `idx_dimension` (`dimension`,`dimension_value`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='AI预测缓存表';

CREATE TABLE `ai_knowledge_bases` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `kb_id` varchar(32) NOT NULL DEFAULT '' COMMENT '知识库唯一标识（UUID去横线）',
  `kb_name` varchar(100) NOT NULL DEFAULT '' COMMENT '知识库名称',
  `description` varchar(255) DEFAULT NULL COMMENT '知识库描述',
  `embedding_model` varchar(50) NOT NULL DEFAULT 'text-embedding-v3' COMMENT '向量化模型',
  `chunk_size` int(11) NOT NULL DEFAULT '512' COMMENT '切片大小',
  `overlap` int(11) NOT NULL DEFAULT '50' COMMENT '重叠大小',
  `doc_count` int(11) NOT NULL DEFAULT '0' COMMENT '文档数量',
  `total_size` bigint(20) NOT NULL DEFAULT '0' COMMENT '总大小（字节）',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态：pending/processing/completed/failed',
  `progress` int(11) NOT NULL DEFAULT '0' COMMENT '向量化进度（0-100）',
  `error_message` text COMMENT '错误信息',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_kb_id` (`kb_id`),
  KEY `idx_created_create` (`created_by`,`create_time`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='AI知识库表';

CREATE TABLE `ai_knowledge_chunks` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `chunk_id` varchar(32) NOT NULL DEFAULT '' COMMENT '切片唯一标识（UUID去横线）',
  `doc_id` varchar(32) NOT NULL DEFAULT '' COMMENT '文档ID（关联 ai_knowledge_documents.doc_id）',
  `kb_id` varchar(32) NOT NULL DEFAULT '' COMMENT '知识库ID',
  `chunk_index` int(11) NOT NULL DEFAULT '0' COMMENT '切片序号',
  `content` text COMMENT '切片文本内容',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_chunk_id` (`chunk_id`),
  KEY `idx_kb_id` (`kb_id`),
  KEY `idx_doc_index` (`doc_id`,`chunk_index`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI知识库文档切片表';

CREATE TABLE `ai_knowledge_documents` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `doc_id` varchar(32) NOT NULL DEFAULT '' COMMENT '文档唯一标识（UUID去横线）',
  `kb_id` varchar(32) NOT NULL DEFAULT '' COMMENT '知识库ID',
  `doc_name` varchar(255) NOT NULL DEFAULT '' COMMENT '文档名称',
  `doc_type` varchar(20) NOT NULL DEFAULT '' COMMENT '文档类型：pdf/word/excel/ppt/txt/md/html',
  `doc_size` bigint(20) NOT NULL DEFAULT '0' COMMENT '文档大小（字节）',
  `doc_path` varchar(500) NOT NULL DEFAULT '' COMMENT '文档存储路径',
  `chunk_count` int(11) NOT NULL DEFAULT '0' COMMENT '切片数量',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '向量化状态：pending/processing/completed/failed',
  `error_message` text COMMENT '错误信息',
  `uploaded_by` int(11) NOT NULL DEFAULT '0' COMMENT '上传人ID',
  `uploaded_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '上传人姓名',
  `upload_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  `process_time` datetime DEFAULT NULL COMMENT '处理完成时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  `progress` int(11) NOT NULL DEFAULT '0' COMMENT '处理进度（0-100）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_doc_id` (`doc_id`),
  KEY `idx_kb_status` (`kb_id`,`status`),
  KEY `idx_upload_time` (`upload_time`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='AI知识库文档表';

CREATE TABLE `ai_model_providers` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `provider_code` varchar(50) NOT NULL DEFAULT '' COMMENT '服务商标识：deepseek/qwen/zhipu/baichuan/custom',
  `provider_name` varchar(100) NOT NULL DEFAULT '' COMMENT '服务商名称',
  `api_base_url` varchar(255) NOT NULL DEFAULT '' COMMENT 'API基础地址',
  `auth_type` varchar(20) NOT NULL DEFAULT 'api_key' COMMENT '认证方式：api_key/jwt_token',
  `api_key` text COMMENT 'API密钥（加密存储）',
  `api_secret` text COMMENT 'API密钥备用字段（加密存储）',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `description` varchar(255) NOT NULL DEFAULT '' COMMENT '描述说明',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_provider_code` (`provider_code`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='AI服务商表';

CREATE TABLE `ai_models` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `model_code` varchar(50) NOT NULL DEFAULT '' COMMENT '模型标识：deepseek-v4-pro/qwen-plus/glm-5.2',
  `model_name` varchar(100) NOT NULL DEFAULT '' COMMENT '模型名称',
  `provider_id` int(11) NOT NULL DEFAULT '0' COMMENT '所属服务商ID',
  `context_length` int(11) NOT NULL DEFAULT '128000' COMMENT '上下文长度',
  `input_price` decimal(10,4) NOT NULL DEFAULT '0.0000' COMMENT '输入价格（元/百万tokens）',
  `output_price` decimal(10,4) NOT NULL DEFAULT '0.0000' COMMENT '输出价格（元/百万tokens）',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认模型：1是 0否',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `description` varchar(255) NOT NULL DEFAULT '' COMMENT '描述说明',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_model_code` (`model_code`),
  KEY `idx_provider_id` (`provider_id`),
  KEY `idx_status` (`status`),
  KEY `idx_is_default` (`is_default`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COMMENT='AI模型表';

CREATE TABLE `ai_order_process_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '订单ID',
  `step` varchar(20) NOT NULL DEFAULT '' COMMENT 'credit_check/inventory_check/create_notice',
  `status` varchar(20) NOT NULL DEFAULT '' COMMENT 'pass/fail/pending',
  `detail` json DEFAULT NULL COMMENT '处理详情',
  `processed_at` datetime NOT NULL COMMENT '处理时间',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COMMENT='订单处理日志表';

CREATE TABLE `ai_report_schedules` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `schedule_name` varchar(100) NOT NULL DEFAULT '' COMMENT '任务名称',
  `template_id` int(11) NOT NULL DEFAULT '0' COMMENT '模板ID',
  `template_name` varchar(50) NOT NULL DEFAULT '' COMMENT '模板名称',
  `time_range` varchar(50) DEFAULT NULL COMMENT '时间范围（如 last_month/current_month）',
  `config` json DEFAULT NULL COMMENT '生成配置',
  `frequency` varchar(10) NOT NULL DEFAULT 'daily' COMMENT '频率：daily/weekly/monthly',
  `run_time` varchar(20) NOT NULL DEFAULT '09:00' COMMENT '执行时间（daily/weekly: HH:MM；monthly: D HH:MM）',
  `recipients` json DEFAULT NULL COMMENT '接收人 [{type:user,id,name}]',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `last_run_at` datetime DEFAULT NULL COMMENT '上次执行时间',
  `next_run_at` datetime DEFAULT NULL COMMENT '下次执行时间',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_status_next` (`status`,`next_run_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI定时报告任务表';

CREATE TABLE `ai_report_templates` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `template_name` varchar(50) NOT NULL DEFAULT '' COMMENT '模板名称',
  `template_code` varchar(30) NOT NULL DEFAULT '' COMMENT '模板编码',
  `description` text COMMENT '模板描述',
  `structure` json DEFAULT NULL COMMENT '模板结构（章节）',
  `data_sources` json DEFAULT NULL COMMENT '数据源配置',
  `prompt_template` text COMMENT 'AI分析提示词模板',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=禁用 1=启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_code` (`template_code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='AI报告模板表';

CREATE TABLE `ai_reports` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `report_name` varchar(100) NOT NULL DEFAULT '' COMMENT '报告名称',
  `template_id` int(11) NOT NULL DEFAULT '0' COMMENT '模板ID',
  `template_name` varchar(50) NOT NULL DEFAULT '' COMMENT '模板名称（冗余展示）',
  `time_range` varchar(50) DEFAULT NULL COMMENT '时间范围（如 2026-08）',
  `config` json DEFAULT NULL COMMENT '生成配置（格式/包含内容）',
  `content` longtext COMMENT '报告内容（HTML）',
  `file_url` varchar(255) DEFAULT NULL COMMENT '导出文件URL',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=生成中 1=已完成 2=失败',
  `error_msg` varchar(500) DEFAULT NULL COMMENT '失败原因',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI报告记录表';

CREATE TABLE `ai_search_schemas` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `schema_id` varchar(32) NOT NULL DEFAULT '',
  `schema_name` varchar(100) NOT NULL DEFAULT '',
  `kb_id` varchar(32) NOT NULL DEFAULT '',
  `search_mode` varchar(20) NOT NULL DEFAULT 'semantic',
  `top_k` int(11) NOT NULL DEFAULT '5',
  `threshold` decimal(3,2) NOT NULL DEFAULT '0.60',
  `semantic_weight` decimal(3,2) NOT NULL DEFAULT '0.50',
  `keyword_weight` decimal(3,2) NOT NULL DEFAULT '0.50',
  `rerank_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `created_by` int(11) NOT NULL DEFAULT '0',
  `created_by_name` varchar(50) NOT NULL DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_schema_id` (`schema_id`),
  KEY `idx_kb_create` (`kb_id`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI检索方案表';

CREATE TABLE `ai_search_test_records` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `record_id` varchar(32) NOT NULL DEFAULT '',
  `kb_id` varchar(32) NOT NULL DEFAULT '',
  `kb_name` varchar(100) NOT NULL DEFAULT '',
  `query_text` text NOT NULL,
  `search_mode` varchar(20) NOT NULL DEFAULT 'semantic',
  `top_k` int(11) NOT NULL DEFAULT '5',
  `threshold` decimal(3,2) NOT NULL DEFAULT '0.60',
  `semantic_weight` decimal(3,2) NOT NULL DEFAULT '0.50',
  `keyword_weight` decimal(3,2) NOT NULL DEFAULT '0.50',
  `rerank_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `result_count` int(11) NOT NULL DEFAULT '0',
  `avg_score` decimal(5,4) NOT NULL DEFAULT '0.0000',
  `max_score` decimal(5,4) NOT NULL DEFAULT '0.0000',
  `search_duration` int(11) NOT NULL DEFAULT '0',
  `results` json DEFAULT NULL,
  `user_feedback` json DEFAULT NULL,
  `created_by` int(11) NOT NULL DEFAULT '0',
  `created_by_name` varchar(50) NOT NULL DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_record_id` (`record_id`),
  KEY `idx_kb_create` (`kb_id`,`create_time`),
  KEY `idx_mode_create` (`search_mode`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COMMENT='AI检索测试记录表';

CREATE TABLE `ai_session_tools` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `session_id` varchar(32) NOT NULL DEFAULT '' COMMENT '会话ID（关联 ai_chat_sessions.session_id）',
  `tool_id` int(11) NOT NULL DEFAULT '0' COMMENT '工具ID（关联 ai_tools.id）',
  `enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用：1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_session_tool` (`session_id`,`tool_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4113 DEFAULT CHARSET=utf8mb4 COMMENT='AI会话可用工具表';

CREATE TABLE `ai_tool_approvals` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `approval_id` varchar(32) NOT NULL DEFAULT '',
  `tool_id` int(11) DEFAULT NULL,
  `tool_name` varchar(100) NOT NULL DEFAULT '',
  `action_type` varchar(20) NOT NULL DEFAULT '',
  `tool_snapshot` json NOT NULL,
  `applicant_id` int(11) NOT NULL DEFAULT '0',
  `applicant_name` varchar(50) NOT NULL DEFAULT '',
  `apply_time` datetime NOT NULL,
  `apply_remark` varchar(500) DEFAULT NULL,
  `approver_id` int(11) DEFAULT NULL,
  `approver_name` varchar(50) DEFAULT NULL,
  `approval_time` datetime DEFAULT NULL,
  `approval_status` varchar(20) NOT NULL DEFAULT 'pending',
  `approval_comment` varchar(500) DEFAULT NULL,
  `reject_reason` varchar(500) DEFAULT NULL,
  `notified` tinyint(1) NOT NULL DEFAULT '0',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_approval_id` (`approval_id`),
  KEY `idx_tool_id` (`tool_id`),
  KEY `idx_status_create` (`approval_status`,`create_time`),
  KEY `idx_applicant_create` (`applicant_id`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI工具审批表';

CREATE TABLE `ai_tool_call_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `log_id` varchar(32) NOT NULL DEFAULT '' COMMENT '日志唯一标识（UUID去横线）',
  `tool_id` int(11) DEFAULT NULL COMMENT '工具ID',
  `tool_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工具名称（冗余）',
  `session_id` varchar(32) DEFAULT NULL COMMENT '会话ID',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '调用人ID',
  `user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '调用人姓名',
  `method` varchar(10) NOT NULL DEFAULT 'GET' COMMENT '请求方法',
  `api_path` varchar(255) NOT NULL DEFAULT '' COMMENT 'API路径',
  `request_headers` json DEFAULT NULL COMMENT '请求头(JSON)',
  `request_params` json DEFAULT NULL COMMENT '请求参数(JSON)',
  `response_status` int(11) DEFAULT NULL COMMENT '响应状态码',
  `response_headers` json DEFAULT NULL COMMENT '响应头(JSON)',
  `response_body` text COMMENT '响应体（超1MB自动截断）',
  `duration` int(11) DEFAULT NULL COMMENT '耗时（毫秒）',
  `request_size` int(11) NOT NULL DEFAULT '0' COMMENT '请求大小（字节）',
  `response_size` int(11) NOT NULL DEFAULT '0' COMMENT '响应大小（字节）',
  `status` varchar(20) NOT NULL DEFAULT 'success' COMMENT '状态：success/error/timeout',
  `error_message` text COMMENT '错误信息',
  `source` varchar(20) NOT NULL DEFAULT 'chat' COMMENT '来源：chat/test/workflow',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_log_id` (`log_id`),
  KEY `idx_tool_create` (`tool_id`,`create_time`),
  KEY `idx_user_create` (`user_id`,`create_time`),
  KEY `idx_status_create` (`status`,`create_time`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=111 DEFAULT CHARSET=utf8mb4 COMMENT='AI工具调用日志表';

CREATE TABLE `ai_tool_categories` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `category_key` varchar(30) NOT NULL DEFAULT '' COMMENT '分类键',
  `category_name` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名称',
  `icon` varchar(50) DEFAULT NULL,
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `is_system` tinyint(1) NOT NULL DEFAULT '0',
  `description` varchar(255) DEFAULT NULL,
  `tool_count` int(11) NOT NULL DEFAULT '0',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_category_key` (`category_key`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='AI工具分类字典';

CREATE TABLE `ai_tool_test_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `tool_id` int(11) NOT NULL DEFAULT '0' COMMENT '工具ID',
  `tool_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工具名称（冗余）',
  `request_params` json DEFAULT NULL COMMENT '请求参数(JSON)',
  `request_headers` json DEFAULT NULL COMMENT '请求头(JSON)',
  `response_status` int(11) DEFAULT NULL COMMENT '响应状态码',
  `response_time` int(11) NOT NULL DEFAULT '0' COMMENT '响应时间（毫秒）',
  `response_body` text COMMENT '响应体（完整内容）',
  `response_headers` json DEFAULT NULL COMMENT '响应头(JSON)',
  `error_message` text COMMENT '错误信息',
  `status` varchar(20) NOT NULL DEFAULT 'success' COMMENT '状态：success成功/error错误/timeout超时',
  `tester_id` int(11) NOT NULL DEFAULT '0' COMMENT '测试人ID',
  `tester_name` varchar(50) NOT NULL DEFAULT '' COMMENT '测试人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_tool_id` (`tool_id`),
  KEY `idx_tool_create` (`tool_id`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI工具测试日志表';

CREATE TABLE `ai_tools` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `tool_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工具名称（供AI识别调用，唯一）',
  `tool_display_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工具显示名称（前端展示）',
  `category` varchar(30) NOT NULL DEFAULT 'common' COMMENT '分类：device/safety/hr/warehouse/common',
  `description` text COMMENT '工具描述（供AI理解用途）',
  `method` varchar(10) NOT NULL DEFAULT 'GET' COMMENT '请求方法：GET/POST/PUT/DELETE',
  `api_path` varchar(255) NOT NULL DEFAULT '' COMMENT 'API路径',
  `headers` json DEFAULT NULL COMMENT '请求头配置(JSON)',
  `params_schema` json DEFAULT NULL COMMENT '参数定义(JSON Schema)',
  `response_schema` json DEFAULT NULL COMMENT '返回格式定义(JSON)',
  `requires_confirm` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否需要人工确认：1是 0否',
  `timeout` int(11) NOT NULL DEFAULT '30' COMMENT '超时时间（秒）',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '重试次数',
  `call_count` int(11) NOT NULL DEFAULT '0' COMMENT '调用次数',
  `last_call_time` datetime DEFAULT NULL COMMENT '最后调用时间',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `approval_status` varchar(20) NOT NULL DEFAULT 'active' COMMENT '审批状态：draft/approval_pending/active',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tool_name` (`tool_name`),
  KEY `idx_category` (`category`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COMMENT='AI工具表';

CREATE TABLE `ai_workflow_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `log_id` varchar(32) NOT NULL DEFAULT '' COMMENT '日志唯一标识(UUID)',
  `workflow_id` varchar(32) NOT NULL DEFAULT '' COMMENT '工作流ID',
  `workflow_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工作流名称（冗余）',
  `trigger_source` varchar(50) NOT NULL DEFAULT '' COMMENT '触发来源：manual/schedule/webhook/event',
  `trigger_user` varchar(50) NOT NULL DEFAULT '' COMMENT '触发人',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `duration` int(11) DEFAULT NULL COMMENT '执行耗时（毫秒）',
  `status` varchar(20) NOT NULL DEFAULT 'running' COMMENT '状态：running/success/failed',
  `node_executions` json DEFAULT NULL COMMENT '节点执行记录',
  `error_message` text COMMENT '错误信息',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_log_id` (`log_id`),
  KEY `idx_workflow_create` (`workflow_id`,`create_time`),
  KEY `idx_status_create` (`status`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='AI工作流运行日志表';

CREATE TABLE `ai_workflows` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `workflow_id` varchar(32) NOT NULL DEFAULT '' COMMENT '工作流唯一标识(UUID)',
  `workflow_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工作流名称',
  `description` varchar(255) NOT NULL DEFAULT '' COMMENT '工作流描述',
  `trigger_type` varchar(20) NOT NULL DEFAULT 'manual' COMMENT '触发方式：manual/schedule/webhook/event',
  `trigger_config` json DEFAULT NULL COMMENT '触发配置（定时cron/Webhook配置）',
  `config` json NOT NULL COMMENT '工作流配置（节点配置、连接关系）',
  `node_count` int(11) NOT NULL DEFAULT '0' COMMENT '节点数量',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `last_run_time` datetime DEFAULT NULL COMMENT '最近运行时间',
  `last_run_status` varchar(20) NOT NULL DEFAULT 'idle' COMMENT '最近运行状态：idle/running/success/failed',
  `run_count` int(11) NOT NULL DEFAULT '0' COMMENT '运行次数',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_workflow_id` (`workflow_id`),
  KEY `idx_creator_create` (`created_by`,`create_time`),
  KEY `idx_status` (`status`),
  KEY `idx_trigger_type` (`trigger_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='AI工作流表';

CREATE TABLE `alarm_history` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `alarm_type` varchar(20) NOT NULL COMMENT 'cpu/memory/disk/service',
  `alarm_level` varchar(10) NOT NULL DEFAULT 'warning' COMMENT 'info/warning/critical',
  `content` varchar(500) NOT NULL,
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0未处理 1已读 2已处理',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_type` (`alarm_type`),
  KEY `idx_status` (`status`),
  KEY `idx_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='告警历史表';

CREATE TABLE `app_banner_groups` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '组名称',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT '组编码',
  `position` varchar(50) NOT NULL DEFAULT '' COMMENT '位置标识',
  `style` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1全屏 2卡片 3沉浸式',
  `indicator_style` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1圆点 2数字 3缩略图 4无',
  `animation` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1滑动 2淡入淡出 3缩放 4翻转',
  `autoplay_interval` int(11) NOT NULL DEFAULT '3' COMMENT '自动轮播间隔(秒)',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1启用 0禁用',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='轮播组';

CREATE TABLE `app_banner_statistics` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `banner_id` int(11) NOT NULL DEFAULT '0' COMMENT '轮播图ID',
  `stat_date` date NOT NULL COMMENT '统计日期',
  `view_count` int(11) NOT NULL DEFAULT '0' COMMENT '展示次数',
  `click_count` int(11) NOT NULL DEFAULT '0' COMMENT '点击次数',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_banner_date` (`banner_id`,`stat_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='轮播图日统计';

CREATE TABLE `app_banners` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `group_id` int(11) NOT NULL DEFAULT '0' COMMENT '轮播组ID',
  `title` varchar(100) NOT NULL DEFAULT '' COMMENT '标题',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT '图片URL',
  `link_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1内链 2外链 3商品 4活动 5文章',
  `link_url` varchar(255) NOT NULL DEFAULT '' COMMENT '跳转链接',
  `platform` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0全部 1小程序 2H5 3公众号',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序权重',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1启用 0禁用',
  `publish_time` datetime DEFAULT NULL COMMENT '定时发布时间',
  `unpublish_time` datetime DEFAULT NULL COMMENT '定时下架时间',
  `view_count` int(11) NOT NULL DEFAULT '0' COMMENT '展示次数',
  `click_count` int(11) NOT NULL DEFAULT '0' COMMENT '点击次数',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_group_id` (`group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='轮播图';

CREATE TABLE `app_functions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '功能名称',
  `code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '功能编码',
  `icon` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '图标类名',
  `path_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联路径ID',
  `permission` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '权限标识',
  `display_location` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'both' COMMENT '显示位置:home=首页 profile=我的 both=都显示',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序权重',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1=启用 0=禁用',
  `visible_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'all' COMMENT '可见性类型：all/role/user',
  `visible_targets` text COLLATE utf8mb4_unicode_ci COMMENT '可见目标（JSON数组：角色ID或用户ID）',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_path_id` (`path_id`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='功能配置表';

CREATE TABLE `app_mobile_pages` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `page_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '类型:1=登录页 2=启动页',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '方案名称',
  `description` varchar(255) NOT NULL DEFAULT '' COMMENT '方案描述',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态:0=草稿 1=已发布 2=已下架',
  `is_active` tinyint(1) NOT NULL DEFAULT '0' COMMENT '激活',
  `start_time` datetime DEFAULT NULL,
  `end_time` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `tech_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `tech_primary_color` varchar(20) NOT NULL DEFAULT '#0b1a3a',
  `tech_secondary_color` varchar(20) NOT NULL DEFAULT '#1a1040',
  `tech_grid_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `tech_grid_size` int(11) NOT NULL DEFAULT '60',
  `tech_grid_opacity` decimal(4,2) NOT NULL DEFAULT '0.08',
  `tech_particle_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `tech_particle_color` varchar(20) NOT NULL DEFAULT '#00b4ff',
  `tech_particle_count` int(11) NOT NULL DEFAULT '100',
  `tech_particle_speed` decimal(3,1) NOT NULL DEFAULT '0.4',
  `tech_particle_distance` int(11) NOT NULL DEFAULT '80',
  `tech_glow_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `tech_glow1_color` varchar(40) NOT NULL DEFAULT 'rgba(0,180,255,0.06)',
  `tech_glow2_color` varchar(40) NOT NULL DEFAULT 'rgba(100,50,255,0.04)',
  `tech_lightband_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `tech_lightband_count` int(11) NOT NULL DEFAULT '3',
  `tech_lightband_speed` int(11) NOT NULL DEFAULT '10',
  `tech_lightband_opacity` decimal(4,2) NOT NULL DEFAULT '0.06',
  `mine_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `mine_primary_color` varchar(20) NOT NULL DEFAULT '#2d1f2a',
  `mine_secondary_color` varchar(20) NOT NULL DEFAULT '#140c06',
  `mine_texture_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `mine_texture_type` tinyint(1) NOT NULL DEFAULT '1',
  `mine_texture_opacity` decimal(4,2) NOT NULL DEFAULT '0.15',
  `mine_particle_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `mine_particle_color_scheme` tinyint(1) NOT NULL DEFAULT '1',
  `mine_particle_count` int(11) NOT NULL DEFAULT '50',
  `mine_particle_min_size` int(11) NOT NULL DEFAULT '3',
  `mine_particle_max_size` int(11) NOT NULL DEFAULT '8',
  `mine_particle_speed` decimal(3,1) NOT NULL DEFAULT '0.4',
  `mine_particle_shape` tinyint(1) NOT NULL DEFAULT '3',
  `mine_glow_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `mine_glow1_color` varchar(40) NOT NULL DEFAULT 'rgba(255,160,50,0.08)',
  `mine_glow2_color` varchar(40) NOT NULL DEFAULT 'rgba(200,120,40,0.06)',
  `logo` varchar(255) NOT NULL DEFAULT '',
  `sys_name` varchar(50) NOT NULL DEFAULT '华能科技',
  `sys_name_color` varchar(20) NOT NULL DEFAULT '#ffffff',
  `subtitle` varchar(100) NOT NULL DEFAULT '智能管控平台',
  `subtitle_color` varchar(40) NOT NULL DEFAULT 'rgba(255,255,255,0.6)',
  `brand_gradient_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `welcome_title` varchar(100) NOT NULL DEFAULT '登录工业控制平台',
  `title_highlight` varchar(50) NOT NULL DEFAULT '工业控制平台',
  `highlight_gradient_start` varchar(20) NOT NULL DEFAULT '#00d4ff',
  `highlight_gradient_end` varchar(20) NOT NULL DEFAULT '#ff8c00',
  `status_text` varchar(100) NOT NULL DEFAULT '系统运行中 · 混合加密通道',
  `status_dot_color` varchar(20) NOT NULL DEFAULT '#00d4ff',
  `content_vertical_position` int(11) NOT NULL DEFAULT '50',
  `btn_text` varchar(20) NOT NULL DEFAULT '微信一键登录',
  `btn_width` int(11) NOT NULL DEFAULT '100',
  `btn_height` int(11) NOT NULL DEFAULT '56',
  `btn_bg_color` varchar(40) NOT NULL DEFAULT 'rgba(255,255,255,0.04)',
  `btn_border_color` varchar(40) NOT NULL DEFAULT 'rgba(255,255,255,0.06)',
  `btn_text_color` varchar(20) NOT NULL DEFAULT '#ffffff',
  `btn_hover_bg_color` varchar(40) NOT NULL DEFAULT 'rgba(255,255,255,0.08)',
  `btn_hover_border_color` varchar(40) NOT NULL DEFAULT 'rgba(0,212,255,0.15)',
  `btn_radius` int(11) NOT NULL DEFAULT '12',
  `btn_glass_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `btn_glow_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `btn_glow_color` varchar(20) NOT NULL DEFAULT '#00d4ff',
  `show_alt_login` tinyint(1) NOT NULL DEFAULT '1',
  `alt_login_color` varchar(40) NOT NULL DEFAULT 'rgba(255,255,255,0.2)',
  `alt_login_hover_color` varchar(40) NOT NULL DEFAULT 'rgba(0,212,255,0.5)',
  `show_agreement` tinyint(1) NOT NULL DEFAULT '1',
  `agreement_text_color` varchar(40) NOT NULL DEFAULT 'rgba(255,255,255,0.2)',
  `agreement_link_color` varchar(40) NOT NULL DEFAULT 'rgba(255,255,255,0.3)',
  `agreement_link_hover_color` varchar(20) NOT NULL DEFAULT '#00d4ff',
  `checkbox_border_color` varchar(40) NOT NULL DEFAULT 'rgba(255,255,255,0.1)',
  `checkbox_checked_color` varchar(40) NOT NULL DEFAULT 'rgba(0,212,255,0.1)',
  `transition_height` int(11) NOT NULL DEFAULT '10',
  `transition_color1` varchar(20) NOT NULL DEFAULT '#1a1040',
  `transition_color2` varchar(20) NOT NULL DEFAULT '#2d1f2a',
  `transition_smoothness` decimal(3,1) NOT NULL DEFAULT '0.5',
  `splash_type` tinyint(1) NOT NULL DEFAULT '1',
  `splash_image` varchar(255) NOT NULL DEFAULT '',
  `splash_video` varchar(255) NOT NULL DEFAULT '',
  `splash_bg_color` varchar(20) NOT NULL DEFAULT '#060b18',
  `splash_duration` int(11) NOT NULL DEFAULT '3',
  `splash_can_skip` tinyint(1) NOT NULL DEFAULT '1',
  `splash_skip_style` tinyint(1) NOT NULL DEFAULT '1',
  `splash_skip_text` varchar(20) NOT NULL DEFAULT '跳过',
  `splash_skip_color` varchar(40) NOT NULL DEFAULT 'rgba(255,255,255,0.6)',
  `splash_skip_position` tinyint(1) NOT NULL DEFAULT '1',
  `splash_show_text` tinyint(1) NOT NULL DEFAULT '0',
  `splash_text` varchar(200) NOT NULL DEFAULT '',
  `splash_text_color` varchar(20) NOT NULL DEFAULT '#ffffff',
  `splash_text_position` tinyint(1) NOT NULL DEFAULT '1',
  `splash_text_size` int(11) NOT NULL DEFAULT '24',
  PRIMARY KEY (`id`),
  KEY `idx_type_active` (`page_type`,`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='移动端页面配置表';

CREATE TABLE `app_paths` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '路径名称',
  `path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '路径地址',
  `page_key` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '关联DIY页面标识',
  `platform` tinyint(1) NOT NULL DEFAULT '0' COMMENT '平台：0=全部 1=小程序 2=H5 3=公众号',
  `page_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '页面类型：1=普通页面 2=Tab页面',
  `require_auth` tinyint(1) NOT NULL DEFAULT '1' COMMENT '需要登录：1=需要 0=不需要',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1=启用 0=禁用',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_path` (`path`)
) ENGINE=InnoDB AUTO_INCREMENT=82 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='移动端路径管理';

CREATE TABLE `app_splash_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1图片 2视频 3图片+视频',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT '图片URL',
  `video` varchar(255) NOT NULL DEFAULT '' COMMENT '视频URL',
  `background_color` varchar(20) NOT NULL DEFAULT '#ffffff' COMMENT '背景色',
  `duration` int(11) NOT NULL DEFAULT '3' COMMENT '显示时长(秒)',
  `skip_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否可跳过',
  `skip_style` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1文字 2图标 3无',
  `skip_text` varchar(10) NOT NULL DEFAULT '跳过' COMMENT '跳过按钮文字',
  `skip_color` varchar(20) NOT NULL DEFAULT '#ffffff' COMMENT '跳过按钮颜色',
  `skip_position` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1右下角 2右上角 3底部居中',
  `show_text` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否显示文字',
  `text_content` text COMMENT '文字内容',
  `text_color` varchar(20) NOT NULL DEFAULT '#ffffff' COMMENT '文字颜色',
  `text_position` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1居中 2底部 3顶部',
  `text_size` int(11) NOT NULL DEFAULT '24' COMMENT '文字大小(px)',
  `enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用',
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='启动页配置';

CREATE TABLE `app_tab_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tab_key` varchar(50) NOT NULL DEFAULT '',
  `title` varchar(50) NOT NULL DEFAULT '',
  `icon` varchar(255) NOT NULL DEFAULT '',
  `icon_active` varchar(255) NOT NULL DEFAULT '',
  `path` varchar(255) NOT NULL DEFAULT '',
  `page_path` varchar(255) NOT NULL DEFAULT '',
  `sort` int(11) NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `require_login` tinyint(1) NOT NULL DEFAULT '1',
  `roles` text,
  `badge` varchar(20) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tab_key` (`tab_key`),
  KEY `idx_status_sort` (`status`,`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='移动端底部导航配置';

CREATE TABLE `approval_common_phrase` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户ID（0=系统默认）',
  `content` varchar(255) NOT NULL DEFAULT '' COMMENT '常用语内容',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `use_count` int(11) NOT NULL DEFAULT '0' COMMENT '使用次数',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='审批常用语表';

CREATE TABLE `approval_flow` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `biz_type` varchar(50) NOT NULL DEFAULT '' COMMENT '业务类型编码（purchase_request/purchase_order/contract/leave/hazard/report）',
  `biz_name` varchar(50) NOT NULL DEFAULT '' COMMENT '业务类型名称',
  `module_name` varchar(50) NOT NULL DEFAULT '' COMMENT '所属模块名称',
  `approval_mode` tinyint(1) NOT NULL DEFAULT '1' COMMENT '审批模式：1单人 2会签 3或签 4依次',
  `timeout_hours` int(11) NOT NULL DEFAULT '24' COMMENT '审批时限（小时）',
  `node_config` text COMMENT '节点配置JSON：[{"name":"部门审批"},{"name":"经理审批"}]',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_biz_type` (`biz_type`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COMMENT='审批流程定义表';

CREATE TABLE `approval_history` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `instance_id` int(11) NOT NULL DEFAULT '0' COMMENT '审批实例ID',
  `node_index` int(11) NOT NULL DEFAULT '0' COMMENT '节点序号',
  `action` varchar(20) NOT NULL DEFAULT '' COMMENT '操作类型：submit/approve/reject/transfer/urge/batch',
  `action_label` varchar(20) NOT NULL DEFAULT '' COMMENT '操作类型标签',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `result` varchar(20) NOT NULL DEFAULT '' COMMENT '操作结果：pass/reject/transfer/urge',
  `comment` text COMMENT '审批意见',
  `notify_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '通知状态：0未发送 1已发送',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_instance` (`instance_id`)
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COMMENT='审批历史表';

CREATE TABLE `approval_instance` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `instance_no` varchar(32) NOT NULL DEFAULT '' COMMENT '审批实例编号 AP+YYYYMMDD+4位流水',
  `flow_id` int(11) NOT NULL DEFAULT '0' COMMENT '流程定义ID',
  `biz_type` varchar(50) NOT NULL DEFAULT '' COMMENT '业务类型',
  `biz_id` int(11) NOT NULL DEFAULT '0' COMMENT '业务单据ID（0=演示数据）',
  `business_no` varchar(50) NOT NULL DEFAULT '' COMMENT '业务编号',
  `business_title` varchar(255) NOT NULL DEFAULT '' COMMENT '业务标题',
  `applicant_id` int(11) NOT NULL DEFAULT '0' COMMENT '申请人ID',
  `applicant_name` varchar(50) NOT NULL DEFAULT '' COMMENT '申请人姓名（冗余）',
  `current_node_index` int(11) NOT NULL DEFAULT '0' COMMENT '当前节点序号（从0开始）',
  `current_node_name` varchar(50) NOT NULL DEFAULT '' COMMENT '当前节点名称',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1审批中 2已通过 3已驳回 4已撤销',
  `approval_mode` tinyint(1) NOT NULL DEFAULT '1' COMMENT '审批模式：1单人 2会签 3或签 4依次',
  `mode_label` varchar(20) NOT NULL DEFAULT '' COMMENT '审批模式标签',
  `urgent` tinyint(1) NOT NULL DEFAULT '0' COMMENT '紧急程度：0普通 1紧急 2特急',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `timeout_at` datetime DEFAULT NULL COMMENT '审批时限（超时判定）',
  `finish_time` datetime DEFAULT NULL COMMENT '完成时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_instance_no` (`instance_no`),
  KEY `idx_status` (`status`),
  KEY `idx_biz_type` (`biz_type`),
  KEY `idx_applicant` (`applicant_id`),
  KEY `idx_timeout` (`timeout_at`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COMMENT='审批实例表';

CREATE TABLE `approval_node` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `instance_id` int(11) NOT NULL DEFAULT '0' COMMENT '审批实例ID',
  `node_index` int(11) NOT NULL DEFAULT '0' COMMENT '节点序号',
  `node_name` varchar(50) NOT NULL DEFAULT '' COMMENT '节点名称',
  `approver_id` int(11) NOT NULL DEFAULT '0' COMMENT '审批人ID',
  `approver_name` varchar(50) NOT NULL DEFAULT '' COMMENT '审批人姓名（冗余）',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0待审 1已通过 2已驳回',
  `pass_count` int(11) NOT NULL DEFAULT '0' COMMENT '会签已通过人数',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '节点备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_instance` (`instance_id`)
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COMMENT='审批节点执行表';

CREATE TABLE `approval_notify_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `inmail` tinyint(1) NOT NULL DEFAULT '1' COMMENT '站内信通知（默认开启，不可关）',
  `enable_site` tinyint(1) NOT NULL DEFAULT '1' COMMENT '站内信通知（默认开，不可关闭）',
  `enable_email` tinyint(1) NOT NULL DEFAULT '0' COMMENT '邮件通知开关',
  `enable_sms` tinyint(1) NOT NULL DEFAULT '0' COMMENT '短信通知开关',
  `email_address` varchar(100) DEFAULT NULL COMMENT '接收通知邮箱',
  `mobile` varchar(20) DEFAULT NULL COMMENT '接收通知手机号',
  `scene_todo` tinyint(1) NOT NULL DEFAULT '1' COMMENT '待办提醒',
  `scene_urge` tinyint(1) NOT NULL DEFAULT '1' COMMENT '催办提醒',
  `scene_approve` tinyint(1) NOT NULL DEFAULT '1' COMMENT '通过通知',
  `scene_reject` tinyint(1) NOT NULL DEFAULT '1' COMMENT '驳回通知',
  `scene_transfer` tinyint(1) NOT NULL DEFAULT '1' COMMENT '转办通知',
  `scene_overdue` tinyint(1) NOT NULL DEFAULT '1' COMMENT '超时提醒',
  `email_switch` tinyint(1) NOT NULL DEFAULT '0' COMMENT '邮件通知开关',
  `email` varchar(100) DEFAULT NULL COMMENT '邮件地址',
  `sms_switch` tinyint(1) NOT NULL DEFAULT '0' COMMENT '短信通知开关',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号码',
  `scenes` varchar(255) NOT NULL DEFAULT 'todo,urge,approve,reject,transfer,timeout' COMMENT '通知场景（逗号分隔）',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='审批通知配置表';

CREATE TABLE `approval_proxy` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `proxy_no` varchar(50) NOT NULL DEFAULT '' COMMENT '代理编号 AP+YYYYMMDD+4位流水',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '被代理人ID',
  `user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '被代理人姓名（冗余）',
  `proxy_user_id` int(11) NOT NULL DEFAULT '0' COMMENT '代理人ID',
  `proxy_user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '代理人姓名（冗余）',
  `start_time` datetime DEFAULT NULL COMMENT '代理开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '代理结束时间',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0待生效 1生效中 2已过期 3已取消',
  `reason` varchar(200) DEFAULT NULL COMMENT '代理原因',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proxy_no` (`proxy_no`),
  KEY `idx_user` (`user_id`),
  KEY `idx_proxy_user` (`proxy_user_id`),
  KEY `idx_time` (`start_time`,`end_time`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='审批代理记录表';

CREATE TABLE `approval_urge_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `instance_id` int(11) NOT NULL DEFAULT '0' COMMENT '审批实例ID',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '催办发起人ID',
  `target_id` int(11) NOT NULL DEFAULT '0' COMMENT '被催办人ID',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_instance_user` (`instance_id`,`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='催办日志表';

CREATE TABLE `articles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL DEFAULT '' COMMENT '标题',
  `content` longtext COMMENT '内容',
  `cover_image` varchar(255) DEFAULT '' COMMENT '封面图',
  `category_id` int(11) NOT NULL DEFAULT '0' COMMENT '分类ID',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1发布 0草稿',
  `sort` int(11) NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='文章表';

CREATE TABLE `assessment_appeals` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `deduction_id` int(11) NOT NULL DEFAULT '0' COMMENT '扣分明细ID',
  `employee_id` int(11) NOT NULL DEFAULT '0' COMMENT '申诉人ID',
  `appeal_reason` text COMMENT '申诉理由',
  `attachments` varchar(500) DEFAULT NULL COMMENT '附件',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0待处理 1已通过 2已驳回',
  `handler_id` int(11) DEFAULT NULL COMMENT '处理人ID',
  `handler_reply` text COMMENT '处理意见',
  `created_at` datetime DEFAULT NULL,
  `handled_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_deduction` (`deduction_id`),
  KEY `idx_employee` (`employee_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='考核申诉记录表';

CREATE TABLE `assessment_auto_deduct_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `task_id` int(11) NOT NULL DEFAULT '0' COMMENT '考核任务ID',
  `indicator_id` int(11) NOT NULL DEFAULT '0' COMMENT '指标ID',
  `employee_id` int(11) NOT NULL DEFAULT '0' COMMENT '员工ID',
  `executed_at` datetime DEFAULT NULL COMMENT '执行时间',
  `source_count` int(11) NOT NULL DEFAULT '0' COMMENT '违规次数/异常条数',
  `deduct_score` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '本次扣分',
  `source_detail` text COMMENT '具体来源记录(JSON)',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1成功 0失败',
  `error_msg` varchar(255) DEFAULT NULL COMMENT '错误信息',
  PRIMARY KEY (`id`),
  KEY `idx_task` (`task_id`),
  KEY `idx_employee` (`employee_id`),
  KEY `idx_indicator` (`indicator_id`)
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COMMENT='自动扣分执行日志表';

CREATE TABLE `assessment_deductions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `task_id` int(11) NOT NULL DEFAULT '0' COMMENT '考核任务ID',
  `indicator_id` int(11) NOT NULL DEFAULT '0' COMMENT '指标ID(快照中的ID)',
  `employee_id` int(11) NOT NULL DEFAULT '0' COMMENT '被考核人ID',
  `deduct_score` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '本次扣分分值',
  `reason` varchar(255) NOT NULL COMMENT '扣分原因',
  `data_source_type` tinyint(1) NOT NULL DEFAULT '2' COMMENT '1系统自动 2手动录入',
  `data_source_detail` varchar(255) DEFAULT NULL COMMENT '数据来源明细，如工单号/考勤日期',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0待确认 1已确认 2已申诉 3已驳回',
  `confirm_time` datetime DEFAULT NULL COMMENT '员工确认时间',
  `attachments` varchar(500) DEFAULT NULL COMMENT '附件(JSON数组)',
  `created_by` int(11) DEFAULT NULL COMMENT '录入人ID(手动录入时)',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_task` (`task_id`),
  KEY `idx_employee` (`employee_id`),
  KEY `idx_indicator` (`indicator_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COMMENT='考核扣分明细表';

CREATE TABLE `assessment_indicator_library` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT '指标名称',
  `category` varchar(50) DEFAULT NULL COMMENT '所属大类：履职情况/公共量化指标/安全/纪律行为规范',
  `default_score` decimal(5,2) NOT NULL DEFAULT '5.00' COMMENT '建议分值',
  `default_data_source` varchar(50) DEFAULT NULL COMMENT '建议数据源：attendance/production/quality/maintenance/training/exam/manual',
  `default_deduct_rule` text COMMENT '默认扣分规则（JSON）',
  `usage_count` int(11) NOT NULL DEFAULT '0' COMMENT '被模板引用次数',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COMMENT='全局指标库表';

CREATE TABLE `assessment_tasks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `template_id` int(11) NOT NULL DEFAULT '0' COMMENT '来源模板ID',
  `period` varchar(20) NOT NULL COMMENT '考核周期，如 2026-08',
  `employee_id` int(11) NOT NULL DEFAULT '0' COMMENT '被考核人ID(employee_profiles.id)',
  `department_id` int(11) DEFAULT NULL COMMENT '所属部门ID',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0待评分 1待确认 2已确认 3已审批 4已结束',
  `total_score` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '最终得分(百分制)',
  `grade` varchar(10) DEFAULT NULL COMMENT '等级 A/B/C/D',
  `deduction_amount` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '考核扣款金额',
  `reward_amount` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '考核奖励金额',
  `evaluator_id` int(11) DEFAULT NULL COMMENT '考核人ID(班组长/车间主任)',
  `approver_id` int(11) DEFAULT NULL COMMENT '审批人ID',
  `remark` varchar(500) DEFAULT NULL COMMENT '评语/备注',
  `snapshot` text COMMENT '指标快照(JSON，从模板复制)',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_employee_period` (`employee_id`,`period`),
  KEY `idx_period` (`period`),
  KEY `idx_status` (`status`),
  KEY `idx_template` (`template_id`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COMMENT='考核任务主表';

CREATE TABLE `assessment_template_indicators` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `template_id` int(11) NOT NULL COMMENT '模板ID',
  `indicator_id` int(11) DEFAULT NULL COMMENT '指标库ID（自定义指标为NULL）',
  `parent_id` int(11) NOT NULL DEFAULT '0' COMMENT '父指标ID（0为顶级/分组）',
  `name` varchar(100) NOT NULL COMMENT '指标名称',
  `category` varchar(50) DEFAULT NULL COMMENT '所属大类',
  `score` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '该项分值',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序（同一父级下）',
  `data_source` varchar(50) DEFAULT NULL COMMENT '数据源',
  `data_source_config` text COMMENT '数据源配置（JSON）',
  `scoring_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '评分类型：1扣分制 2加分制 3等级制',
  `auto_deduct_rule` text COMMENT '自动扣分规则（JSON）',
  `is_custom` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否自定义指标（非指标库引用）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_template` (`template_id`),
  KEY `idx_parent` (`parent_id`),
  KEY `idx_indicator` (`indicator_id`)
) ENGINE=InnoDB AUTO_INCREMENT=83 DEFAULT CHARSET=utf8mb4 COMMENT='模板指标关联表';

CREATE TABLE `assessment_templates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT '模板名称',
  `code` varchar(50) NOT NULL COMMENT '模板编码，唯一',
  `category` varchar(50) NOT NULL DEFAULT '' COMMENT '适用岗位类别：操作工/维修工/质检员/班组长/管理人员',
  `period_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '周期类型：1月度 2季度 3年度 4半年度',
  `total_score` decimal(5,2) NOT NULL DEFAULT '100.00' COMMENT '模板总分',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认模板',
  `version` int(11) NOT NULL DEFAULT '1' COMMENT '版本号，每次修改+1',
  `description` varchar(500) DEFAULT NULL COMMENT '模板描述',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_category` (`category`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COMMENT='考核模板表';

CREATE TABLE `asset_apply` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `apply_no` varchar(50) NOT NULL DEFAULT '' COMMENT '申请单号 AA+日期+流水',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '申请人ID',
  `user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '申请人姓名',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '申请部门ID',
  `asset_archive_id` int(11) NOT NULL DEFAULT '0' COMMENT '资产档案ID',
  `asset_name` varchar(100) NOT NULL DEFAULT '' COMMENT '资产名称(冗余)',
  `asset_no` varchar(50) NOT NULL DEFAULT '' COMMENT '资产编号(冗余)',
  `specification` varchar(100) NOT NULL DEFAULT '' COMMENT '规格型号(冗余)',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位(冗余)',
  `apply_quantity` decimal(15,2) NOT NULL DEFAULT '1.00' COMMENT '申请数量',
  `original_value` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '资产原值(冗余)',
  `purpose` varchar(500) NOT NULL DEFAULT '' COMMENT '用途说明',
  `purchase_order_no` varchar(50) DEFAULT NULL COMMENT '关联采购订单编号',
  `supplier_name` varchar(100) DEFAULT NULL COMMENT '供应商名称',
  `remark` varchar(200) NOT NULL DEFAULT '' COMMENT '备注',
  `approval_instance_id` int(11) NOT NULL DEFAULT '0' COMMENT '审批中心实例ID',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0=草稿 1=审批中 2=已通过 3=已驳回 4=已取消',
  `personal_asset_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联个人资产ID',
  `reject_reason` varchar(255) NOT NULL DEFAULT '' COMMENT '驳回原因',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_apply_no` (`apply_no`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_approval_instance_id` (`approval_instance_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='资产领用申请表';

CREATE TABLE `asset_archive` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `asset_no` varchar(50) NOT NULL DEFAULT '' COMMENT '资产编号',
  `asset_name` varchar(100) NOT NULL DEFAULT '' COMMENT '资产名称',
  `category_id` int(11) NOT NULL DEFAULT '0' COMMENT '分类ID',
  `specification` varchar(100) NOT NULL DEFAULT '' COMMENT '规格型号',
  `brand` varchar(50) NOT NULL DEFAULT '' COMMENT '品牌',
  `serial_no` varchar(100) NOT NULL DEFAULT '' COMMENT '序列号',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位',
  `quantity` decimal(15,2) NOT NULL DEFAULT '1.00' COMMENT '总数量',
  `unit_price` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '单价',
  `total_value` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '总价值',
  `purchase_date` date DEFAULT NULL COMMENT '购入日期',
  `supplier_id` int(11) NOT NULL DEFAULT '0' COMMENT '供应商ID',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '使用部门ID',
  `current_user_id` int(11) DEFAULT NULL COMMENT '当前使用人ID',
  `asset_status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1=正常 2=维修中 3=闲置 4=待报废 5=已报废',
  `depreciation_rate` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '年折旧率(%)',
  `depreciation_method` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=直线法 2=加速法',
  `depreciation_months` int(11) NOT NULL DEFAULT '0' COMMENT '折旧月数',
  `accumulated_depreciation` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '累计折旧',
  `current_net_value` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '当前净值',
  `depreciated_months` int(11) NOT NULL DEFAULT '0' COMMENT '已折旧月数',
  `residual_value` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '残值',
  `purchase_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '采购单号',
  `warranty_expire` date DEFAULT NULL COMMENT '保修到期日',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1=启用 0=停用',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_asset_no` (`asset_no`),
  KEY `idx_asset_status` (`asset_status`),
  KEY `idx_current_user` (`current_user_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COMMENT='资产档案表（固定资产）';

CREATE TABLE `asset_category` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名称',
  `parent_id` int(11) NOT NULL DEFAULT '0' COMMENT '父分类ID',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=停用 1=启用',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='资产分类表';

CREATE TABLE `asset_consume_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` int(11) NOT NULL DEFAULT '0',
  `user_id` int(11) NOT NULL DEFAULT '0',
  `consume_quantity` decimal(15,2) NOT NULL DEFAULT '0.00',
  `reason` varchar(255) NOT NULL DEFAULT '',
  `related_order_no` varchar(50) NOT NULL DEFAULT '',
  `work_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工单ID',
  `device_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联设备ID',
  `remark` varchar(255) NOT NULL DEFAULT '',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_asset` (`asset_id`),
  KEY `idx_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='个人资产消耗记录';

CREATE TABLE `asset_depreciation_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` int(11) NOT NULL DEFAULT '0' COMMENT '资产ID',
  `asset_no` varchar(50) NOT NULL DEFAULT '' COMMENT '资产编号',
  `asset_name` varchar(100) NOT NULL DEFAULT '' COMMENT '资产名称',
  `depreciation_month` varchar(7) NOT NULL DEFAULT '' COMMENT '折旧月份(YYYY-MM)',
  `original_value` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '原始价值',
  `depreciation_rate` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '当月折旧率(%)',
  `depreciation_amount` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '当月折旧金额',
  `accumulated_depreciation` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '累计折旧',
  `net_value` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '净值',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_asset_id` (`asset_id`),
  KEY `idx_depreciation_month` (`depreciation_month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='资产折旧记录表';

CREATE TABLE `asset_return_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` int(11) NOT NULL DEFAULT '0',
  `user_id` int(11) NOT NULL DEFAULT '0',
  `return_quantity` decimal(15,2) NOT NULL DEFAULT '0.00',
  `reason` varchar(255) NOT NULL DEFAULT '',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0=待审核 1=已退还',
  `remark` varchar(255) NOT NULL DEFAULT '',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_asset` (`asset_id`),
  KEY `idx_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='个人资产退还记录';

CREATE TABLE `asset_transfer_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `transfer_no` varchar(50) NOT NULL DEFAULT '' COMMENT '调拨单号 PT+日期+流水',
  `asset_id` int(11) NOT NULL DEFAULT '0',
  `from_user_id` int(11) NOT NULL DEFAULT '0',
  `to_user_id` int(11) NOT NULL DEFAULT '0',
  `initiator_id` int(11) NOT NULL DEFAULT '0' COMMENT '发起人ID',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=待确认 1=已确认 2=已拒绝',
  `transfer_quantity` decimal(15,2) NOT NULL DEFAULT '0.00',
  `purpose` varchar(255) NOT NULL DEFAULT '' COMMENT '用途/原因',
  `from_name` varchar(50) NOT NULL DEFAULT '' COMMENT '调出人姓名',
  `to_name` varchar(50) NOT NULL DEFAULT '' COMMENT '调入人姓名',
  `asset_name` varchar(100) NOT NULL DEFAULT '' COMMENT '资产名称（冗余）',
  `asset_code` varchar(50) NOT NULL DEFAULT '' COMMENT '资产编码（冗余）',
  `specification` varchar(100) NOT NULL DEFAULT '' COMMENT '规格型号（冗余）',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位（冗余）',
  `confirm_user_id` int(11) NOT NULL DEFAULT '0' COMMENT '确认人ID',
  `confirm_time` datetime DEFAULT NULL COMMENT '确认时间',
  `reject_reason` varchar(255) NOT NULL DEFAULT '' COMMENT '拒绝原因',
  `remark` varchar(255) NOT NULL DEFAULT '',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_asset` (`asset_id`),
  KEY `idx_from` (`from_user_id`),
  KEY `idx_to` (`to_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='个人资产调拨记录';

CREATE TABLE `attendance_points` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `point_name` varchar(100) NOT NULL COMMENT '打卡点名称',
  `address` varchar(255) NOT NULL DEFAULT '' COMMENT '详细地址',
  `latitude` decimal(10,7) NOT NULL COMMENT '纬度',
  `longitude` decimal(10,7) NOT NULL COMMENT '经度',
  `radius` int(11) NOT NULL DEFAULT '300' COMMENT '有效半径（米），范围100-3000',
  `start_time` time DEFAULT NULL COMMENT '打卡开始时间',
  `end_time` time DEFAULT NULL COMMENT '打卡结束时间',
  `weekdays` varchar(20) NOT NULL DEFAULT '1,2,3,4,5' COMMENT '有效星期：1-7（1=周一）',
  `department_ids` text COMMENT '关联部门ID列表（JSON数组，空=全部部门）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序（数字越小越靠前）',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_sort` (`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='考勤打卡点配置';

CREATE TABLE `attendance_rules` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rule_name` varchar(100) NOT NULL COMMENT '规则名称',
  `rule_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=默认规则 1=自定义规则',
  `department_ids` text COMMENT '关联部门ID列表（JSON数组，空=全部部门）',
  `checkin_count` tinyint(1) NOT NULL DEFAULT '2' COMMENT '每日打卡次数：1/2/4',
  `morning_start` time DEFAULT '08:00:00' COMMENT '上午上班时间',
  `morning_end` time DEFAULT '12:00:00' COMMENT '上午下班时间',
  `afternoon_start` time DEFAULT '13:30:00' COMMENT '下午上班时间',
  `afternoon_end` time DEFAULT '18:00:00' COMMENT '下午下班时间',
  `advance_minutes` int(11) NOT NULL DEFAULT '30' COMMENT '可提前打卡分钟数（上班前）',
  `delay_minutes` int(11) NOT NULL DEFAULT '30' COMMENT '可延迟打卡分钟数（下班后）',
  `grace_late_minutes` int(11) NOT NULL DEFAULT '5' COMMENT '迟到宽限分钟数',
  `grace_early_minutes` int(11) NOT NULL DEFAULT '5' COMMENT '早退宽限分钟数',
  `weekdays` varchar(20) NOT NULL DEFAULT '1,2,3,4,5' COMMENT '适用工作日（1-7）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=停用 1=启用',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序（数字越小越靠前）',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_sort` (`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='打卡规则配置表';

CREATE TABLE `business_contract_approvals` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `contract_id` int(11) NOT NULL DEFAULT '0' COMMENT '合同ID',
  `approver_id` int(11) NOT NULL DEFAULT '0' COMMENT '审批人ID',
  `approver_name` varchar(50) NOT NULL DEFAULT '' COMMENT '审批人姓名（冗余）',
  `approval_result` varchar(20) NOT NULL DEFAULT '' COMMENT '审批结果：pass/reject',
  `approval_comment` varchar(500) DEFAULT NULL COMMENT '审批意见',
  `approval_time` datetime DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_contract_id` (`contract_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='合同审批记录表';

CREATE TABLE `business_contract_changes` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `contract_id` int(11) NOT NULL DEFAULT '0' COMMENT '合同ID',
  `change_type` varchar(20) NOT NULL DEFAULT '' COMMENT '变更类型：amount/date/content/status/renew/terminate',
  `old_value` text COMMENT '变更前值',
  `new_value` text COMMENT '变更后值',
  `change_reason` varchar(500) DEFAULT NULL COMMENT '变更原因',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_contract_id` (`contract_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='合同变更记录表';

CREATE TABLE `business_contract_clauses` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `contract_id` int(11) NOT NULL DEFAULT '0' COMMENT '合同ID',
  `clause_title` varchar(200) NOT NULL DEFAULT '' COMMENT '条款标题',
  `clause_content` text NOT NULL COMMENT '条款内容',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_contract_id` (`contract_id`)
) ENGINE=InnoDB AUTO_INCREMENT=389 DEFAULT CHARSET=utf8mb4 COMMENT='合同条款表';

CREATE TABLE `business_contract_template_variables` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `var_key` varchar(50) NOT NULL DEFAULT '' COMMENT '变量键（如 customer_name）',
  `var_name` varchar(100) NOT NULL DEFAULT '' COMMENT '变量名称',
  `var_category` varchar(30) NOT NULL DEFAULT 'basic' COMMENT '分类：basic/customer/supplier/items/amount/system/custom',
  `var_type` varchar(20) NOT NULL DEFAULT 'string' COMMENT '类型：string/number/date/amount/html',
  `description` varchar(255) DEFAULT NULL COMMENT '描述说明',
  `example` varchar(255) DEFAULT NULL COMMENT '示例值',
  `is_system` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否系统预置',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_var_key` (`var_key`),
  KEY `idx_var_category` (`var_category`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COMMENT='合同模板变量表';

CREATE TABLE `business_contract_templates` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `template_code` varchar(50) NOT NULL DEFAULT '' COMMENT '模板编号 TPL-YYYYMMDD-XXXX',
  `template_name` varchar(100) NOT NULL DEFAULT '' COMMENT '模板名称',
  `template_type` varchar(20) NOT NULL DEFAULT 'standard' COMMENT '模板类型：standard标准 custom自定义',
  `contract_type` varchar(30) NOT NULL DEFAULT '' COMMENT '适用合同类型：sales/purchase/repair_service',
  `content` longtext NOT NULL COMMENT '模板内容（HTML，含变量占位符）',
  `style` text COMMENT '模板样式（CSS）',
  `variables` json DEFAULT NULL COMMENT '模板使用的变量列表',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认模板',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `version` int(11) NOT NULL DEFAULT '1' COMMENT '版本号',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_code` (`template_code`),
  KEY `idx_type_default` (`contract_type`,`is_default`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='合同模板表';

CREATE TABLE `business_contracts` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `contract_no` varchar(50) NOT NULL DEFAULT '' COMMENT '合同编号 CT-YYYYMMDD-XXXX',
  `contract_name` varchar(200) NOT NULL DEFAULT '' COMMENT '合同名称',
  `contract_type` varchar(20) NOT NULL DEFAULT '' COMMENT '合同类型：sales/purchase/repair_service',
  `template_id` int(11) DEFAULT NULL COMMENT '合同模板ID',
  `customer_id` int(11) DEFAULT NULL COMMENT '客户ID（销售/维修合同时必填）',
  `supplier_id` int(11) DEFAULT NULL COMMENT '供应商ID（采购合同时必填）',
  `customer_name` varchar(200) DEFAULT NULL COMMENT '客户名称（冗余）',
  `supplier_name` varchar(200) DEFAULT NULL COMMENT '供应商名称（冗余）',
  `contact_person` varchar(50) DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `contract_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '合同金额',
  `payment_terms` varchar(255) DEFAULT NULL COMMENT '付款方式',
  `items` json DEFAULT NULL COMMENT '合同明细[{name,model,unit,qty,price,amount,remark}]',
  `sign_date` date NOT NULL COMMENT '签订日期',
  `sign_location` varchar(100) DEFAULT NULL COMMENT '签订地点',
  `effective_date` date DEFAULT NULL COMMENT '生效日期',
  `expiry_date` date DEFAULT NULL COMMENT '到期日期',
  `contract_status` varchar(20) NOT NULL DEFAULT 'draft' COMMENT '合同状态：draft/pending/approved/executing/completed/terminated/voided',
  `sign_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '签署状态',
  `sign_flow_id` varchar(100) DEFAULT NULL COMMENT '签署流程ID',
  `sign_url` varchar(500) DEFAULT NULL COMMENT '签署链接',
  `sign_time` datetime DEFAULT NULL COMMENT '签署完成时间',
  `sign_log` json DEFAULT NULL COMMENT '签署日志',
  `file_id` varchar(100) DEFAULT NULL COMMENT '合同文件ID',
  `content` text COMMENT '合同内容（条款摘要）',
  `contract_html` longtext COMMENT '合同HTML内容（模板生成）',
  `content_version` int(11) NOT NULL DEFAULT '1' COMMENT '内容版本号',
  `attachments` json DEFAULT NULL COMMENT '附件列表',
  `responsible_person_id` int(11) DEFAULT NULL COMMENT '负责人ID',
  `responsible_person_name` varchar(50) DEFAULT NULL COMMENT '负责人姓名（冗余）',
  `remark` text COMMENT '备注',
  `parent_contract_id` int(11) DEFAULT NULL COMMENT '父合同ID（续签时关联原合同）',
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联采购订单ID（预留）',
  `request_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联采购申请ID（冗余便于追溯）',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_contract_no` (`contract_no`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_supplier_id` (`supplier_id`),
  KEY `idx_type_status` (`contract_type`,`contract_status`),
  KEY `idx_status_expiry` (`contract_status`,`expiry_date`),
  KEY `idx_sign_date` (`sign_date`),
  KEY `idx_expiry_date` (`expiry_date`),
  KEY `idx_sign_status` (`sign_status`),
  KEY `idx_template_id` (`template_id`),
  KEY `idx_contract_trace` (`order_id`,`request_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COMMENT='合同主表';

CREATE TABLE `business_customer_category` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `category_code` varchar(30) NOT NULL DEFAULT '' COMMENT '分类编码',
  `category_name` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名称',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用0停用',
  `description` varchar(255) DEFAULT NULL COMMENT '描述说明',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_category_code` (`category_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='客户分类表';

CREATE TABLE `business_customers` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `customer_code` varchar(30) NOT NULL DEFAULT '' COMMENT '客户编码 C-YYYYMMDD-XXXX',
  `customer_name` varchar(200) NOT NULL DEFAULT '' COMMENT '客户名称',
  `customer_short_name` varchar(50) DEFAULT NULL COMMENT '客户简称',
  `category_id` int(11) DEFAULT NULL COMMENT '客户分类ID',
  `customer_type` varchar(30) NOT NULL DEFAULT 'other' COMMENT '客户类型：state_owned/private/individual/foreign/other',
  `industry` varchar(30) DEFAULT NULL COMMENT '所属行业：coal/electric/chemical/mechanical/other',
  `region` varchar(20) DEFAULT NULL COMMENT '所属区域：north/east/south/central/southwest/northwest/northeast/other',
  `customer_level` varchar(10) NOT NULL DEFAULT 'C' COMMENT '客户等级：A/B/C/D',
  `credit_limit` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '信用额度',
  `contact_person` varchar(50) DEFAULT NULL COMMENT '联系人姓名',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `contact_email` varchar(100) DEFAULT NULL COMMENT '联系邮箱',
  `address` varchar(255) DEFAULT NULL COMMENT '地址',
  `tax_number` varchar(50) DEFAULT NULL COMMENT '税号',
  `bank_name` varchar(100) DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(50) DEFAULT NULL COMMENT '银行账号',
  `remark` text COMMENT '备注',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用0停用',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_customer_code` (`customer_code`),
  KEY `idx_customer_name` (`customer_name`),
  KEY `idx_customer_type` (`customer_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='客户表';

CREATE TABLE `business_order_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '订单ID',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名（冗余）',
  `action` varchar(30) NOT NULL DEFAULT '' COMMENT '操作类型：create/edit/submit/review_pass/review_reject/status_change/delete',
  `from_status` varchar(20) DEFAULT NULL COMMENT '变更前状态',
  `to_status` varchar(20) DEFAULT NULL COMMENT '变更后状态',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COMMENT='订单状态变更日志表';

CREATE TABLE `business_order_reviews` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '订单ID',
  `reviewer_id` int(11) NOT NULL DEFAULT '0' COMMENT '评审人ID',
  `reviewer_name` varchar(50) NOT NULL DEFAULT '' COMMENT '评审人姓名（冗余）',
  `review_result` varchar(20) NOT NULL DEFAULT '' COMMENT '评审结果：pass/reject',
  `review_comment` varchar(500) DEFAULT NULL COMMENT '评审意见',
  `review_time` datetime DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='订单评审记录表';

CREATE TABLE `business_orders` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '订单编号 SO-YYYYMMDD-XXXX',
  `order_category` varchar(20) NOT NULL DEFAULT '' COMMENT '订单类别：sales/repair',
  `customer_id` int(11) NOT NULL DEFAULT '0' COMMENT '客户ID',
  `customer_name` varchar(200) NOT NULL DEFAULT '' COMMENT '客户名称（冗余）',
  `contact_person` varchar(50) DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `order_date` date NOT NULL COMMENT '订单日期',
  `delivery_date` date DEFAULT NULL COMMENT '交付日期',
  `order_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '订单金额',
  `order_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '订单状态：pending/reviewed/production/shipping/completed/cancelled',
  `out_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '已出库数量',
  `out_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '出库状态：0未出库 1部分出库 2全部出库',
  `production_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '生产状态：0未生产 1生产中 2已完成 3已关闭',
  `work_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工单ID',
  `work_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '关联工单编号（冗余）',
  `production_progress` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '生产进度百分比（由工单同步）',
  `actual_completion_date` date DEFAULT NULL COMMENT '实际完工日期',
  `business_type` varchar(30) NOT NULL DEFAULT 'other' COMMENT '业务类型：repair/parts_sales/product_sales/other',
  `contract_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联合同ID',
  `contract_no` varchar(50) NOT NULL DEFAULT '' COMMENT '合同编号（冗余）',
  `remark` text COMMENT '备注',
  `salesperson_id` int(11) DEFAULT NULL COMMENT '业务员ID',
  `salesperson_name` varchar(50) DEFAULT NULL COMMENT '业务员姓名（冗余）',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_category_status` (`order_category`,`order_status`),
  KEY `idx_status_create` (`order_status`,`create_time`),
  KEY `idx_order_date` (`order_date`),
  KEY `idx_contract_id` (`contract_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='订单主表';

CREATE TABLE `business_product_bom` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `bom_code` varchar(30) NOT NULL DEFAULT '' COMMENT 'BOM编号 BOM+YYYYMMDD+XXXX',
  `bom_name` varchar(100) NOT NULL DEFAULT '' COMMENT 'BOM名称',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '父件产品ID',
  `product_code` varchar(30) NOT NULL DEFAULT '' COMMENT '父件产品编码（冗余）',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '父件产品名称（冗余）',
  `version` varchar(20) NOT NULL DEFAULT 'V1.0' COMMENT '版本号',
  `quantity` decimal(12,4) NOT NULL DEFAULT '1.0000' COMMENT '父件数量',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '父件单位',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认BOM：1是0否',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用0停用',
  `approval_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '审批状态：0草稿1待审批2已审批3已驳回',
  `effective_date` date DEFAULT NULL COMMENT '生效日期',
  `expiry_date` date DEFAULT NULL COMMENT '失效日期',
  `remark` text COMMENT '备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bom_code` (`bom_code`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='产品BOM主表';

CREATE TABLE `business_product_bom_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `bom_id` int(11) NOT NULL DEFAULT '0' COMMENT '所属BOM ID',
  `parent_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '父级子项ID（0=顶级）',
  `component_product_id` int(11) NOT NULL DEFAULT '0' COMMENT '子件产品ID',
  `component_code` varchar(30) NOT NULL DEFAULT '' COMMENT '子件编码（冗余）',
  `component_name` varchar(200) NOT NULL DEFAULT '' COMMENT '子件名称（冗余）',
  `component_spec` varchar(100) NOT NULL DEFAULT '' COMMENT '子件规格（冗余）',
  `component_unit` varchar(20) NOT NULL DEFAULT '' COMMENT '子件单位（冗余）',
  `quantity` decimal(12,4) NOT NULL DEFAULT '1.0000' COMMENT '用量',
  `wastage_rate` decimal(6,2) NOT NULL DEFAULT '0.00' COMMENT '损耗率%',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `source_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '来源类型：1自制2外购3外协',
  `is_key` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否关键件：1是0否',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_bom_id` (`bom_id`),
  KEY `idx_parent` (`bom_id`,`parent_item_id`),
  KEY `idx_component_product` (`component_product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COMMENT='产品BOM子项表';

CREATE TABLE `business_product_category` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` int(11) NOT NULL DEFAULT '0' COMMENT '父级分类ID（0=顶级）',
  `category_code` varchar(30) NOT NULL DEFAULT '' COMMENT '分类编码',
  `category_name` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名称',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序（小在前）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用0停用',
  `description` varchar(255) DEFAULT NULL COMMENT '描述说明',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_category_code` (`category_code`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='产品分类表（树形）';

CREATE TABLE `business_product_drawing` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `drawing_code` varchar(30) NOT NULL DEFAULT '' COMMENT '图纸编号 DWG+YYYYMMDD+XXXX',
  `drawing_name` varchar(150) NOT NULL DEFAULT '' COMMENT '图纸名称',
  `drawing_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '图纸类型：1CAD 2PDF 3图片 4三维 5其他',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联产品ID',
  `product_code` varchar(30) NOT NULL DEFAULT '' COMMENT '产品编码（冗余）',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称（冗余）',
  `category_id` int(11) DEFAULT NULL COMMENT '图纸分类ID',
  `file_name` varchar(255) NOT NULL DEFAULT '' COMMENT '原始文件名',
  `file_path` varchar(255) NOT NULL DEFAULT '' COMMENT '文件存储路径',
  `file_size` bigint(20) NOT NULL DEFAULT '0' COMMENT '文件大小（字节）',
  `file_ext` varchar(10) NOT NULL DEFAULT '' COMMENT '文件扩展名',
  `version` varchar(20) NOT NULL DEFAULT 'V1.0' COMMENT '版本号',
  `is_newest` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否最新版本：1是0否',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用0停用',
  `uploader_id` int(11) NOT NULL DEFAULT '0' COMMENT '上传人ID',
  `uploader_name` varchar(50) NOT NULL DEFAULT '' COMMENT '上传人姓名（冗余）',
  `uploaded_at` datetime DEFAULT NULL COMMENT '上传时间',
  `remark` text COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_drawing_code` (`drawing_code`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='产品图纸主表';

CREATE TABLE `business_product_drawing_category` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` int(11) NOT NULL DEFAULT '0' COMMENT '父级分类ID（0=顶级）',
  `category_code` varchar(30) NOT NULL DEFAULT '' COMMENT '分类编码',
  `category_name` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名称',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序（小在前）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用0停用',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_category_code` (`category_code`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='产品图纸分类表（树形）';

CREATE TABLE `business_product_drawing_version` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `drawing_id` int(11) NOT NULL DEFAULT '0' COMMENT '图纸ID',
  `version` varchar(20) NOT NULL DEFAULT '' COMMENT '版本号',
  `file_name` varchar(255) NOT NULL DEFAULT '' COMMENT '原始文件名',
  `file_path` varchar(255) NOT NULL DEFAULT '' COMMENT '文件存储路径',
  `file_size` bigint(20) NOT NULL DEFAULT '0' COMMENT '文件大小（字节）',
  `uploader_id` int(11) NOT NULL DEFAULT '0' COMMENT '上传人ID',
  `uploader_name` varchar(50) NOT NULL DEFAULT '' COMMENT '上传人姓名（冗余）',
  `uploaded_at` datetime DEFAULT NULL COMMENT '上传时间',
  `change_description` varchar(500) DEFAULT NULL COMMENT '变更说明',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_drawing_id` (`drawing_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='产品图纸版本历史表';

CREATE TABLE `business_product_param_values` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `param_name` varchar(50) NOT NULL DEFAULT '' COMMENT '参数名称',
  `param_value` varchar(255) NOT NULL DEFAULT '' COMMENT '参数值',
  `param_unit` varchar(20) NOT NULL DEFAULT '' COMMENT '参数单位',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序，小在前',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_product_id` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='产品参数值表';

CREATE TABLE `business_product_receipt` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `receipt_no` varchar(30) NOT NULL DEFAULT '' COMMENT '接收单编号 RC+YYYYMMDD+XXXX',
  `receipt_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '接收类型：1煤矿拉回 2维修完成移交 3客户退货 4内部调拨 5其他',
  `work_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联维修工单ID（煤矿拉回/维修完成时）',
  `work_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '关联维修工单编号（冗余）',
  `source_location` varchar(100) DEFAULT NULL COMMENT '来源地点（如XX煤矿，煤矿拉回必填）',
  `customer_id` int(11) NOT NULL DEFAULT '0' COMMENT '客户ID（客户退货时）',
  `customer_name` varchar(200) NOT NULL DEFAULT '' COMMENT '客户名称（冗余）',
  `receipt_date` date DEFAULT NULL COMMENT '接收日期',
  `receiver_id` int(11) NOT NULL DEFAULT '0' COMMENT '接收人ID',
  `receiver_name` varchar(50) NOT NULL DEFAULT '' COMMENT '接收人姓名（冗余）',
  `product_status` tinyint(1) NOT NULL DEFAULT '5' COMMENT '产品状态：1完好 2待维修 3待保养 4报废 5待检验',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '接收状态：0草稿 1已接收 2已入库 3已移交/已发货',
  `remark` text COMMENT '整体备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  `quality_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '质量状态：0未质检 1合格 2不合格',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_receipt_no` (`receipt_no`),
  KEY `idx_type` (`receipt_type`),
  KEY `idx_status` (`status`),
  KEY `idx_receipt_date` (`receipt_date`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='产品接收单主表';

CREATE TABLE `business_product_receipt_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `receipt_id` int(11) NOT NULL DEFAULT '0' COMMENT '接收单ID',
  `work_order_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联维修订单明细ID（剩余量扣减）',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID（关联产品表，无则0）',
  `product_code` varchar(30) NOT NULL DEFAULT '' COMMENT '产品编码（冗余/手填）',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称',
  `product_spec` varchar(100) NOT NULL DEFAULT '' COMMENT '规格型号',
  `product_unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位',
  `quantity` int(11) NOT NULL DEFAULT '1' COMMENT '接收数量',
  `product_status` tinyint(1) NOT NULL DEFAULT '5' COMMENT '产品状态：1完好 2待维修 3待保养 4报废 5待检验',
  `serial_no` varchar(100) DEFAULT NULL COMMENT '设备编号/序列号',
  `source_location` varchar(100) DEFAULT NULL COMMENT '来源矿井（从接收单带入）',
  `manufacturer` varchar(100) DEFAULT NULL COMMENT '生产厂家',
  `manufacture_date` date DEFAULT NULL COMMENT '出厂日期',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_receipt_id` (`receipt_id`),
  KEY `idx_product_id` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COMMENT='产品接收明细表';

CREATE TABLE `business_product_receipt_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `receipt_id` int(11) NOT NULL DEFAULT '0' COMMENT '接收单ID',
  `action` varchar(50) NOT NULL DEFAULT '' COMMENT '操作动作',
  `content` varchar(500) DEFAULT NULL COMMENT '操作内容',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_receipt_id` (`receipt_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COMMENT='产品接收操作日志表';

CREATE TABLE `business_product_receipt_transport` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `receipt_id` int(11) NOT NULL DEFAULT '0' COMMENT '接收单ID',
  `transport_no` varchar(30) NOT NULL DEFAULT '' COMMENT '运输单号 TR+YYYYMMDD+XXXX',
  `transport_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '运输方式：1公司派车 2外包物流 3客户自送 4其他',
  `plate_no` varchar(30) DEFAULT NULL COMMENT '车牌号',
  `driver_name` varchar(50) DEFAULT NULL COMMENT '司机姓名',
  `driver_phone` varchar(30) DEFAULT NULL COMMENT '司机联系方式',
  `logistics_company` varchar(100) DEFAULT NULL COMMENT '物流公司',
  `track_no` varchar(60) DEFAULT NULL COMMENT '物流单号',
  `depart_date` date DEFAULT NULL COMMENT '发车日期',
  `expected_arrive_date` date DEFAULT NULL COMMENT '预计到达日期',
  `actual_arrive_date` date DEFAULT NULL COMMENT '实际到达日期',
  `ship_address` varchar(200) DEFAULT NULL COMMENT '发货地址（如XX煤矿）',
  `receive_address` varchar(200) DEFAULT NULL COMMENT '收货地址（公司地址）',
  `freight_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '运费金额',
  `transport_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '运输状态：0待发车 1运输中 2已到达 3已签收',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_receipt_id` (`receipt_id`),
  KEY `idx_transport_no` (`transport_no`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='产品接收运输信息表';

CREATE TABLE `business_product_repair_history` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `work_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '维修工单ID',
  `work_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '维修工单编号（冗余）',
  `repair_type` tinyint(1) NOT NULL DEFAULT '3' COMMENT '维修类型：1大修 2中修 3小修 4保养',
  `content` varchar(500) DEFAULT NULL COMMENT '维修内容描述',
  `start_date` date DEFAULT NULL COMMENT '维修开始日期',
  `complete_date` date DEFAULT NULL COMMENT '维修完成日期',
  `repairer` varchar(50) DEFAULT NULL COMMENT '维修负责人',
  `result` varchar(20) NOT NULL DEFAULT '已修复' COMMENT '维修结果：已修复/部分修复/无法修复',
  `parts` text COMMENT '更换配件清单（JSON数组）',
  `cost` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '维修费用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_work_order` (`work_order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='产品维修履历表';

CREATE TABLE `business_product_status_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `before_status` tinyint(1) DEFAULT NULL COMMENT '变更前状态（1-5）',
  `after_status` tinyint(1) NOT NULL DEFAULT '5' COMMENT '变更后状态（1-5）',
  `reason` varchar(255) DEFAULT NULL COMMENT '变更原因',
  `ref_no` varchar(50) DEFAULT NULL COMMENT '关联单据号（接收单/维修工单编号）',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_product_id` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='产品状态变更日志表';

CREATE TABLE `business_products` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `product_code` varchar(30) NOT NULL DEFAULT '' COMMENT '产品编码 P-YYYYMMDD-XXXX',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称',
  `category_id` int(11) DEFAULT NULL COMMENT '产品分类ID',
  `specification` varchar(100) DEFAULT NULL COMMENT '规格型号',
  `serial_number` varchar(100) DEFAULT NULL COMMENT '设备编号/序列号（设备类唯一标识）',
  `manufacturer` varchar(100) DEFAULT NULL COMMENT '生产厂家',
  `manufacture_date` date DEFAULT NULL COMMENT '出厂日期',
  `unit` varchar(20) DEFAULT NULL COMMENT '单位',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序，小在前',
  `qrcode_url` varchar(255) DEFAULT NULL COMMENT '二维码图片地址',
  `qrcode_generated_at` datetime DEFAULT NULL COMMENT '二维码生成时间',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用0停用',
  `current_location` varchar(100) DEFAULT NULL COMMENT '当前所在位置（如维修车间/成品区/XX煤矿）',
  `product_image` varchar(255) DEFAULT NULL COMMENT '产品图片URL',
  `remark` text COMMENT '备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_product_code` (`product_code`),
  KEY `idx_product_name` (`product_name`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COMMENT='产品表';

CREATE TABLE `business_purchase_arrival` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `arrival_no` varchar(30) NOT NULL DEFAULT '' COMMENT '到货单编号 AR+YYYYMMDD+XXXX',
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联采购订单ID',
  `order_no` varchar(30) NOT NULL DEFAULT '' COMMENT '关联采购订单编号（冗余）',
  `supplier_id` int(11) NOT NULL DEFAULT '0' COMMENT '供应商ID',
  `supplier_name` varchar(200) NOT NULL DEFAULT '' COMMENT '供应商名称（冗余）',
  `arrival_date` date DEFAULT NULL COMMENT '到货日期',
  `received_quantity` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '已入库数量（分批入库累加）',
  `logistics_company` varchar(100) DEFAULT NULL COMMENT '物流公司名称',
  `track_no` varchar(60) DEFAULT NULL COMMENT '物流单号',
  `receiver` varchar(50) DEFAULT NULL COMMENT '收货人（签收人）',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '到货状态：0待质检 1质检中 2质检合格 3质检不合格 4待入库 5已入库',
  `quality_remark` varchar(500) DEFAULT NULL COMMENT '质检结果备注（整体结论）',
  `remark` text COMMENT '备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_arrival_no` (`arrival_no`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_status` (`status`),
  KEY `idx_arrival_date` (`arrival_date`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='采购到货单主表';

CREATE TABLE `business_purchase_arrival_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `arrival_id` int(11) NOT NULL DEFAULT '0' COMMENT '到货单ID',
  `order_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '采购订单明细ID（行级追溯）',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `product_code` varchar(30) NOT NULL DEFAULT '' COMMENT '产品编码（冗余）',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称（冗余）',
  `product_spec` varchar(100) NOT NULL DEFAULT '' COMMENT '规格型号（冗余）',
  `product_unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位（冗余）',
  `order_quantity` int(11) NOT NULL DEFAULT '0' COMMENT '订单数量',
  `arrival_quantity` int(11) NOT NULL DEFAULT '0' COMMENT '到货数量',
  `qualified_quantity` int(11) NOT NULL DEFAULT '0' COMMENT '质检合格数量',
  `unqualified_quantity` int(11) NOT NULL DEFAULT '0' COMMENT '质检不合格数量',
  `quality_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '质检状态：0待检 1合格 2不合格',
  `unqualified_reason` varchar(255) DEFAULT NULL COMMENT '不合格原因',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_arrival_id` (`arrival_id`),
  KEY `idx_order_item` (`order_item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='采购到货明细表';

CREATE TABLE `business_purchase_arrival_notice` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `arrival_id` int(11) NOT NULL DEFAULT '0' COMMENT '到货单ID',
  `notice_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '通知类型：1到货通知 2质检完成通知 3入库完成通知',
  `target_user_id` int(11) NOT NULL DEFAULT '0' COMMENT '通知对象ID',
  `target_user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '通知对象姓名（冗余）',
  `notice_way` varchar(30) NOT NULL DEFAULT '1' COMMENT '通知方式：1站内信 2邮件 3短信 4多种组合',
  `content` text COMMENT '通知内容',
  `send_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '发送状态：0待发送 1已发送 2发送失败',
  `send_time` datetime DEFAULT NULL COMMENT '发送时间',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_arrival_id` (`arrival_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='采购到货通知记录表';

CREATE TABLE `business_purchase_order` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_no` varchar(30) NOT NULL DEFAULT '' COMMENT '订单编号 PO+YYYYMMDD+XXXX',
  `title` varchar(200) NOT NULL DEFAULT '' COMMENT '订单标题',
  `supplier_id` int(11) NOT NULL DEFAULT '0' COMMENT '供应商ID',
  `supplier_name` varchar(200) NOT NULL DEFAULT '' COMMENT '供应商名称（冗余）',
  `request_id` int(11) NOT NULL DEFAULT '0' COMMENT '来源采购申请ID',
  `request_no` varchar(30) NOT NULL DEFAULT '' COMMENT '来源采购申请编号（冗余）',
  `order_date` date DEFAULT NULL COMMENT '订单日期',
  `expected_date` date DEFAULT NULL COMMENT '期望交货日期',
  `total_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '订单总金额',
  `order_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '订单状态：0草稿 1已确认 2已发货 3部分入库 4已入库 5已关闭 6已中止',
  `payment_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '付款状态：0未付款 1部分付款 2已付款',
  `approval_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '审核状态：0草稿 1待审核 2已审核 3已驳回',
  `approver_id` int(11) NOT NULL DEFAULT '0' COMMENT '审核人ID',
  `approver_name` varchar(50) NOT NULL DEFAULT '' COMMENT '审核人姓名（冗余）',
  `approval_date` datetime DEFAULT NULL COMMENT '审核日期',
  `approval_remark` varchar(500) DEFAULT NULL COMMENT '审核备注',
  `receive_address` varchar(255) DEFAULT NULL COMMENT '收货地址',
  `receiver` varchar(50) DEFAULT NULL COMMENT '收货人',
  `receiver_phone` varchar(20) DEFAULT NULL COMMENT '收货电话',
  `payment_terms` varchar(255) DEFAULT NULL COMMENT '付款条款',
  `transport_type` varchar(50) DEFAULT NULL COMMENT '运输方式',
  `track_no` varchar(60) DEFAULT NULL COMMENT '物流单号',
  `express_code` varchar(30) DEFAULT NULL COMMENT '快递公司编码（标准码）',
  `express_name` varchar(50) DEFAULT NULL COMMENT '快递公司名称',
  `logistics_status` varchar(30) DEFAULT NULL COMMENT '物流状态：pending/transporting/delivering/delivered/exception',
  `logistics_status_label` varchar(50) DEFAULT NULL COMMENT '物流状态标签',
  `logistics_updated_at` datetime DEFAULT NULL COMMENT '物流状态更新时间',
  `received_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '已入库总数量',
  `arrive_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '到货状态：0未到货 1部分到货 2全部到货',
  `arrived_quantity` int(11) NOT NULL DEFAULT '0' COMMENT '已到货总数量',
  `remark` text COMMENT '备注',
  `purpose` text COMMENT '用途说明（从采购申请带入）',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_supplier` (`supplier_id`),
  KEY `idx_request` (`request_id`),
  KEY `idx_order_status` (`order_status`),
  KEY `idx_approval` (`approval_status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='采购订单主表';

CREATE TABLE `business_purchase_order_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '订单ID',
  `request_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '来源申请明细ID（行级追溯）',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `product_code` varchar(30) NOT NULL DEFAULT '' COMMENT '产品编码（冗余）',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称（冗余）',
  `product_spec` varchar(100) NOT NULL DEFAULT '' COMMENT '规格型号（冗余）',
  `product_unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位（冗余）',
  `quantity` int(11) NOT NULL DEFAULT '1' COMMENT '下单数量',
  `received_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '已入库数量',
  `unit_price` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '采购单价',
  `total_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '总价（数量x单价）',
  `need_date` date DEFAULT NULL COMMENT '需求日期',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_request_item` (`request_item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='采购订单明细表';

CREATE TABLE `business_purchase_order_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '订单ID',
  `action_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作类型：1创建 2提交审核 3审核通过 4审核驳回 5确认 6发货 7入库 8关闭 9中止',
  `action_label` varchar(30) NOT NULL DEFAULT '' COMMENT '操作类型标签（冗余）',
  `from_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作前订单状态',
  `to_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作后订单状态',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名（冗余）',
  `remark` varchar(500) DEFAULT NULL COMMENT '操作备注',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COMMENT='采购订单执行日志表';

CREATE TABLE `business_purchase_order_logistics` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '采购订单ID',
  `track_no` varchar(60) NOT NULL DEFAULT '' COMMENT '快递单号',
  `express_code` varchar(30) NOT NULL DEFAULT '' COMMENT '快递公司编码（标准码）',
  `express_name` varchar(50) NOT NULL DEFAULT '' COMMENT '快递公司名称',
  `logistics_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '物流状态：0未发货 1已揽收 2运输中 3派送中 4已签收 5异常',
  `logistics_status_label` varchar(50) NOT NULL DEFAULT '' COMMENT '物流状态标签',
  `traces` text COMMENT '物流轨迹数据（JSON数组，完整时间轴）',
  `ship_date` date DEFAULT NULL COMMENT '发货日期',
  `predict_date` date DEFAULT NULL COMMENT '预计送达日期',
  `signed_date` date DEFAULT NULL COMMENT '实际签收日期',
  `express_phone` varchar(50) DEFAULT NULL COMMENT '物流公司客服电话',
  `error_reason` varchar(255) DEFAULT NULL COMMENT '异常原因',
  `last_update_time` datetime DEFAULT NULL COMMENT '最后更新时间',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_track_no` (`track_no`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COMMENT='采购订单物流跟踪表';

CREATE TABLE `business_purchase_order_reminder` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '采购订单ID',
  `remind_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '催货类型：1电话催货 2邮件催货 3系统自动提醒',
  `content` varchar(500) NOT NULL DEFAULT '' COMMENT '催货内容',
  `contact` varchar(50) DEFAULT NULL COMMENT '联系人',
  `contact_way` varchar(100) DEFAULT NULL COMMENT '联系方式',
  `reminder` varchar(50) NOT NULL DEFAULT '' COMMENT '催货人',
  `remind_time` datetime DEFAULT NULL COMMENT '催货时间',
  `is_replied` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已回复：0否 1是',
  `reply_content` varchar(500) DEFAULT NULL COMMENT '回复内容',
  `reply_time` datetime DEFAULT NULL COMMENT '回复时间',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购订单催货记录表';

CREATE TABLE `business_purchase_request` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `request_code` varchar(30) NOT NULL DEFAULT '' COMMENT '申请编号 PR+YYYYMMDD+XXXX',
  `title` varchar(200) NOT NULL DEFAULT '' COMMENT '申请标题',
  `request_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '申请类型：1日常 2项目 3紧急 4备品备件',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '申请部门ID',
  `department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '申请部门名称（冗余）',
  `applicant_id` int(11) NOT NULL DEFAULT '0' COMMENT '申请人ID',
  `applicant_name` varchar(50) NOT NULL DEFAULT '' COMMENT '申请人姓名（冗余）',
  `request_date` date DEFAULT NULL COMMENT '申请日期',
  `expected_date` date DEFAULT NULL COMMENT '期望交付日期',
  `budget_subject` varchar(100) DEFAULT NULL COMMENT '预算科目',
  `budget_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '预算金额（0=无限制）',
  `purpose` text COMMENT '用途说明',
  `urgency` tinyint(1) NOT NULL DEFAULT '1' COMMENT '紧急程度：1普通 2紧急 3特急',
  `approval_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '审批状态：0草稿 1待审批 2已审批 3已驳回 4已撤销',
  `approver_id` int(11) NOT NULL DEFAULT '0' COMMENT '审批人ID',
  `approver_name` varchar(50) NOT NULL DEFAULT '' COMMENT '审批人姓名（冗余）',
  `approval_date` datetime DEFAULT NULL COMMENT '审批日期',
  `approval_remark` varchar(500) DEFAULT NULL COMMENT '审批备注',
  `source_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '来源类型：1手动 2销售订单 3维修订单 4生产工单 5库存补货 6消耗品 7项目 8计划 9紧急',
  `source_id` int(11) NOT NULL DEFAULT '0' COMMENT '来源单据ID',
  `source_no` varchar(50) NOT NULL DEFAULT '' COMMENT '来源单据编号（冗余）',
  `source_category` tinyint(1) NOT NULL DEFAULT '1' COMMENT '来源大类：1订单驱动 2库存补充 3消耗品 4项目 5计划 6紧急',
  `execution_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '执行状态：0待执行 1部分执行 2全部执行 3全部入库',
  `order_count` int(11) NOT NULL DEFAULT '0' COMMENT '已生成采购订单数量',
  `ordered_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '已下单总数量',
  `received_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '已入库总数量',
  `contract_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联采购合同ID',
  `contract_no` varchar(50) NOT NULL DEFAULT '' COMMENT '合同编号（冗余）',
  `contract_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '合同状态：0未签约 1已签约 2已生效',
  `demand_pool_id` int(11) NOT NULL DEFAULT '0' COMMENT '需求池ID',
  `remark` text COMMENT '备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_request_code` (`request_code`),
  KEY `idx_department` (`department_id`),
  KEY `idx_applicant` (`applicant_id`),
  KEY `idx_status` (`approval_status`),
  KEY `idx_source_type` (`source_type`),
  KEY `idx_source_id` (`source_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='采购申请主表';

CREATE TABLE `business_purchase_request_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `request_id` int(11) NOT NULL DEFAULT '0' COMMENT '申请ID',
  `source_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '来源明细ID（精确追溯）',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `product_code` varchar(30) NOT NULL DEFAULT '' COMMENT '产品编码（冗余）',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称（冗余）',
  `product_spec` varchar(100) NOT NULL DEFAULT '' COMMENT '规格型号（冗余）',
  `product_unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位（冗余）',
  `quantity` int(11) NOT NULL DEFAULT '1' COMMENT '申请数量',
  `approved_quantity` int(11) NOT NULL DEFAULT '0' COMMENT '审批数量',
  `unit_price` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '采购单价',
  `total_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '总价（数量x单价）',
  `need_date` date DEFAULT NULL COMMENT '需求日期',
  `ordered_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '已下单数量',
  `received_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '已入库数量',
  `execution_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '执行状态：0待执行 1已生成订单 2部分入库 3全部入库 4已关闭',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_request_id` (`request_id`),
  KEY `idx_product_id` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COMMENT='采购申请明细表';

CREATE TABLE `business_purchase_request_tracking` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `request_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '申请明细ID',
  `purchase_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '采购订单ID',
  `purchase_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '采购订单编号（冗余）',
  `contract_id` int(11) NOT NULL DEFAULT '0' COMMENT '采购合同ID',
  `contract_no` varchar(50) NOT NULL DEFAULT '' COMMENT '合同编号（冗余）',
  `ordered_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '订单数量',
  `received_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '入库数量',
  `execution_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '执行状态：0待执行 1已生成订单 2部分入库 3全部入库 4已关闭',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_request_item_id` (`request_item_id`),
  KEY `idx_purchase_order_id` (`purchase_order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='采购申请执行跟踪表';

CREATE TABLE `business_quotation_items` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `quotation_id` int(11) NOT NULL DEFAULT '0' COMMENT '报价单ID',
  `item_type` varchar(20) NOT NULL DEFAULT 'product' COMMENT '明细类型：product/service/repair/part',
  `item_name` varchar(200) NOT NULL DEFAULT '' COMMENT '项目名称',
  `item_spec` varchar(100) DEFAULT NULL COMMENT '规格型号',
  `quantity` int(11) NOT NULL DEFAULT '1' COMMENT '数量',
  `unit_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '单价',
  `amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '金额（数量×单价）',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_quotation_id` (`quotation_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报价单明细表';

CREATE TABLE `business_quotation_reviews` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `quotation_id` int(11) NOT NULL DEFAULT '0' COMMENT '报价单ID',
  `reviewer_id` int(11) NOT NULL DEFAULT '0' COMMENT '审核人ID',
  `reviewer_name` varchar(50) NOT NULL DEFAULT '' COMMENT '审核人姓名（冗余）',
  `review_result` varchar(20) NOT NULL DEFAULT '' COMMENT '审核结果：pass/reject',
  `review_comment` varchar(500) DEFAULT NULL COMMENT '审核意见',
  `review_time` datetime DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_quotation_id` (`quotation_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报价单审核记录表';

CREATE TABLE `business_quotations` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `quotation_no` varchar(50) NOT NULL DEFAULT '' COMMENT '报价单编号 QT-YYYYMMDD-XXXX',
  `customer_id` int(11) NOT NULL DEFAULT '0' COMMENT '客户ID',
  `customer_name` varchar(200) NOT NULL DEFAULT '' COMMENT '客户名称（冗余）',
  `quotation_category` varchar(20) NOT NULL DEFAULT '' COMMENT '报价类别：repair/sales',
  `quotation_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '报价金额',
  `quotation_status` varchar(20) NOT NULL DEFAULT 'draft' COMMENT '报价状态：draft/pending/approved/rejected/converted',
  `validity_days` int(11) NOT NULL DEFAULT '30' COMMENT '有效期（天）',
  `validity_date` date DEFAULT NULL COMMENT '有效期截止日期',
  `quotation_date` date NOT NULL COMMENT '报价日期',
  `delivery_date` date DEFAULT NULL COMMENT '预计交付日期',
  `remark` text COMMENT '备注',
  `salesperson_id` int(11) DEFAULT NULL COMMENT '业务员ID',
  `salesperson_name` varchar(50) DEFAULT NULL COMMENT '业务员姓名（冗余）',
  `converted_order_id` int(11) DEFAULT NULL COMMENT '转订单后的订单ID',
  `converted_order_no` varchar(50) DEFAULT NULL COMMENT '转订单后的订单编号',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_quotation_no` (`quotation_no`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_category_status` (`quotation_category`,`quotation_status`),
  KEY `idx_status_create` (`quotation_status`,`create_time`),
  KEY `idx_quotation_date` (`quotation_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报价单主表';

CREATE TABLE `business_repair_order_items` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '订单ID',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '配件产品ID',
  `product_code` varchar(30) NOT NULL DEFAULT '' COMMENT '配件编码（冗余）',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '配件名称（冗余）',
  `product_spec` varchar(100) NOT NULL DEFAULT '' COMMENT '配件规格（冗余）',
  `product_unit` varchar(20) NOT NULL DEFAULT '' COMMENT '配件单位（冗余）',
  `quantity` int(11) NOT NULL DEFAULT '1' COMMENT '配件数量',
  `unit_price` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '配件单价',
  `device_name` varchar(200) NOT NULL DEFAULT '' COMMENT '设备名称',
  `device_model` varchar(100) DEFAULT NULL COMMENT '设备型号',
  `device_serial` varchar(50) DEFAULT NULL COMMENT '设备编号',
  `fault_description` text COMMENT '故障描述',
  `repair_hours` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '预估工时',
  `labor_rate` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '工时单价',
  `labor_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '工时费（工时×单价）',
  `parts_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '配件费',
  `total_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '小计（工时费+配件费）',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COMMENT='维修订单明细表';

CREATE TABLE `business_sales_order_items` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '订单ID',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `product_code` varchar(30) NOT NULL DEFAULT '' COMMENT '产品编码（冗余）',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称',
  `product_spec` varchar(100) NOT NULL DEFAULT '' COMMENT '产品规格（冗余）',
  `product_unit` varchar(20) NOT NULL DEFAULT '' COMMENT '产品单位（冗余）',
  `product_model` varchar(100) DEFAULT NULL COMMENT '产品型号',
  `quantity` int(11) NOT NULL DEFAULT '1' COMMENT '数量',
  `unit_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '单价',
  `amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '金额（数量×单价）',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='销售订单明细表';

CREATE TABLE `business_sign_callback_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `flow_id` varchar(100) NOT NULL DEFAULT '' COMMENT '签署流程ID',
  `contract_id` int(11) DEFAULT NULL COMMENT '合同ID',
  `contract_no` varchar(50) DEFAULT NULL COMMENT '合同编号',
  `callback_data` json DEFAULT NULL COMMENT '完整回调数据',
  `sign_status` varchar(20) DEFAULT NULL COMMENT '签署状态',
  `sign_time` datetime DEFAULT NULL COMMENT '签署完成时间',
  `file_url` varchar(500) DEFAULT NULL COMMENT '签署文件下载地址',
  `processed` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已处理：1是 0否',
  `process_time` datetime DEFAULT NULL COMMENT '处理时间',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_flow_id` (`flow_id`),
  KEY `idx_contract_id` (`contract_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='签署回调日志表';

CREATE TABLE `business_sign_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `contract_id` int(11) DEFAULT NULL COMMENT '合同ID（关联 business_contracts）',
  `contract_no` varchar(50) DEFAULT NULL COMMENT '合同编号',
  `flow_id` varchar(100) DEFAULT NULL COMMENT '签署流程ID（电子签平台）',
  `flow_name` varchar(200) DEFAULT NULL COMMENT '流程名称',
  `sign_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '签署状态：pending/signing/signed/expired/rejected',
  `sign_url` varchar(500) DEFAULT NULL COMMENT '签署链接',
  `operator_id` int(11) DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(50) DEFAULT NULL COMMENT '操作人姓名',
  `sign_time` datetime DEFAULT NULL COMMENT '签署完成时间',
  `callback_data` json DEFAULT NULL COMMENT '回调数据（完整通知）',
  `error_message` text COMMENT '错误信息',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_flow_id` (`flow_id`),
  KEY `idx_contract_id` (`contract_id`),
  KEY `idx_status_create` (`sign_status`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='电子签签署日志表';

CREATE TABLE `business_supplier_category` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `category_code` varchar(30) NOT NULL DEFAULT '' COMMENT '分类编码',
  `category_name` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名称',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用0停用',
  `description` varchar(255) DEFAULT NULL COMMENT '描述说明',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_category_code` (`category_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='供应商分类表';

CREATE TABLE `business_suppliers` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `supplier_code` varchar(30) NOT NULL DEFAULT '' COMMENT '供应商编码 S-YYYYMMDD-XXXX',
  `supplier_name` varchar(200) NOT NULL DEFAULT '' COMMENT '供应商名称',
  `supplier_short_name` varchar(50) DEFAULT NULL COMMENT '供应商简称',
  `category_id` int(11) DEFAULT NULL COMMENT '供应商分类ID',
  `supplier_type` varchar(30) NOT NULL DEFAULT 'other' COMMENT '供应商类型：manufacturer/trader/outsource/service/other',
  `supply_category` varchar(30) DEFAULT NULL COMMENT '供应品类：parts/raw_material/outsource/equipment/other',
  `region` varchar(20) DEFAULT NULL COMMENT '所属区域：north/east/south/central/southwest/northwest/northeast/other',
  `supplier_level` varchar(10) NOT NULL DEFAULT 'C' COMMENT '供应商评级：A/B/C/D',
  `contact_person` varchar(50) DEFAULT NULL COMMENT '联系人姓名',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `contact_email` varchar(100) DEFAULT NULL COMMENT '联系邮箱',
  `address` varchar(255) DEFAULT NULL COMMENT '地址',
  `tax_number` varchar(50) DEFAULT NULL COMMENT '税号',
  `bank_name` varchar(100) DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(50) DEFAULT NULL COMMENT '银行账号',
  `qualifications` json DEFAULT NULL COMMENT '资质证照（名称/编号/有效期）',
  `cooperation_start` date DEFAULT NULL COMMENT '合作开始日期',
  `remark` text COMMENT '备注',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用0停用',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_supplier_code` (`supplier_code`),
  KEY `idx_supplier_name` (`supplier_name`),
  KEY `idx_supplier_type` (`supplier_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='供应商表';

CREATE TABLE `contacts_messages` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `sender_id` int(11) unsigned NOT NULL COMMENT '发送者用户ID',
  `receiver_id` int(11) unsigned NOT NULL COMMENT '接收者用户ID',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容',
  `is_read` tinyint(1) NOT NULL DEFAULT '0' COMMENT '接收者是否已读：0否 1是',
  `created_at` datetime NOT NULL COMMENT '发送时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_sender_receiver_created` (`sender_id`,`receiver_id`,`created_at`),
  KEY `idx_receiver_created` (`receiver_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通讯录消息表';

CREATE TABLE `cost_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_key` varchar(50) NOT NULL DEFAULT '' COMMENT '配置键',
  `config_value` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '配置值',
  `description` varchar(255) NOT NULL DEFAULT '' COMMENT '说明',
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_config_key` (`config_key`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='成本配置表';

CREATE TABLE `customer_churn_actions` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL DEFAULT '0' COMMENT '客户ID',
  `customer_name` varchar(200) DEFAULT '' COMMENT '客户名称（冗余）',
  `strategy_id` int(11) DEFAULT NULL COMMENT '策略ID',
  `strategy_name` varchar(50) DEFAULT '' COMMENT '策略名称（冗余）',
  `risk_id` int(11) DEFAULT NULL COMMENT '关联风险记录ID',
  `action_content` text COMMENT '执行内容',
  `executor` varchar(50) DEFAULT NULL COMMENT '执行人',
  `execute_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=待执行 1=执行中 2=已完成 3=失败',
  `customer_response` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=未响应 1=已查看 2=已回复 3=已转化',
  `result` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=进行中 1=成功 2=失败',
  `recovery_amount` decimal(15,2) DEFAULT NULL COMMENT '挽回金额',
  `recovery_days` int(11) DEFAULT NULL COMMENT '挽回周期（天）',
  `executed_at` datetime DEFAULT NULL COMMENT '执行时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_result` (`result`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='挽回执行记录表';

CREATE TABLE `customer_churn_risks` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL DEFAULT '0' COMMENT '客户ID',
  `customer_name` varchar(200) DEFAULT '' COMMENT '客户名称（冗余）',
  `risk_score` int(11) NOT NULL DEFAULT '0' COMMENT '风险评分（0-100）',
  `risk_level` varchar(10) NOT NULL DEFAULT 'low' COMMENT 'low/medium/high',
  `churn_reason` text COMMENT '流失原因（AI生成）',
  `days_since_last_order` int(11) DEFAULT NULL COMMENT '距上次购买天数',
  `frequency_decline` decimal(5,2) DEFAULT NULL COMMENT '近3月频次下降率（%）',
  `amount_decline` decimal(5,2) DEFAULT NULL COMMENT '近3月金额下降率（%）',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=待处理 1=处理中 2=已挽回 3=已流失',
  `detected_at` datetime NOT NULL COMMENT '检测时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_risk_level` (`risk_level`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='客户流失风险表';

CREATE TABLE `customer_churn_strategies` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `strategy_name` varchar(50) NOT NULL DEFAULT '' COMMENT '策略名称',
  `strategy_code` varchar(30) NOT NULL DEFAULT '' COMMENT '策略编码',
  `description` text COMMENT '策略描述',
  `applicable_scenario` varchar(50) DEFAULT NULL COMMENT '适用场景',
  `execution_type` varchar(20) DEFAULT NULL COMMENT '执行方式：visit/coupon/recommend/survey/care',
  `expected_success_rate` decimal(5,2) DEFAULT NULL COMMENT '预计成功率（%）',
  `estimated_cost` varchar(50) DEFAULT NULL COMMENT '预计成本',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=禁用 1=启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='挽回策略模板表';

CREATE TABLE `customer_rfm_scores` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL DEFAULT '0' COMMENT '客户ID',
  `analysis_period` varchar(20) NOT NULL DEFAULT '' COMMENT '分析周期（YYYY-MM）',
  `r_value` int(11) DEFAULT NULL COMMENT 'R值（距上次购买天数）',
  `f_value` int(11) DEFAULT NULL COMMENT 'F值（购买次数）',
  `m_value` decimal(15,2) DEFAULT NULL COMMENT 'M值（累计消费金额）',
  `r_score` tinyint(1) DEFAULT NULL COMMENT 'R评分（0低/1高）',
  `f_score` tinyint(1) DEFAULT NULL COMMENT 'F评分（0低/1高）',
  `m_score` tinyint(1) DEFAULT NULL COMMENT 'M评分（0低/1高）',
  `customer_type` varchar(20) DEFAULT NULL COMMENT '客户类型（重要价值/重要发展/重要挽留/一般价值/重要保持/一般保持/流失客户）',
  `total_score` int(11) DEFAULT NULL COMMENT '综合评分（0-100）',
  `rank` int(11) DEFAULT NULL COMMENT '排名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_period` (`analysis_period`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='客户RFM评分表';

CREATE TABLE `departments` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '部门名称',
  `parent_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '父级部门ID',
  `code` varchar(50) DEFAULT NULL COMMENT '部门编码',
  `leader_id` int(11) DEFAULT NULL COMMENT '部门负责人ID',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序权重',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '状态 1启用 0禁用',
  `description` varchar(255) DEFAULT NULL COMMENT '部门描述',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COMMENT='部门表';

CREATE TABLE `device_assets` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `device_code` varchar(50) NOT NULL COMMENT '设备编码（唯一）',
  `name` varchar(100) NOT NULL COMMENT '设备名称',
  `category_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '所属分类ID（device_category.id）',
  `device_type` varchar(20) NOT NULL DEFAULT '' COMMENT '设备类型：general/special/car/truck（字典device_type）',
  `model` varchar(50) NOT NULL DEFAULT '' COMMENT '型号',
  `specification` varchar(255) NOT NULL DEFAULT '' COMMENT '规格参数',
  `brand` varchar(50) NOT NULL DEFAULT '' COMMENT '品牌',
  `manufacturer` varchar(100) NOT NULL DEFAULT '' COMMENT '生产厂家',
  `supplier_id` int(11) unsigned DEFAULT NULL COMMENT '供应商ID（supplier.id）',
  `purchase_date` date DEFAULT NULL COMMENT '采购日期',
  `purchase_price` decimal(10,2) DEFAULT NULL COMMENT '采购价格',
  `put_into_use_date` date DEFAULT NULL COMMENT '投入使用日期',
  `inspection_expire_date` date DEFAULT NULL COMMENT '年检到期日',
  `insurance_expire_date` date DEFAULT NULL COMMENT '保险到期日',
  `department_id` int(11) unsigned DEFAULT NULL COMMENT '使用部门ID（departments.id）',
  `location` varchar(100) NOT NULL DEFAULT '' COMMENT '存放位置',
  `manager_id` int(11) unsigned DEFAULT NULL COMMENT '负责人ID（users.id）',
  `status` varchar(20) NOT NULL DEFAULT 'in_use' COMMENT '状态（字典device_status）',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT '设备图片',
  `qrcode_url` varchar(255) NOT NULL DEFAULT '' COMMENT '二维码图片访问地址',
  `qrcode_generated_at` datetime DEFAULT NULL COMMENT '二维码生成时间',
  `qrcode` varchar(255) NOT NULL DEFAULT '' COMMENT '二维码',
  `remark` text COMMENT '备注',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_device_code` (`device_code`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_device_type` (`device_type`),
  KEY `idx_status` (`status`),
  KEY `idx_department_id` (`department_id`),
  KEY `idx_manager_id` (`manager_id`),
  KEY `idx_purchase_date` (`purchase_date`)
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COMMENT='设备台账主表';

CREATE TABLE `device_category` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `parent_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '父级分类ID，0表示顶级分类',
  `name` varchar(50) NOT NULL COMMENT '分类名称',
  `code` varchar(30) NOT NULL COMMENT '分类编码',
  `level` tinyint(4) NOT NULL DEFAULT '1' COMMENT '分类层级深度，顶级为1',
  `icon` varchar(100) NOT NULL DEFAULT '' COMMENT '分类图标（Element UI 图标类名）',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序权重，数值越大越靠前',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_parent_id` (`parent_id`),
  KEY `idx_sort` (`sort`),
  KEY `idx_status` (`status`),
  KEY `idx_level` (`level`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COMMENT='设备分类表';

CREATE TABLE `device_inspection_hazard` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `hazard_code` varchar(50) NOT NULL COMMENT '隐患编号（唯一）',
  `record_id` int(11) unsigned NOT NULL COMMENT '巡检记录ID',
  `device_id` int(11) unsigned NOT NULL COMMENT '设备ID',
  `device_code` varchar(50) NOT NULL COMMENT '设备编码',
  `device_name` varchar(100) NOT NULL COMMENT '设备名称',
  `check_item_name` varchar(100) NOT NULL COMMENT '检查项名称',
  `hazard_desc` text NOT NULL COMMENT '隐患描述',
  `severity` varchar(20) NOT NULL DEFAULT 'general' COMMENT '严重程度：minor/general/serious/emergency（字典hazard_severity）',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态：pending/processing/resolved/closed（字典hazard_status）',
  `handler_id` int(11) unsigned DEFAULT NULL COMMENT '处理人ID',
  `handler_name` varchar(50) NOT NULL DEFAULT '' COMMENT '处理人姓名',
  `handle_measure` text COMMENT '处理措施',
  `handle_result` text COMMENT '处理结果',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `repair_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '关联维修单号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hazard_code` (`hazard_code`),
  KEY `idx_record_id` (`record_id`),
  KEY `idx_device_id` (`device_id`),
  KEY `idx_severity` (`severity`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='巡检隐患表';

CREATE TABLE `device_inspection_plan` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `plan_code` varchar(50) NOT NULL COMMENT '计划编号（唯一）',
  `plan_name` varchar(100) NOT NULL COMMENT '计划名称',
  `plan_type` varchar(20) NOT NULL DEFAULT 'periodic' COMMENT '计划类型：periodic/temporary（字典inspection_plan_type）',
  `target_type` varchar(20) NOT NULL DEFAULT 'device' COMMENT '目标类型：device/device_type',
  `target_ids` text COMMENT '目标ID列表（设备ID或分类ID，逗号分隔）',
  `template_id` int(11) unsigned DEFAULT NULL COMMENT '内容模板ID',
  `executor_type` varchar(20) NOT NULL DEFAULT 'fixed' COMMENT '执行人类型：fixed/role/dept',
  `executor_ids` varchar(500) NOT NULL DEFAULT '' COMMENT '执行人ID列表（逗号分隔）',
  `frequency_type` varchar(20) DEFAULT NULL COMMENT '频率类型：daily/weekly/monthly/quarterly/yearly/once',
  `frequency_value` varchar(50) NOT NULL DEFAULT '' COMMENT '频率值：如每周几/每月几号',
  `start_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '结束日期',
  `next_execute_date` date DEFAULT NULL COMMENT '下次执行日期',
  `status` varchar(20) NOT NULL DEFAULT 'active' COMMENT '状态：active/inactive/expired（字典plan_status）',
  `remark` text COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plan_code` (`plan_code`),
  KEY `idx_plan_type` (`plan_type`),
  KEY `idx_status` (`status`),
  KEY `idx_next_execute_date` (`next_execute_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='巡检计划表';

CREATE TABLE `device_inspection_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `record_code` varchar(50) NOT NULL COMMENT '记录编号（唯一）',
  `task_id` int(11) unsigned NOT NULL COMMENT '任务ID',
  `device_id` int(11) unsigned NOT NULL COMMENT '设备ID',
  `plan_id` int(11) unsigned DEFAULT NULL COMMENT '计划ID',
  `executor_id` int(11) unsigned NOT NULL COMMENT '执行人ID',
  `executor_name` varchar(50) NOT NULL COMMENT '执行人姓名',
  `execute_time` datetime NOT NULL COMMENT '执行时间',
  `items` json NOT NULL COMMENT '检查项完整结果',
  `abnormal_count` int(11) NOT NULL DEFAULT '0' COMMENT '异常项数量',
  `total_count` int(11) NOT NULL DEFAULT '0' COMMENT '总检查项数量',
  `result` varchar(20) NOT NULL DEFAULT 'normal' COMMENT '整体结果：normal/abnormal（字典record_result）',
  `attachments` json DEFAULT NULL COMMENT '附件列表',
  `remark` text COMMENT '备注',
  `auditor_id` int(11) unsigned DEFAULT NULL COMMENT '审核人ID',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(255) NOT NULL DEFAULT '' COMMENT '审核意见',
  `audit_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '审核状态：pending/approved/rejected（字典audit_status）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_record_code` (`record_code`),
  KEY `idx_task_id` (`task_id`),
  KEY `idx_device_id` (`device_id`),
  KEY `idx_executor_id` (`executor_id`),
  KEY `idx_execute_time` (`execute_time`),
  KEY `idx_audit_status` (`audit_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='巡检记录表';

CREATE TABLE `device_inspection_task` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `task_code` varchar(50) NOT NULL COMMENT '任务编号（唯一）',
  `plan_id` int(11) unsigned NOT NULL COMMENT '计划ID',
  `device_id` int(11) unsigned NOT NULL COMMENT '设备ID',
  `device_code` varchar(50) NOT NULL COMMENT '设备编码（冗余）',
  `device_name` varchar(100) NOT NULL COMMENT '设备名称（冗余）',
  `executor_id` int(11) unsigned DEFAULT NULL COMMENT '执行人ID',
  `executor_name` varchar(50) NOT NULL DEFAULT '' COMMENT '执行人姓名',
  `plan_execute_date` date NOT NULL COMMENT '计划执行日期',
  `actual_execute_date` datetime DEFAULT NULL COMMENT '实际执行日期',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态：pending/in_progress/completed/overdue/cancelled（字典task_status）',
  `result` json DEFAULT NULL COMMENT '检查项填写结果',
  `remark` text COMMENT '备注',
  `execute_duration` int(11) DEFAULT NULL COMMENT '执行耗时(分钟)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_code` (`task_code`),
  KEY `idx_plan_id` (`plan_id`),
  KEY `idx_device_id` (`device_id`),
  KEY `idx_executor_id` (`executor_id`),
  KEY `idx_status` (`status`),
  KEY `idx_plan_execute_date` (`plan_execute_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='巡检任务表';

CREATE TABLE `device_inspection_template` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `template_code` varchar(50) NOT NULL COMMENT '模板编号（唯一）',
  `template_name` varchar(100) NOT NULL COMMENT '模板名称',
  `category_id` int(11) unsigned DEFAULT NULL COMMENT '适用分类ID',
  `description` varchar(255) NOT NULL DEFAULT '' COMMENT '模板描述',
  `items` json NOT NULL COMMENT '检查项列表：id/name/standard/check_method/normal_range/required/sort',
  `version` int(11) NOT NULL DEFAULT '1' COMMENT '版本号',
  `status` varchar(20) NOT NULL DEFAULT 'active' COMMENT '状态：active/inactive',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_code` (`template_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='巡检内容模板表';

CREATE TABLE `device_maintenance_level` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `level_code` varchar(30) NOT NULL COMMENT '等级编码，如 DAILY、LEVEL1、LEVEL2、LEVEL3',
  `level_name` varchar(50) NOT NULL COMMENT '等级名称，如日常保养、一级保养',
  `executor_role` varchar(50) DEFAULT '' COMMENT '执行人角色',
  `acceptor_role` varchar(50) DEFAULT '' COMMENT '验收人角色',
  `default_cycle_type` varchar(20) DEFAULT '' COMMENT '默认周期类型 day/week/month/quarter/year/hour',
  `default_cycle_value` int(11) DEFAULT '0' COMMENT '默认周期值',
  `description` varchar(255) DEFAULT '' COMMENT '描述说明',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态 1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_level_code` (`level_code`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='保养等级表';

CREATE TABLE `device_maintenance_material` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `material_code` varchar(50) NOT NULL COMMENT '耗材编码',
  `material_name` varchar(100) NOT NULL COMMENT '耗材名称',
  `specification` varchar(100) DEFAULT '' COMMENT '规格型号',
  `unit` varchar(20) DEFAULT '' COMMENT '单位（个/瓶/升/米等）',
  `stock` int(11) NOT NULL DEFAULT '0' COMMENT '库存数量',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态 1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_material_code` (`material_code`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='保养耗材表';

CREATE TABLE `device_maintenance_notification` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) unsigned NOT NULL COMMENT '接收人用户ID',
  `notify_type` varchar(30) NOT NULL COMMENT '类型 task_assign任务分配/remind到期提醒/overdue逾期/verify_result验收结果',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `content` text NOT NULL COMMENT '内容',
  `task_id` int(11) unsigned DEFAULT NULL COMMENT '关联任务ID',
  `record_id` int(11) unsigned DEFAULT NULL COMMENT '关联记录ID',
  `is_read` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已读',
  `channel` varchar(30) NOT NULL DEFAULT 'inbox' COMMENT '渠道 inbox站内信/email邮件',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_task_id` (`task_id`),
  KEY `idx_is_read` (`is_read`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COMMENT='保养通知表';

CREATE TABLE `device_maintenance_plan` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `plan_code` varchar(50) NOT NULL COMMENT '计划编号，格式 MNT-YYYYMMDD-XXXX',
  `plan_name` varchar(100) NOT NULL COMMENT '计划名称',
  `device_id` int(11) unsigned NOT NULL COMMENT '设备ID，关联设备主表',
  `level_id` int(11) unsigned NOT NULL COMMENT '保养等级ID',
  `template_id` int(11) unsigned DEFAULT NULL COMMENT '模板ID，关联保养模板表',
  `cycle_type` varchar(20) NOT NULL COMMENT '周期类型 day/week/month/quarter/year/hour',
  `cycle_value` int(11) NOT NULL COMMENT '周期值',
  `cycle_unit` varchar(20) DEFAULT '' COMMENT '周期单位 day/week/month/quarter/year/hour',
  `start_date` date DEFAULT NULL COMMENT '计划开始日期',
  `end_date` date DEFAULT NULL COMMENT '计划结束日期',
  `last_maintenance_date` date DEFAULT NULL COMMENT '上次保养日期',
  `next_maintenance_date` date DEFAULT NULL COMMENT '下次保养日期',
  `executor_id` int(11) unsigned DEFAULT NULL COMMENT '执行人ID，关联user表',
  `executor_name` varchar(50) DEFAULT '' COMMENT '执行人姓名',
  `acceptor_id` int(11) unsigned DEFAULT NULL COMMENT '验收人ID，关联user表',
  `acceptor_name` varchar(50) DEFAULT '' COMMENT '验收人姓名',
  `need_approve` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否需要审批 1是 0否',
  `status` varchar(20) NOT NULL DEFAULT 'active' COMMENT '状态 active启用 inactive停用 expired过期',
  `remark` text COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plan_code` (`plan_code`),
  KEY `idx_device_id` (`device_id`),
  KEY `idx_level_id` (`level_id`),
  KEY `idx_status` (`status`),
  KEY `idx_next_date` (`next_maintenance_date`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COMMENT='保养计划表';

CREATE TABLE `device_maintenance_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `record_code` varchar(50) NOT NULL COMMENT '记录编号，格式 MNT-REC-YYYYMMDD-XXXX',
  `task_id` int(11) unsigned NOT NULL COMMENT '任务ID',
  `plan_id` int(11) unsigned NOT NULL COMMENT '计划ID',
  `plan_name` varchar(100) NOT NULL DEFAULT '' COMMENT '计划名称（冗余）',
  `device_id` int(11) unsigned NOT NULL COMMENT '设备ID',
  `device_code` varchar(50) NOT NULL DEFAULT '' COMMENT '设备编码',
  `device_name` varchar(100) NOT NULL DEFAULT '' COMMENT '设备名称',
  `level_id` int(11) unsigned NOT NULL COMMENT '保养等级ID',
  `level_name` varchar(50) NOT NULL DEFAULT '' COMMENT '保养等级名称',
  `executor_id` int(11) unsigned NOT NULL COMMENT '执行人ID',
  `executor_name` varchar(50) DEFAULT '' COMMENT '执行人姓名',
  `acceptor_id` int(11) unsigned DEFAULT NULL COMMENT '验收人ID',
  `acceptor_name` varchar(50) DEFAULT '' COMMENT '验收人姓名',
  `items` json NOT NULL COMMENT '保养项目结果',
  `materials` json DEFAULT NULL COMMENT '耗材使用记录',
  `attachments` json DEFAULT NULL COMMENT '附件图片URL数组',
  `accept_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '验收状态 pending待验收/approved已通过/rejected已驳回',
  `accept_time` datetime DEFAULT NULL COMMENT '验收时间',
  `accept_remark` varchar(255) NOT NULL DEFAULT '' COMMENT '验收意见',
  `remark` text COMMENT '备注',
  `execute_time` datetime DEFAULT NULL COMMENT '执行时间',
  `normal_count` int(11) NOT NULL DEFAULT '0' COMMENT '正常项数',
  `abnormal_count` int(11) NOT NULL DEFAULT '0' COMMENT '异常项数',
  `serious_count` int(11) NOT NULL DEFAULT '0' COMMENT '严重异常项数量',
  `total_count` int(11) NOT NULL DEFAULT '0' COMMENT '总项目数量',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态 pending待验收/passed已通过/rejected已驳回',
  `reject_reason` varchar(255) DEFAULT '' COMMENT '驳回原因',
  `reject_count` int(11) NOT NULL DEFAULT '0' COMMENT '驳回次数',
  `execute_start_time` datetime DEFAULT NULL COMMENT '执行开始时间',
  `execute_end_time` datetime DEFAULT NULL COMMENT '执行结束时间',
  `execute_duration` int(11) DEFAULT NULL COMMENT '执行耗时（分钟）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `reject_history` json DEFAULT NULL COMMENT '驳回历史',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_record_code` (`record_code`),
  KEY `idx_task_id` (`task_id`),
  KEY `idx_device_id` (`device_id`),
  KEY `idx_executor_id` (`executor_id`),
  KEY `idx_status` (`status`),
  KEY `idx_accept_status` (`accept_status`),
  KEY `idx_execute_time` (`execute_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='保养记录表';

CREATE TABLE `device_maintenance_task` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `task_code` varchar(50) NOT NULL COMMENT '任务编号，格式 MNT-TASK-YYYYMMDD-XXXX',
  `plan_id` int(11) unsigned NOT NULL COMMENT '计划ID',
  `device_id` int(11) unsigned NOT NULL COMMENT '设备ID',
  `device_code` varchar(50) NOT NULL DEFAULT '' COMMENT '设备编码（冗余）',
  `device_name` varchar(100) NOT NULL DEFAULT '' COMMENT '设备名称（冗余）',
  `level_id` int(11) unsigned NOT NULL COMMENT '保养等级ID',
  `level_name` varchar(50) NOT NULL DEFAULT '' COMMENT '保养等级名称（冗余）',
  `template_id` int(11) unsigned DEFAULT NULL COMMENT '模板ID',
  `executor_id` int(11) unsigned DEFAULT NULL COMMENT '执行人ID',
  `executor_name` varchar(50) DEFAULT '' COMMENT '执行人姓名',
  `acceptor_id` int(11) unsigned DEFAULT NULL COMMENT '验收人ID',
  `acceptor_name` varchar(50) DEFAULT '' COMMENT '验收人姓名',
  `plan_execute_date` date NOT NULL COMMENT '计划执行日期',
  `actual_execute_date` datetime DEFAULT NULL COMMENT '实际执行日期',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态 pending待执行/in_progress执行中/completed已完成/overdue已逾期/cancelled已取消',
  `execute_start_time` datetime DEFAULT NULL COMMENT '执行开始时间',
  `execute_end_time` datetime DEFAULT NULL COMMENT '执行结束时间',
  `execute_duration` int(11) DEFAULT NULL COMMENT '执行耗时（分钟）',
  `is_notified` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已发送到期提醒',
  `remind_count` int(11) NOT NULL DEFAULT '0' COMMENT '提醒次数',
  `cancel_reason` varchar(255) DEFAULT '' COMMENT '取消原因',
  `remark` text COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_code` (`task_code`),
  KEY `idx_plan_id` (`plan_id`),
  KEY `idx_device_id` (`device_id`),
  KEY `idx_executor_id` (`executor_id`),
  KEY `idx_status` (`status`),
  KEY `idx_plan_execute_date` (`plan_execute_date`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COMMENT='保养任务表';

CREATE TABLE `device_maintenance_template` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `template_code` varchar(50) NOT NULL COMMENT '模板编号，格式 TPL-YYYYMMDD-XXXX',
  `template_name` varchar(100) NOT NULL COMMENT '模板名称',
  `device_type_id` int(11) unsigned DEFAULT NULL COMMENT '适用设备类型ID，关联设备分类表，空=通用',
  `level_id` int(11) unsigned NOT NULL COMMENT '保养等级ID，关联保养等级表',
  `items` json NOT NULL COMMENT '保养项目列表',
  `standard_hours` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '标准工时（小时）',
  `status` varchar(20) NOT NULL DEFAULT 'active' COMMENT '状态 active启用 inactive停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_code` (`template_code`),
  KEY `idx_level_id` (`level_id`),
  KEY `idx_device_type_id` (`device_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='保养项目模板表';

CREATE TABLE `device_master` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `category_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '所属设备分类ID（关联 device_category.id）',
  `device_code` varchar(50) NOT NULL DEFAULT '' COMMENT '设备编号',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '设备名称',
  `model` varchar(100) NOT NULL DEFAULT '' COMMENT '规格型号',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '状态：1使用中 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_category_id` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='设备台账主表（占位，待设备台账模块完善）';

CREATE TABLE `device_normal_ext` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` int(11) unsigned NOT NULL COMMENT '设备ID（device_assets.id）',
  `power_rating` varchar(50) NOT NULL DEFAULT '' COMMENT '额定功率',
  `voltage` varchar(50) NOT NULL DEFAULT '' COMMENT '电压等级',
  `weight` decimal(10,2) DEFAULT NULL COMMENT '重量(kg)',
  `dimensions` varchar(100) NOT NULL DEFAULT '' COMMENT '外形尺寸',
  `warranty_expire_date` date DEFAULT NULL COMMENT '保修截止日期',
  `calibration_cycle` int(11) DEFAULT NULL COMMENT '校准周期(月)',
  `last_calibration_date` date DEFAULT NULL COMMENT '上次校准日期',
  `next_calibration_date` date DEFAULT NULL COMMENT '下次校准日期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_asset_id` (`asset_id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COMMENT='设备台账-普通设备扩展表';

CREATE TABLE `device_remind_history` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `remind_type` varchar(30) NOT NULL COMMENT '提醒类型',
  `device_id` int(11) unsigned NOT NULL DEFAULT '0',
  `device_name` varchar(100) NOT NULL DEFAULT '',
  `device_code` varchar(50) NOT NULL DEFAULT '',
  `remind_item` varchar(255) NOT NULL DEFAULT '',
  `due_date` date DEFAULT NULL,
  `source_id` int(11) unsigned NOT NULL DEFAULT '0',
  `handler_id` int(11) unsigned NOT NULL DEFAULT '0',
  `handler_name` varchar(50) NOT NULL DEFAULT '',
  `handled_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_remind_type` (`remind_type`),
  KEY `idx_device_id` (`device_id`),
  KEY `idx_handled_at` (`handled_at`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='设备提醒历史';

CREATE TABLE `device_repair_order` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_code` varchar(50) NOT NULL COMMENT '工单编号（REP-YYYYMMDD-XXXX）',
  `device_id` int(11) unsigned NOT NULL COMMENT '设备ID（device_assets.id）',
  `device_code` varchar(50) NOT NULL COMMENT '设备编码（冗余）',
  `device_name` varchar(100) NOT NULL COMMENT '设备名称（冗余）',
  `fault_type` varchar(30) NOT NULL DEFAULT '' COMMENT '故障类型（字典 repair_fault_type）',
  `fault_description` text COMMENT '故障描述',
  `emergency_level` varchar(20) NOT NULL DEFAULT 'normal' COMMENT '紧急程度：normal/urgent/critical（字典 repair_emergency_level）',
  `source_type` varchar(30) NOT NULL DEFAULT 'manual' COMMENT '来源类型：manual/inspection/maintenance（字典 repair_source_type）',
  `source_id` int(11) DEFAULT NULL COMMENT '来源ID（巡检/保养记录ID）',
  `reporter_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '报修人ID（users.id）',
  `reporter_name` varchar(50) NOT NULL DEFAULT '' COMMENT '报修人姓名',
  `report_time` datetime NOT NULL COMMENT '报修时间',
  `handler_id` int(11) unsigned DEFAULT NULL COMMENT '处理人ID（users.id）',
  `handler_name` varchar(50) NOT NULL DEFAULT '' COMMENT '处理人姓名',
  `assign_time` datetime DEFAULT NULL COMMENT '派单时间',
  `assign_remark` varchar(255) NOT NULL DEFAULT '' COMMENT '派单备注',
  `plan_complete_time` date DEFAULT NULL COMMENT '计划完成时间',
  `actual_complete_time` datetime DEFAULT NULL COMMENT '实际完成时间',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态：pending待派单/assigned已派单/repairing维修中/accepted待验收/approved已验收/closed已关闭/rejected已驳回',
  `transfer_history` json DEFAULT NULL COMMENT '转派历史[{from,to,time,reason}]',
  `reject_reason` varchar(255) NOT NULL DEFAULT '' COMMENT '驳回原因',
  `reject_count` int(11) NOT NULL DEFAULT '0' COMMENT '驳回次数',
  `close_time` datetime DEFAULT NULL COMMENT '关闭时间',
  `diagnosis_cause` text COMMENT '故障原因分析',
  `diagnosis_conclusion` text COMMENT '诊断结论',
  `repair_plan` text COMMENT '维修方案',
  `materials` json DEFAULT NULL COMMENT '备件清单[{name,spec,quantity}]',
  `repair_process` text COMMENT '维修过程记录',
  `repair_result` varchar(20) NOT NULL DEFAULT '' COMMENT '维修结果：fixed/unfixable',
  `attachments` json DEFAULT NULL COMMENT '附件图片列表',
  `execute_start_time` datetime DEFAULT NULL COMMENT '开始维修时间',
  `execute_end_time` datetime DEFAULT NULL COMMENT '结束维修时间',
  `duration` int(11) DEFAULT NULL COMMENT '维修时长（分钟）',
  `acceptor_id` int(11) unsigned DEFAULT NULL COMMENT '验收人ID',
  `acceptor_name` varchar(50) NOT NULL DEFAULT '' COMMENT '验收人姓名',
  `accept_time` datetime DEFAULT NULL COMMENT '验收时间',
  `accept_remark` varchar(255) NOT NULL DEFAULT '' COMMENT '验收意见',
  `draft` json DEFAULT NULL COMMENT '暂存数据（员工端草稿）',
  `remark` text COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_code` (`order_code`),
  KEY `idx_device_id` (`device_id`),
  KEY `idx_status` (`status`),
  KEY `idx_reporter_id` (`reporter_id`),
  KEY `idx_handler_id` (`handler_id`),
  KEY `idx_report_time` (`report_time`),
  KEY `idx_emergency_level` (`emergency_level`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='设备维修工单';

CREATE TABLE `device_repair_order_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(11) unsigned NOT NULL COMMENT '工单ID',
  `operator_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `action` varchar(30) NOT NULL COMMENT '操作类型：create/edit/delete/assign/transfer/accept/reject/status_change/close',
  `action_desc` varchar(255) NOT NULL COMMENT '操作描述',
  `old_value` varchar(255) DEFAULT NULL COMMENT '旧值',
  `new_value` varchar(255) DEFAULT NULL COMMENT '新值',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COMMENT='维修工单操作日志';

CREATE TABLE `device_special_ext` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` int(11) unsigned NOT NULL COMMENT '设备ID（device_assets.id）',
  `special_type` varchar(30) NOT NULL DEFAULT '' COMMENT '特种设备类型（字典special_type）',
  `registration_code` varchar(50) NOT NULL DEFAULT '' COMMENT '使用登记证编号',
  `registration_authority` varchar(100) NOT NULL DEFAULT '' COMMENT '登记机关',
  `inspection_cycle` int(11) DEFAULT NULL COMMENT '检验周期(月)',
  `last_inspection_date` date DEFAULT NULL COMMENT '上次检验日期',
  `next_inspection_date` date DEFAULT NULL COMMENT '下次检验日期',
  `inspection_result` varchar(20) NOT NULL DEFAULT '' COMMENT '最近检验结果：合格/不合格/整改',
  `operator_cert_required` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否需要操作证',
  `operator_cert_number` varchar(50) NOT NULL DEFAULT '' COMMENT '操作证编号',
  `operator_ids` varchar(255) NOT NULL DEFAULT '' COMMENT '持证操作人员ID列表(逗号分隔)',
  `design_unit` varchar(100) NOT NULL DEFAULT '' COMMENT '设计单位',
  `install_unit` varchar(100) NOT NULL DEFAULT '' COMMENT '安装单位',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_asset_id` (`asset_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COMMENT='设备台账-特种设备扩展表';

CREATE TABLE `device_status_change_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` int(11) unsigned NOT NULL COMMENT '设备ID（device_assets.id）',
  `device_code` varchar(50) NOT NULL DEFAULT '' COMMENT '设备编码（冗余）',
  `device_name` varchar(100) NOT NULL DEFAULT '' COMMENT '设备名称（冗余）',
  `device_type` varchar(20) NOT NULL DEFAULT '' COMMENT '设备类型（冗余，字典device_type）',
  `from_status` varchar(20) NOT NULL DEFAULT '' COMMENT '变更前状态（字典device_status）',
  `to_status` varchar(20) NOT NULL COMMENT '变更后状态（字典device_status）',
  `reason` varchar(500) NOT NULL DEFAULT '' COMMENT '变更原因',
  `change_type` varchar(20) NOT NULL DEFAULT 'normal' COMMENT '变更类型：normal/rollback（字典change_type）',
  `operator_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '操作人ID（users.id）',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名（冗余）',
  `related_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '关联单据编号',
  `related_order_type` varchar(30) NOT NULL DEFAULT '' COMMENT '关联单据类型（字典order_type）',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  `snapshot_data` json DEFAULT NULL COMMENT '变更时设备快照',
  `change_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '变更时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_asset_id` (`asset_id`),
  KEY `idx_device_code` (`device_code`),
  KEY `idx_from_status` (`from_status`),
  KEY `idx_to_status` (`to_status`),
  KEY `idx_operator_id` (`operator_id`),
  KEY `idx_change_time` (`change_time`),
  KEY `idx_related_order_no` (`related_order_no`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COMMENT='设备状态变更记录表';

CREATE TABLE `device_status_flow_rule` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `from_status` varchar(20) NOT NULL COMMENT '源状态（字典device_status）',
  `to_status` varchar(20) NOT NULL COMMENT '目标状态（字典device_status）',
  `allow_transfer` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否允许流转：1允许 0禁止',
  `require_reason` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否必须填写原因',
  `require_order` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否必须关联单据',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_flow` (`from_status`,`to_status`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COMMENT='设备状态流转规则表';

CREATE TABLE `device_status_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` int(11) unsigned NOT NULL COMMENT '设备ID（device_assets.id）',
  `from_status` varchar(20) NOT NULL DEFAULT '' COMMENT '变更前状态（字典device_status）',
  `to_status` varchar(20) NOT NULL COMMENT '变更后状态（字典device_status）',
  `reason` varchar(255) NOT NULL DEFAULT '' COMMENT '变更原因',
  `operator_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '操作人ID（users.id）',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_asset_id` (`asset_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_operator_id` (`operator_id`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COMMENT='设备台账-状态变更日志表';

CREATE TABLE `device_vehicle_ext` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `asset_id` int(11) unsigned NOT NULL COMMENT '设备ID（device_assets.id）',
  `license_plate` varchar(10) NOT NULL DEFAULT '' COMMENT '车牌号',
  `vin` varchar(17) NOT NULL DEFAULT '' COMMENT '车架号',
  `engine_no` varchar(30) NOT NULL DEFAULT '' COMMENT '发动机号',
  `displacement` decimal(3,1) DEFAULT NULL COMMENT '排量(L)',
  `fuel_type` varchar(20) NOT NULL DEFAULT '' COMMENT '燃料类型（字典fuel_type）',
  `load_capacity` decimal(10,2) DEFAULT NULL COMMENT '核定载重(kg)',
  `seat_count` tinyint(4) DEFAULT NULL COMMENT '核定载客数',
  `mileage` decimal(10,1) DEFAULT '0.0' COMMENT '当前里程(km)',
  `last_mileage_update` datetime DEFAULT NULL COMMENT '上次更新里程时间',
  `insurance_expire_date` date DEFAULT NULL COMMENT '保险到期日',
  `inspection_expire_date` date DEFAULT NULL COMMENT '年检到期日',
  `next_maintenance_mileage` decimal(10,1) DEFAULT NULL COMMENT '下次保养里程(km)',
  `last_maintenance_date` date DEFAULT NULL COMMENT '上次保养日期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_asset_id` (`asset_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='设备台账-车辆扩展表';

CREATE TABLE `dictionary_entries` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `type_id` int(11) unsigned NOT NULL COMMENT '所属类型ID',
  `label` varchar(100) NOT NULL COMMENT '字典标签',
  `value` varchar(50) NOT NULL COMMENT '字典值',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `style` varchar(20) DEFAULT '' COMMENT '样式标签',
  `extra` text DEFAULT NULL COMMENT '扩展数据',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0禁用1启用',
  `remark` varchar(255) DEFAULT '' COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_type_value` (`type_id`,`value`),
  KEY `idx_type_id` (`type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4326 DEFAULT CHARSET=utf8mb4 COMMENT='字典条目表';

CREATE TABLE `dictionary_types` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL COMMENT '类型名称',
  `code` varchar(50) NOT NULL COMMENT '类型编码',
  `description` varchar(255) DEFAULT '' COMMENT '类型描述',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0禁用1启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=191 DEFAULT CHARSET=utf8mb4 COMMENT='字典类型表';

CREATE TABLE `diy_navbars` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(20) NOT NULL DEFAULT '' COMMENT '导航名称',
  `icon` varchar(255) NOT NULL DEFAULT '' COMMENT '图标URL',
  `active_icon` varchar(255) NOT NULL DEFAULT '' COMMENT '选中图标',
  `link` varchar(255) NOT NULL DEFAULT '' COMMENT '链接',
  `sort` int(11) NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='底部导航配置';

CREATE TABLE `diy_page_stats` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `diy_id` int(11) NOT NULL DEFAULT '0',
  `page_name` varchar(50) NOT NULL DEFAULT '',
  `user_id` int(11) NOT NULL DEFAULT '0',
  `device_id` varchar(64) NOT NULL DEFAULT '',
  `session_id` varchar(64) NOT NULL DEFAULT '',
  `source` varchar(20) NOT NULL DEFAULT 'link',
  `referer` varchar(255) NOT NULL DEFAULT '',
  `platform` varchar(20) NOT NULL DEFAULT 'h5',
  `user_agent` varchar(500) NOT NULL DEFAULT '',
  `ip` varchar(45) NOT NULL DEFAULT '',
  `visit_time` datetime NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_diy_id` (`diy_id`),
  KEY `idx_page_name` (`page_name`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_visit_time` (`visit_time`),
  KEY `idx_source` (`source`)
) ENGINE=InnoDB AUTO_INCREMENT=1669 DEFAULT CHARSET=utf8mb4 COMMENT='DIY页面访问统计';

CREATE TABLE `diy_pages` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '页面名称',
  `page_key` varchar(50) NOT NULL DEFAULT '' COMMENT '页面标识',
  `title` varchar(100) NOT NULL DEFAULT '' COMMENT '页面标题',
  `type` varchar(30) NOT NULL DEFAULT 'home' COMMENT '页面类型: home/index/mine/custom',
  `value` longtext COMMENT '页面JSON配置',
  `cover_image` varchar(255) DEFAULT '' COMMENT '封面图',
  `status` varchar(20) NOT NULL DEFAULT 'draft' COMMENT 'draft|published|scheduled',
  `version` int(11) NOT NULL DEFAULT '1' COMMENT '版本号，每次发布递增',
  `publish_time` datetime DEFAULT NULL COMMENT '定时发布时间',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_page_key` (`page_key`),
  KEY `idx_type` (`type`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COMMENT='DIY装修页面';

CREATE TABLE `eb_diy` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `version` varchar(20) NOT NULL DEFAULT '1.0' COMMENT '版本号',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '页面名称',
  `title` varchar(100) NOT NULL DEFAULT '' COMMENT '网站标题',
  `cover_image` varchar(255) NOT NULL DEFAULT '' COMMENT '封面图',
  `template_name` varchar(50) NOT NULL DEFAULT '' COMMENT '模板名称',
  `default_value` longtext COMMENT '默认数据',
  `value` longtext COMMENT '页面数据',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否使用',
  `access_type` varchar(20) NOT NULL DEFAULT 'public' COMMENT '访问权限类型：public/login/role/user',
  `access_rule` text COMMENT '权限规则JSON：role=角色ID列表,user=用户ID列表',
  `type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '页面类型',
  `is_show` tinyint(1) NOT NULL DEFAULT '0' COMMENT '显示首页',
  `is_bg_color` tinyint(1) NOT NULL DEFAULT '0' COMMENT '颜色是否选中',
  `is_bg_pic` tinyint(1) NOT NULL DEFAULT '0' COMMENT '背景图是否选中',
  `is_diy` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否diy数据',
  `color_picker` varchar(50) NOT NULL DEFAULT '#f5f5f5' COMMENT '背景颜色',
  `bg_pic` varchar(256) NOT NULL DEFAULT '' COMMENT '背景图',
  `bg_tab_val` tinyint(1) NOT NULL DEFAULT '0' COMMENT '背景图样式',
  `is_del` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '默认模板',
  `scope_type` tinyint(1) NOT NULL DEFAULT '4' COMMENT '适用范围',
  `add_time` datetime DEFAULT NULL COMMENT '添加时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_type` (`type`),
  KEY `idx_status` (`status`),
  KEY `idx_is_diy` (`is_diy`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='DIY页面装修';

CREATE TABLE `education_subsidy_standard` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `education_level` varchar(30) NOT NULL COMMENT '学历等级',
  `education_code` varchar(20) NOT NULL COMMENT '学历编码',
  `subsidy_amount` decimal(15,2) DEFAULT '0.00' COMMENT '补助金额（元/月）',
  `effective_year` int(11) NOT NULL COMMENT '生效年份',
  `sort` int(11) DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) DEFAULT '1' COMMENT '0=停用 1=启用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_education_code_year` (`education_code`,`effective_year`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='学历补助标准表';

CREATE TABLE `employee_contracts` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `profile_id` int(11) unsigned NOT NULL COMMENT '所属员工档案ID',
  `contract_no` varchar(50) NOT NULL COMMENT '合同编号',
  `contract_type` varchar(20) DEFAULT NULL COMMENT '合同类型（字典）',
  `start_date` date DEFAULT NULL COMMENT '合同开始日期',
  `end_date` date DEFAULT NULL COMMENT '合同结束日期',
  `sign_date` date DEFAULT NULL COMMENT '合同签订日期',
  `attachment` varchar(255) DEFAULT NULL COMMENT '合同附件URL',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '合同状态',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_contract_no` (`contract_no`),
  KEY `idx_profile` (`profile_id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COMMENT='员工合同表';

CREATE TABLE `employee_educations` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `profile_id` int(11) unsigned NOT NULL COMMENT '所属员工档案ID',
  `education` varchar(20) DEFAULT NULL COMMENT '最高学历（字典）',
  `school` varchar(100) DEFAULT NULL COMMENT '毕业院校',
  `major` varchar(100) DEFAULT NULL COMMENT '专业',
  `graduation_date` date DEFAULT NULL COMMENT '毕业时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_profile` (`profile_id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COMMENT='员工学历表';

CREATE TABLE `employee_emergency_contacts` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `profile_id` int(11) unsigned NOT NULL COMMENT '所属员工档案ID',
  `name` varchar(50) DEFAULT NULL COMMENT '联系人姓名',
  `relationship` varchar(20) DEFAULT NULL COMMENT '联系人关系',
  `phone` varchar(11) DEFAULT NULL COMMENT '联系人手机号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_profile` (`profile_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COMMENT='员工紧急联系人表';

CREATE TABLE `employee_profiles` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) unsigned DEFAULT NULL,
  `employee_id` varchar(20) DEFAULT NULL COMMENT '工号',
  `name` varchar(50) DEFAULT NULL COMMENT '姓名',
  `gender` tinyint(1) DEFAULT '0' COMMENT '性别',
  `phone` varchar(11) DEFAULT NULL COMMENT '手机号',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `birthday` date DEFAULT NULL COMMENT '出生日期',
  `blood_type` varchar(10) DEFAULT NULL COMMENT '血型',
  `nation` varchar(20) DEFAULT NULL COMMENT '民族',
  `political_status` varchar(20) DEFAULT NULL COMMENT '政治面貌',
  `marital_status` varchar(20) DEFAULT NULL COMMENT '婚姻状况',
  `domicile` varchar(255) DEFAULT NULL COMMENT '户籍地址',
  `address` varchar(255) DEFAULT NULL COMMENT '现住地址',
  `department_id` int(11) unsigned DEFAULT NULL COMMENT '所属部门ID',
  `position_id` int(11) unsigned DEFAULT NULL COMMENT '岗位ID',
  `rank_id` int(11) unsigned DEFAULT NULL COMMENT '职级ID(hr_rank.id)',
  `position_level` varchar(20) DEFAULT NULL COMMENT '岗位等级编码（关联salary_standard.position_code）',
  `manual_work_days` int(11) DEFAULT NULL COMMENT '手动应出勤天数（NULL=按考勤统计）',
  `assessment_score` decimal(5,2) DEFAULT '0.00' COMMENT '考核扣分/加分（负数为加分奖励）',
  `education_level` varchar(30) DEFAULT NULL COMMENT '学历',
  `education_code` varchar(20) DEFAULT NULL COMMENT '学历编码',
  `title_level` varchar(30) DEFAULT NULL COMMENT '职称',
  `title_code` varchar(20) DEFAULT NULL COMMENT '职称编码',
  `sync_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '同步状态:0=已同步 1=待同步 2=同步失败',
  `sync_time` datetime DEFAULT NULL COMMENT '最后同步时间',
  `sync_error` varchar(255) NOT NULL DEFAULT '' COMMENT '同步错误信息',
  `leader_id` int(11) DEFAULT NULL COMMENT '直属上级ID',
  `hire_date` date DEFAULT NULL COMMENT '入职日期',
  `id_card` varchar(18) DEFAULT NULL COMMENT '身份证号',
  `bank_card` varchar(30) DEFAULT NULL COMMENT '银行卡号',
  `emergency_contact` varchar(50) DEFAULT NULL COMMENT '紧急联系人',
  `emergency_phone` varchar(11) DEFAULT NULL COMMENT '紧急联系电话',
  `education` varchar(50) DEFAULT NULL COMMENT '学历',
  `title_qualification` varchar(50) DEFAULT NULL COMMENT '职称或职业资格',
  `graduate_school` varchar(100) DEFAULT NULL COMMENT '毕业院校',
  `major` varchar(100) DEFAULT NULL COMMENT '专业',
  `contract_start_date` date DEFAULT NULL COMMENT '合同签订日期',
  `contract_end_date` date DEFAULT NULL COMMENT '合同到期日期',
  `probation_end_date` date DEFAULT NULL COMMENT '转正日期',
  `probation_months` int(11) DEFAULT '3' COMMENT '试用期月数',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像URL',
  `resignation_date` date DEFAULT NULL COMMENT '离职日期',
  `employee_status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1试用期 2正式 3离职',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user` (`user_id`),
  UNIQUE KEY `uk_employee_id` (`employee_id`),
  KEY `idx_department` (`department_id`),
  KEY `idx_status` (`employee_status`),
  KEY `idx_rank_id` (`rank_id`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COMMENT='员工档案表';

CREATE TABLE `employee_transfer` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `transfer_no` varchar(50) NOT NULL DEFAULT '' COMMENT '异动编号 TR+YYYYMMDD+4位流水',
  `employee_id` int(11) NOT NULL DEFAULT '0' COMMENT '员工ID（employee_profiles.id）',
  `employee_name` varchar(50) NOT NULL DEFAULT '' COMMENT '员工姓名（冗余）',
  `employee_no` varchar(50) NOT NULL DEFAULT '' COMMENT '员工工号（冗余）',
  `transfer_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '异动类型：1转正 2调岗 3晋升 4降职 5离职 6复职',
  `transfer_type_label` varchar(20) NOT NULL DEFAULT '' COMMENT '异动类型标签',
  `before_department_id` int(11) NOT NULL DEFAULT '0' COMMENT '原部门ID',
  `before_department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '原部门名称',
  `before_position_id` int(11) NOT NULL DEFAULT '0' COMMENT '原岗位ID',
  `before_position_name` varchar(100) NOT NULL DEFAULT '' COMMENT '原岗位名称',
  `before_rank_id` int(11) NOT NULL DEFAULT '0' COMMENT '原职级ID',
  `before_rank_name` varchar(50) NOT NULL DEFAULT '' COMMENT '原职级名称',
  `before_salary` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '原薪资（元/月）',
  `after_department_id` int(11) NOT NULL DEFAULT '0' COMMENT '新部门ID',
  `after_department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '新部门名称',
  `after_position_id` int(11) NOT NULL DEFAULT '0' COMMENT '新岗位ID',
  `after_position_name` varchar(100) NOT NULL DEFAULT '' COMMENT '新岗位名称',
  `after_rank_id` int(11) NOT NULL DEFAULT '0' COMMENT '新职级ID',
  `after_rank_name` varchar(50) NOT NULL DEFAULT '' COMMENT '新职级名称',
  `after_salary` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '新薪资（元/月）',
  `transfer_reason` varchar(500) DEFAULT NULL COMMENT '异动原因',
  `transfer_date` date DEFAULT NULL COMMENT '异动生效日期',
  `apply_date` date DEFAULT NULL COMMENT '申请日期',
  `approval_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '审批状态：0草稿 1待审批 2已通过 3已驳回 4已撤销',
  `approval_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联统一审批实例ID',
  `approval_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approval_remark` varchar(500) DEFAULT NULL COMMENT '审批备注',
  `approver_id` int(11) NOT NULL DEFAULT '0' COMMENT '审批人ID（本模块冗余，供统一审批待办）',
  `approver_name` varchar(50) NOT NULL DEFAULT '' COMMENT '审批人姓名',
  `leave_type` tinyint(1) DEFAULT NULL COMMENT '离职类型：1主动辞职 2协商解除 3辞退 4合同到期不续签（仅离职）',
  `last_work_date` date DEFAULT NULL COMMENT '最后工作日（仅离职）',
  `handover_person_id` int(11) NOT NULL DEFAULT '0' COMMENT '交接人ID（仅离职）',
  `handover_person_name` varchar(50) NOT NULL DEFAULT '' COMMENT '交接人姓名（仅离职）',
  `handover_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '交接状态：0待交接 1交接中 2已完成（仅离职）',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '异动状态：0草稿 1待生效 2已生效 3已取消',
  `effective_time` datetime DEFAULT NULL COMMENT '实际生效时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_transfer_no` (`transfer_no`),
  KEY `idx_employee` (`employee_id`),
  KEY `idx_status` (`status`),
  KEY `idx_approval_status` (`approval_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='员工异动主表';

CREATE TABLE `employee_transfer_attachment` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `transfer_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联异动主表ID',
  `file_name` varchar(255) NOT NULL DEFAULT '' COMMENT '文件名',
  `file_path` varchar(500) NOT NULL DEFAULT '' COMMENT '文件路径',
  `file_size` int(11) NOT NULL DEFAULT '0' COMMENT '文件大小（字节）',
  `file_type` varchar(50) NOT NULL DEFAULT '' COMMENT '文件类型（如 application/pdf、image/jpeg）',
  `attachment_type` tinyint(1) NOT NULL DEFAULT '4' COMMENT '附件类型：1转正评估表 2调岗申请单 3离职交接单 4其他',
  `upload_by` int(11) NOT NULL DEFAULT '0' COMMENT '上传人ID',
  `upload_time` datetime DEFAULT NULL COMMENT '上传时间',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_transfer_id` (`transfer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='员工异动附件表';

CREATE TABLE `face_library` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL COMMENT '用户ID（关联 users.id）',
  `person_id` varchar(64) NOT NULL COMMENT '腾讯云人员ID',
  `person_name` varchar(60) NOT NULL COMMENT '人员名称（员工姓名）',
  `face_image` varchar(255) DEFAULT NULL COMMENT '人脸照片URL（相对路径 /uploads/face/xxx.jpg）',
  `face_id` varchar(64) DEFAULT NULL COMMENT '腾讯云人脸ID',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=无效 1=有效',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_id` (`user_id`),
  KEY `idx_person_id` (`person_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='人脸库表（后台人脸录入）';

CREATE TABLE `feedbacks` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) unsigned DEFAULT NULL,
  `type` varchar(20) NOT NULL DEFAULT '',
  `content` text,
  `images` text,
  `status` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4;

CREATE TABLE `fido2_auth_sessions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `auth_token` varchar(64) NOT NULL COMMENT '临时认证Token',
  `session_type` varchar(20) NOT NULL DEFAULT 'login' COMMENT '会话类型：login登录/register绑定',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `username` varchar(50) NOT NULL DEFAULT '' COMMENT '用户名',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT 'pending/completed/expired',
  `challenge` text COMMENT '认证挑战（二进制base64）',
  `get_args` text COMMENT '注册/认证参数 JSON',
  `jwt_token` text COMMENT '登录成功后的JWT（register会话为空）',
  `expires_at` datetime NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_auth_token` (`auth_token`),
  KEY `idx_status_expires` (`status`,`expires_at`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COMMENT='FIDO2扫码会话表（登录/绑定）';

CREATE TABLE `holiday_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `holiday_date` date NOT NULL COMMENT '日期',
  `holiday_name` varchar(50) NOT NULL DEFAULT '' COMMENT '节假日名称',
  `holiday_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=法定节假日 2=调休日 3=公司特殊日',
  `work_type` tinyint(1) DEFAULT '0' COMMENT '0=默认(按星期) 1=工作日 2=休息日 3=法定节假日',
  `multiplier` decimal(3,1) NOT NULL DEFAULT '3.0' COMMENT '加班倍数',
  `year` int(11) NOT NULL COMMENT '年份',
  `is_system` tinyint(1) DEFAULT '0' COMMENT '0=用户配置 1=系统预置',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=停用 1=启用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_holiday_date` (`holiday_date`),
  KEY `idx_year` (`year`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=59 DEFAULT CHARSET=utf8mb4 COMMENT='节假日配置表';

CREATE TABLE `hr_attendance_approval` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `approval_code` varchar(50) NOT NULL COMMENT '审批编号(AP-YYYYMMDD-XXXX)',
  `employee_id` int(11) NOT NULL COMMENT '员工ID(employee_profiles.id)',
  `employee_name` varchar(50) NOT NULL COMMENT '员工姓名(冗余)',
  `department_id` int(11) DEFAULT NULL COMMENT '部门ID(冗余)',
  `department_name` varchar(100) DEFAULT NULL COMMENT '部门名称(冗余)',
  `approval_type` varchar(30) NOT NULL DEFAULT 'leave' COMMENT 'leave请假 outing外出 travel出差 car_apply用车申请',
  `apply_date` date NOT NULL COMMENT '申请日期',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `duration` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '时长(小时)',
  `approval_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT 'pending待审批 approved已通过 rejected已驳回 canceled已撤销',
  `approver` varchar(50) DEFAULT NULL COMMENT '审批人',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_opinion` varchar(500) DEFAULT NULL COMMENT '审批意见',
  `attachments` json DEFAULT NULL COMMENT '附件列表',
  `source` varchar(20) NOT NULL DEFAULT 'dingtalk' COMMENT 'dingtalk钉钉同步 manual手动录入',
  `source_id` varchar(100) DEFAULT NULL COMMENT '来源记录ID(钉钉审批实例ID)',
  `sync_time` datetime DEFAULT NULL COMMENT '同步时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_approval_code` (`approval_code`),
  KEY `idx_employee_id` (`employee_id`),
  KEY `idx_type_status` (`approval_type`,`approval_status`),
  KEY `idx_apply_date` (`apply_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='考勤审批记录';

CREATE TABLE `hr_attendance_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL COMMENT '员工ID(employee_profiles.id)',
  `employee_name` varchar(50) NOT NULL COMMENT '员工姓名(冗余)',
  `department_id` int(11) DEFAULT NULL COMMENT '部门ID(冗余)',
  `department_name` varchar(100) DEFAULT NULL COMMENT '部门名称(冗余)',
  `check_date` date NOT NULL COMMENT '打卡日期',
  `check_time` datetime NOT NULL COMMENT '打卡时间',
  `check_result` varchar(20) NOT NULL DEFAULT 'normal' COMMENT 'normal正常 late迟到 early早退 miss缺卡',
  `check_type` varchar(20) DEFAULT NULL COMMENT 'face人脸 bluetooth蓝牙 fingerprint指纹 gps定位 manual手动',
  `check_location` varchar(255) DEFAULT NULL COMMENT '打卡地址',
  `check_device` varchar(100) DEFAULT NULL COMMENT '打卡设备',
  `source` varchar(20) NOT NULL DEFAULT 'dingtalk' COMMENT 'dingtalk钉钉同步 manual手动录入',
  `source_id` varchar(100) DEFAULT NULL COMMENT '来源记录ID(钉钉记录ID)',
  `sync_time` datetime DEFAULT NULL COMMENT '同步时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_emp_date` (`employee_id`,`check_date`),
  KEY `idx_date_time` (`check_date`,`check_time`),
  KEY `idx_employee_id` (`employee_id`),
  KEY `idx_check_date` (`check_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='考勤打卡记录';

CREATE TABLE `hr_attendance_schedule` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL COMMENT '员工ID(employee_profiles.id)',
  `schedule_date` date NOT NULL COMMENT '排班日期',
  `shift_id` int(11) DEFAULT NULL COMMENT '班次ID(空=休息日)',
  `shift_type` varchar(20) NOT NULL DEFAULT 'full' COMMENT 'full全天 half_am上午 half_pm下午',
  `source_type` varchar(20) NOT NULL DEFAULT 'manual' COMMENT 'manual手动 batch批量 import导入 copy复制',
  `creator_id` int(11) DEFAULT NULL COMMENT '创建人ID',
  `creator_name` varchar(50) DEFAULT NULL COMMENT '创建人姓名',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_emp_date` (`employee_id`,`schedule_date`),
  KEY `idx_shift_id` (`shift_id`),
  KEY `idx_schedule_date` (`schedule_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='考勤排班';

CREATE TABLE `hr_attendance_shift` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `shift_code` varchar(50) NOT NULL COMMENT '班次编码',
  `shift_name` varchar(50) NOT NULL COMMENT '班次名称',
  `shift_category` varchar(20) NOT NULL DEFAULT 'fixed' COMMENT 'fixed固定 flexible弹性',
  `department_ids` varchar(500) DEFAULT NULL COMMENT '适用部门ID列表(逗号分隔,空=全部)',
  `description` varchar(255) DEFAULT NULL COMMENT '班次描述',
  `start_time` time NOT NULL COMMENT '上班时间',
  `morning_end_time` time DEFAULT NULL,
  `end_time` time NOT NULL COMMENT '下班时间',
  `afternoon_start_time` time DEFAULT NULL,
  `clock_count` int(11) NOT NULL DEFAULT '2' COMMENT '打卡次数 2或4',
  `punch_valid_minutes` int(11) NOT NULL DEFAULT '30' COMMENT '打卡有效时间窗口(分钟)：上班可提前、下班可延后N分钟内打卡有效',
  `late_minutes` int(11) NOT NULL DEFAULT '0' COMMENT '允许迟到分钟数',
  `late_deduction_type` varchar(20) NOT NULL DEFAULT 'minute' COMMENT 'minute按分钟 count按次数',
  `early_minutes` int(11) NOT NULL DEFAULT '0' COMMENT '允许早退分钟数',
  `early_deduction_type` varchar(20) NOT NULL DEFAULT 'minute' COMMENT 'minute按分钟 count按次数',
  `absent_minutes` int(11) NOT NULL DEFAULT '30' COMMENT '旷工判定分钟数',
  `overtime_weekday_start` time DEFAULT NULL,
  `overtime_weekday_end` time DEFAULT NULL,
  `overtime_weekday_rate` decimal(3,1) NOT NULL DEFAULT '1.5',
  `overtime_weekend_start` time DEFAULT NULL,
  `overtime_weekend_end` time DEFAULT NULL,
  `overtime_weekend_rate` decimal(3,1) NOT NULL DEFAULT '2.0',
  `overtime_holiday_start` time DEFAULT NULL,
  `overtime_holiday_end` time DEFAULT NULL,
  `overtime_holiday_rate` decimal(3,1) NOT NULL DEFAULT '3.0',
  `flex_core_start` time DEFAULT NULL COMMENT '弹性核心工作时间开始',
  `flex_core_end` time DEFAULT NULL COMMENT '弹性核心工作时间结束',
  `flex_start` time DEFAULT NULL COMMENT '弹性开始时间',
  `flex_end` time DEFAULT NULL COMMENT '弹性结束时间',
  `flex_daily_hours` decimal(4,2) DEFAULT NULL COMMENT '每日总工时要求',
  `sort` int(11) NOT NULL DEFAULT '0',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_shift_code` (`shift_code`),
  KEY `idx_category` (`shift_category`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='考勤班次';

CREATE TABLE `hr_attendance_shift_swap` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `employee_a_id` int(11) NOT NULL COMMENT '员工A ID',
  `employee_b_id` int(11) NOT NULL COMMENT '员工B ID',
  `swap_date` date NOT NULL COMMENT '调班日期',
  `shift_a_id` int(11) DEFAULT NULL COMMENT '员工A原班次ID',
  `shift_b_id` int(11) DEFAULT NULL COMMENT '员工B原班次ID',
  `shift_a_new_id` int(11) DEFAULT NULL COMMENT '员工A新班次ID',
  `shift_b_new_id` int(11) DEFAULT NULL COMMENT '员工B新班次ID',
  `reason` varchar(255) DEFAULT NULL COMMENT '调班原因',
  `operator_id` int(11) NOT NULL COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL COMMENT '操作人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_swap_date` (`swap_date`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='调班记录';

CREATE TABLE `hr_leave_approval_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `request_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联假勤申请ID',
  `action` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作类型：1提交 2通过 3驳回 4撤销 5催办',
  `action_label` varchar(20) NOT NULL DEFAULT '' COMMENT '操作类型标签',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `before_status` tinyint(1) DEFAULT NULL COMMENT '操作前状态',
  `after_status` tinyint(1) DEFAULT NULL COMMENT '操作后状态',
  `remark` varchar(500) DEFAULT NULL COMMENT '操作备注',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_request_id` (`request_id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COMMENT='假勤审批日志表';

CREATE TABLE `hr_leave_request` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `request_no` varchar(30) NOT NULL DEFAULT '' COMMENT '申请编号 LQ+YYYYMMDD+XXXX',
  `applicant_id` int(11) NOT NULL DEFAULT '0' COMMENT '申请人ID',
  `applicant_name` varchar(50) NOT NULL DEFAULT '' COMMENT '申请人姓名（冗余）',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '申请部门ID',
  `department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '申请部门名称（冗余）',
  `leave_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '假勤类型：1年假 2事假 3病假 4调休 5加班 6出差 7婚假 8丧假 9产假 10其他',
  `start_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '结束日期',
  `start_time` varchar(5) DEFAULT NULL COMMENT '开始时间（半天申请 HH:mm）',
  `end_time` varchar(5) DEFAULT NULL COMMENT '结束时间（半天申请 HH:mm）',
  `total_days` decimal(5,1) NOT NULL DEFAULT '1.0' COMMENT '申请总天数（支持半天0.5）',
  `reason` varchar(500) DEFAULT NULL COMMENT '申请事由',
  `emergency_contact_name` varchar(50) DEFAULT '',
  `emergency_contact_phone` varchar(20) DEFAULT '',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0草稿 1待审批 2已通过 3已驳回 4已撤销',
  `approver_id` int(11) NOT NULL DEFAULT '0' COMMENT '审批人ID',
  `approver_name` varchar(50) NOT NULL DEFAULT '' COMMENT '审批人姓名（冗余）',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_remark` varchar(500) DEFAULT NULL COMMENT '审批备注',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_request_no` (`request_no`),
  KEY `idx_applicant` (`applicant_id`),
  KEY `idx_status` (`status`),
  KEY `idx_leave_type` (`leave_type`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COMMENT='假勤申请表';

CREATE TABLE `hr_leave_request_detail` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `request_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联假勤申请ID',
  `attachment_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '附件类型：1证明文件 2病历单 3出差单 4其他',
  `file_name` varchar(255) NOT NULL DEFAULT '' COMMENT '文件名',
  `file_path` varchar(500) NOT NULL DEFAULT '' COMMENT '文件路径',
  `file_size` int(11) NOT NULL DEFAULT '0' COMMENT '文件大小（字节）',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_request_id` (`request_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='假勤申请附件表';

CREATE TABLE `hr_rank` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `rank_name` varchar(50) NOT NULL COMMENT '职级名称',
  `rank_code` varchar(20) NOT NULL COMMENT '职级编码',
  `score_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '岗位工分单价（元/分）',
  `employee_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '员工类型：1车间岗位工 2科员',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_status_sort` (`status`,`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='职级表';

CREATE TABLE `hr_salary_calculation` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `calc_no` varchar(30) NOT NULL DEFAULT '' COMMENT '计算编号 SC+YYYYMM+XXXX',
  `calc_month` varchar(7) NOT NULL DEFAULT '' COMMENT '计算月份 YYYY-MM',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：0草稿 1已计算 2已确认 3已发放',
  `total_employee` int(11) NOT NULL DEFAULT '0' COMMENT '总人数',
  `total_base_salary` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '基本工资合计',
  `total_piecework_wage` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '计件工资合计',
  `total_allowance` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '津贴合计',
  `total_deduction` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '扣款合计',
  `total_gross_salary` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '应发工资合计',
  `total_net_salary` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '实发工资合计',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_calc_month` (`calc_month`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='工资计算主表';

CREATE TABLE `hr_salary_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '配置类型：1基本工资 2工分单价 3津贴 4扣款 5其他',
  `config_name` varchar(50) NOT NULL DEFAULT '' COMMENT '配置名称',
  `config_key` varchar(50) NOT NULL DEFAULT '' COMMENT '配置键（唯一）',
  `rank_id` int(11) NOT NULL DEFAULT '0' COMMENT '职级ID（关联hr_rank）',
  `rank_name` varchar(50) NOT NULL DEFAULT '' COMMENT '职级名称（冗余）',
  `employee_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '员工类型：1车间岗位工 2科员',
  `dimension_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '维度类型：1全局 2按岗位 3按职级 4按部门',
  `dimension_value` varchar(50) NOT NULL DEFAULT '' COMMENT '维度值（岗位/职级/部门ID，全局为空）',
  `dimension_label` varchar(50) NOT NULL DEFAULT '' COMMENT '维度标签',
  `value_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '值类型：1固定金额 2百分比 3公式',
  `value` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '配置值',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位（元/%/分）',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用：1启用 0停用',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_config_type` (`config_type`),
  KEY `idx_dimension` (`dimension_type`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='工资配置表';

CREATE TABLE `hr_salary_detail` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `calc_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工资计算主表ID',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '员工ID',
  `user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '员工姓名',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '部门ID',
  `department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '部门名称',
  `rank_id` int(11) NOT NULL DEFAULT '0' COMMENT '职级ID',
  `rank_name` varchar(50) NOT NULL DEFAULT '' COMMENT '职级名称',
  `employee_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '员工类型：1车间岗位工 2科员',
  `position_id` int(11) NOT NULL DEFAULT '0' COMMENT '岗位ID',
  `position_name` varchar(50) NOT NULL DEFAULT '' COMMENT '岗位名称',
  `base_salary` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '基本工资',
  `piecework_score` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '工分',
  `piecework_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '工分单价',
  `piecework_wage` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '计件工资',
  `attendance_days` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '出勤天数',
  `allowance_json` json DEFAULT NULL COMMENT '津贴明细JSON',
  `allowance_total` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '津贴合计',
  `deduction_json` json DEFAULT NULL COMMENT '扣款明细JSON',
  `deduction_total` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '扣款合计',
  `gross_salary` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '应发工资',
  `net_salary` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '实发工资',
  `detail_json` json DEFAULT NULL COMMENT '完整明细快照',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_calc_id` (`calc_id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COMMENT='工资计算明细表';

CREATE TABLE `hr_salary_slip` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `slip_no` varchar(50) NOT NULL DEFAULT '' COMMENT '工资条编号 SL+YYYYMMDD+4位流水',
  `calc_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工资计算主表ID',
  `calc_month` varchar(7) NOT NULL DEFAULT '' COMMENT '工资月份 YYYY-MM',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '员工ID',
  `user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '员工姓名',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '部门ID',
  `department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '部门名称',
  `rank_id` int(11) NOT NULL DEFAULT '0' COMMENT '职级ID',
  `rank_name` varchar(50) NOT NULL DEFAULT '' COMMENT '职级名称',
  `employee_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '员工类型：1车间岗位工 2科员',
  `base_salary` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '基本工资',
  `piecework_score` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '工分（仅车间岗位工）',
  `piecework_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '工分单价（仅车间岗位工）',
  `piecework_wage` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '计件工资（仅车间岗位工）',
  `allowance_json` json DEFAULT NULL COMMENT '津贴明细JSON',
  `allowance_total` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '津贴合计',
  `deduction_json` json DEFAULT NULL COMMENT '扣款明细JSON',
  `deduction_total` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '扣款合计',
  `gross_salary` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '应发工资',
  `net_salary` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '实发工资',
  `slip_data` json DEFAULT NULL COMMENT '工资条完整数据快照',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0草稿 1已生成 2已发送 3已签收',
  `generated_at` datetime DEFAULT NULL COMMENT '生成时间',
  `sent_at` datetime DEFAULT NULL COMMENT '发送时间',
  `signed_at` datetime DEFAULT NULL COMMENT '签收时间',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_name_month` (`calc_month`,`user_name`),
  KEY `idx_calc_id` (`calc_id`),
  KEY `idx_status` (`status`),
  KEY `idx_department` (`department_id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COMMENT='工资条表';

CREATE TABLE `inventory_diff_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `plan_id` int(11) NOT NULL DEFAULT '0' COMMENT '盘点单ID',
  `task_id` int(11) NOT NULL DEFAULT '0' COMMENT '盘点任务ID',
  `asset_id` int(11) NOT NULL DEFAULT '0' COMMENT '资产档案ID',
  `diff_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=盘盈 2=盘亏',
  `system_quantity` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '系统数量',
  `actual_quantity` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '实际数量',
  `diff_quantity` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '差异数量',
  `process_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=待处理 1=已确认 2=已忽略',
  `process_type` tinyint(1) DEFAULT NULL COMMENT '1=调整系统数量 2=补充入库 3=报废出库',
  `process_remark` varchar(255) NOT NULL DEFAULT '' COMMENT '处理备注',
  `processed_by` int(11) NOT NULL DEFAULT '0' COMMENT '处理人ID',
  `processed_at` datetime DEFAULT NULL COMMENT '处理时间',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_plan_id` (`plan_id`),
  KEY `idx_task_id` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='差异处理记录表';

CREATE TABLE `inventory_plan` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `plan_no` varchar(50) NOT NULL DEFAULT '' COMMENT '计划编号 PD+YYYYMMDD+4位流水',
  `plan_name` varchar(100) NOT NULL DEFAULT '' COMMENT '计划名称',
  `plan_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '盘点类型：1全盘 2抽盘 3循环盘点',
  `warehouse_id` int(11) NOT NULL DEFAULT '0' COMMENT '盘点仓库ID',
  `warehouse_name` varchar(50) NOT NULL DEFAULT '' COMMENT '仓库名称（冗余）',
  `scope_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '范围类型：1全仓 2按货位 3按物料分类 4按物料',
  `scope_value` varchar(500) DEFAULT NULL COMMENT '范围值 JSON（货位/分类/物料ID列表）',
  `inventory_method` tinyint(1) NOT NULL DEFAULT '1' COMMENT '盘点方式：1明盘 2暗盘',
  `plan_start_date` date DEFAULT NULL COMMENT '计划开始日期',
  `plan_end_date` date DEFAULT NULL COMMENT '计划结束日期',
  `expected_duration` decimal(6,1) NOT NULL DEFAULT '1.0' COMMENT '预计耗时（小时）',
  `responsible_person_id` int(11) NOT NULL DEFAULT '0' COMMENT '负责人ID',
  `responsible_person_name` varchar(50) NOT NULL DEFAULT '' COMMENT '负责人姓名',
  `participants` json DEFAULT NULL COMMENT '参与人员ID列表',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '计划状态：0草稿 1待审核 2已审核 3执行中 4已完成 5已取消',
  `approval_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '审批状态：0未提交 1待审批 2已通过 3已驳回',
  `approval_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approval_remark` varchar(500) DEFAULT NULL COMMENT '审批备注',
  `actual_start_time` datetime DEFAULT NULL COMMENT '实际开始时间',
  `actual_end_time` datetime DEFAULT NULL COMMENT '实际结束时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plan_no` (`plan_no`),
  KEY `idx_status` (`status`),
  KEY `idx_warehouse` (`warehouse_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='盘点计划表';

CREATE TABLE `inventory_result` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `plan_id` int(11) NOT NULL DEFAULT '0' COMMENT '盘点计划ID',
  `task_id` int(11) NOT NULL DEFAULT '0' COMMENT '盘点任务ID',
  `material_id` int(11) NOT NULL DEFAULT '0' COMMENT '物料ID',
  `material_code` varchar(50) NOT NULL DEFAULT '' COMMENT '物料编码（冗余）',
  `material_name` varchar(100) NOT NULL DEFAULT '' COMMENT '物料名称（冗余）',
  `specification` varchar(100) DEFAULT NULL COMMENT '规格型号（冗余）',
  `unit` varchar(20) DEFAULT NULL COMMENT '单位（冗余）',
  `system_quantity` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '系统账面库存数量',
  `actual_quantity` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '实际盘点数量',
  `difference_quantity` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '差异数量',
  `difference_type` tinyint(1) NOT NULL DEFAULT '3' COMMENT '差异类型：1盘盈 2盘亏 3无差异',
  `location_id` int(11) NOT NULL DEFAULT '0' COMMENT '货位ID',
  `location_name` varchar(100) DEFAULT NULL COMMENT '货位名称（冗余）',
  `batch_no` varchar(50) DEFAULT NULL COMMENT '批次号',
  `scanned_by` int(11) NOT NULL DEFAULT '0' COMMENT '扫码人ID',
  `scanned_at` datetime DEFAULT NULL COMMENT '扫码时间',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '结果状态：0待确认 1已确认 2已调整',
  `process_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '处理状态：0待处理 1已处理 2已忽略',
  `process_remark` varchar(500) DEFAULT NULL COMMENT '处理备注',
  `process_by` int(11) NOT NULL DEFAULT '0' COMMENT '处理人ID',
  `process_at` datetime DEFAULT NULL COMMENT '处理时间',
  `adjust_order_no` varchar(50) DEFAULT NULL COMMENT '关联调整单编号',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_plan` (`plan_id`),
  KEY `idx_task` (`task_id`),
  KEY `idx_material` (`material_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='盘点结果表';

CREATE TABLE `inventory_task` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `task_no` varchar(50) NOT NULL DEFAULT '' COMMENT '任务编号',
  `plan_id` int(11) NOT NULL DEFAULT '0' COMMENT '盘点计划ID',
  `plan_no` varchar(50) NOT NULL DEFAULT '' COMMENT '计划编号（冗余）',
  `assignee_id` int(11) NOT NULL DEFAULT '0' COMMENT '被分配人ID',
  `assignee_name` varchar(50) NOT NULL DEFAULT '' COMMENT '被分配人姓名',
  `location_id` int(11) NOT NULL DEFAULT '0' COMMENT '货位ID',
  `location_name` varchar(100) NOT NULL DEFAULT '' COMMENT '货位名称',
  `material_ids` json DEFAULT NULL COMMENT '物料ID列表',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '任务状态：0待执行 1执行中 2已完成 3已逾期',
  `expected_start_time` datetime DEFAULT NULL COMMENT '预计开始时间',
  `expected_end_time` datetime DEFAULT NULL COMMENT '预计结束时间',
  `actual_start_time` datetime DEFAULT NULL COMMENT '实际开始时间',
  `actual_end_time` datetime DEFAULT NULL COMMENT '实际结束时间',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_plan` (`plan_id`),
  KEY `idx_assignee` (`assignee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='盘点任务表';

CREATE TABLE `logistics_call_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `provider_code` varchar(30) NOT NULL DEFAULT '' COMMENT '调用的服务商',
  `api_method` varchar(30) NOT NULL DEFAULT '' COMMENT '调用方法：query/subscribe/callback',
  `request_params` text COMMENT '请求参数（JSON）',
  `response_data` text COMMENT '返回数据（JSON）',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '调用状态：1成功 0失败',
  `error_message` varchar(255) DEFAULT NULL COMMENT '错误信息',
  `ip` varchar(50) DEFAULT NULL COMMENT '调用方IP',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_provider` (`provider_code`),
  KEY `idx_status` (`status`),
  KEY `idx_create` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=119 DEFAULT CHARSET=utf8mb4 COMMENT='物流调用日志表';

CREATE TABLE `logistics_track_cache` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `ship_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联发货单ID',
  `tracking_no` varchar(100) NOT NULL DEFAULT '' COMMENT '物流单号（冗余便于查询）',
  `logistics_code` varchar(50) DEFAULT NULL COMMENT '物流公司编码（如 SF）',
  `track_data` json DEFAULT NULL COMMENT '完整物流节点列表（JSON）',
  `latest_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '最新物流状态：1已揽收 2运输中 3派送中 4已签收 5异常',
  `latest_context` varchar(500) DEFAULT NULL COMMENT '最新状态描述',
  `last_update_time` datetime DEFAULT NULL COMMENT '最后更新时间',
  `next_update_strategy` varchar(50) DEFAULT NULL COMMENT '下次更新策略',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ship_order` (`ship_order_id`),
  KEY `idx_tracking_no` (`tracking_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='物流轨迹缓存表';

CREATE TABLE `menus` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '父级ID',
  `name` varchar(50) NOT NULL COMMENT '菜单名称',
  `path` varchar(200) DEFAULT '' COMMENT '路由路径',
  `icon` varchar(50) DEFAULT '' COMMENT '图标',
  `permission` varchar(100) DEFAULT '' COMMENT '权限标识',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0禁用1启用',
  `type` tinyint(1) NOT NULL DEFAULT '2' COMMENT '1目录2菜单3按钮',
  `is_system` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否系统内置',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_parent` (`parent_id`),
  KEY `idx_permission` (`permission`)
) ENGINE=InnoDB AUTO_INCREMENT=332 DEFAULT CHARSET=utf8mb4 COMMENT='菜单表';

CREATE TABLE `monitor_data` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `cpu_usage` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT 'CPU使用率%',
  `cpu_load_1` decimal(5,2) NOT NULL DEFAULT '0.00',
  `cpu_load_5` decimal(5,2) NOT NULL DEFAULT '0.00',
  `cpu_load_15` decimal(5,2) NOT NULL DEFAULT '0.00',
  `memory_usage` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '内存使用率%',
  `memory_used` bigint(20) NOT NULL DEFAULT '0',
  `memory_total` bigint(20) NOT NULL DEFAULT '0',
  `swap_usage` decimal(5,2) NOT NULL DEFAULT '0.00',
  `disk_usage` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '磁盘使用率%',
  `disk_used` bigint(20) NOT NULL DEFAULT '0',
  `disk_total` bigint(20) NOT NULL DEFAULT '0',
  `disk_read` bigint(20) unsigned NOT NULL DEFAULT '0' COMMENT '磁盘读取字节数',
  `disk_write` bigint(20) unsigned NOT NULL DEFAULT '0' COMMENT '磁盘写入字节数',
  `net_send` bigint(20) unsigned NOT NULL DEFAULT '0' COMMENT '网络发送字节数',
  `net_recv` bigint(20) unsigned NOT NULL DEFAULT '0' COMMENT '网络接收字节数',
  `online_users` int(11) NOT NULL DEFAULT '0',
  `collected_at` datetime NOT NULL COMMENT '采集时间',
  PRIMARY KEY (`id`),
  KEY `idx_collected_at` (`collected_at`)
) ENGINE=InnoDB AUTO_INCREMENT=41473 DEFAULT CHARSET=utf8mb4 COMMENT='监控数据表';

CREATE TABLE `overtime_rule_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rule_name` varchar(50) NOT NULL DEFAULT '' COMMENT '规则名称',
  `rule_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=默认规则 2=节假日规则 3=特殊规则',
  `week_day` tinyint(1) NOT NULL DEFAULT '0' COMMENT '适用星期（1-7，0=全部）',
  `date_type` varchar(20) NOT NULL DEFAULT 'workday' COMMENT '日期类型：workday/weekend/holiday/special',
  `multiplier` decimal(3,1) NOT NULL DEFAULT '1.5' COMMENT '加班倍数',
  `priority` tinyint(1) NOT NULL DEFAULT '1' COMMENT '优先级（数字越大越优先）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=停用 1=启用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_type` (`rule_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='加班规则配置表';

CREATE TABLE `page_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `page_key` varchar(50) NOT NULL DEFAULT '' COMMENT '页面标识',
  `version` int(11) NOT NULL DEFAULT '0' COMMENT '版本号',
  `dsl` longtext COMMENT 'DSL配置',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `operator` varchar(50) DEFAULT '' COMMENT '操作人',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_page_key` (`page_key`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='页面发布历史';

CREATE TABLE `pages` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `page_key` varchar(50) NOT NULL DEFAULT '' COMMENT '页面标识',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '页面名称',
  `dsl` longtext COMMENT 'DSL配置',
  `status` varchar(20) NOT NULL DEFAULT 'draft' COMMENT 'draft|published|modified',
  `schedule_time` datetime DEFAULT NULL COMMENT '定时发布时间',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_page_key` (`page_key`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='页面表';

CREATE TABLE `permissions` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '权限名称',
  `code` varchar(100) NOT NULL DEFAULT '' COMMENT '权限编码',
  `type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1菜单 2按钮 3接口',
  `parent_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '父级ID',
  `module` varchar(50) DEFAULT NULL COMMENT '所属模块',
  `path` varchar(200) DEFAULT NULL COMMENT '路由路径',
  `icon` varchar(50) DEFAULT NULL COMMENT '菜单图标',
  `api_url` varchar(200) DEFAULT NULL COMMENT 'API路径',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序权重',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1启用 0禁用',
  `platform` tinyint(1) NOT NULL DEFAULT '1' COMMENT '平台类型:0=通用 1=后台管理 2=应用',
  `description` varchar(255) DEFAULT NULL COMMENT '权限描述',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_parent` (`parent_id`),
  KEY `idx_type` (`type`)
) ENGINE=InnoDB AUTO_INCREMENT=1707 DEFAULT CHARSET=utf8mb4 COMMENT='权限表';

CREATE TABLE `personal_assets` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '保管人ID',
  `asset_type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1=物料/配件 2=固定资产 3=工具',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '配件ID(asset_type=1)',
  `asset_archive_id` int(11) NOT NULL DEFAULT '0' COMMENT '资产档案ID(asset_type=2)',
  `asset_code` varchar(50) NOT NULL DEFAULT '' COMMENT '资产编码',
  `asset_name` varchar(100) NOT NULL DEFAULT '' COMMENT '资产名称',
  `specification` varchar(100) NOT NULL DEFAULT '' COMMENT '规格型号',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位',
  `location` varchar(100) NOT NULL DEFAULT '' COMMENT '存放位置',
  `brand` varchar(50) NOT NULL DEFAULT '' COMMENT '品牌',
  `quantity` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '当前数量',
  `initial_quantity` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '初始数量',
  `source_type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1=总仓领料 2=资产领用 3=调拨转入 4=盘点入库',
  `source_id` int(11) NOT NULL DEFAULT '0' COMMENT '来源单据ID',
  `source_no` varchar(50) NOT NULL DEFAULT '' COMMENT '来源单号',
  `purchase_order_id` int(11) DEFAULT NULL COMMENT '关联采购订单ID',
  `purchase_order_no` varchar(50) DEFAULT NULL COMMENT '关联采购订单编号',
  `purchase_order_item_id` int(11) DEFAULT NULL COMMENT '关联采购订单明细ID',
  `warehouse_in_id` int(11) DEFAULT NULL COMMENT '关联入库单ID',
  `warehouse_in_no` varchar(50) DEFAULT NULL COMMENT '关联入库单编号',
  `project_id` int(11) DEFAULT NULL COMMENT '关联项目ID',
  `project_no` varchar(50) DEFAULT NULL COMMENT '关联项目编号',
  `project_name` varchar(100) DEFAULT NULL COMMENT '关联项目名称',
  `sales_order_id` int(11) DEFAULT NULL COMMENT '关联销售订单ID',
  `sales_order_no` varchar(50) DEFAULT NULL COMMENT '关联销售订单编号',
  `production_order_id` int(11) DEFAULT NULL COMMENT '关联生产工单ID',
  `production_order_no` varchar(50) DEFAULT NULL COMMENT '关联生产工单编号',
  `supplier_id` int(11) DEFAULT NULL COMMENT '供应商ID',
  `supplier_name` varchar(100) DEFAULT NULL COMMENT '供应商名称',
  `purchase_date` date DEFAULT NULL COMMENT '采购日期',
  `warranty_period` int(11) DEFAULT NULL COMMENT '保修期（月）',
  `warranty_end_date` date DEFAULT NULL COMMENT '保修截止日期',
  `original_value` decimal(15,2) DEFAULT NULL COMMENT '原值(仅资产)',
  `asset_status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1=正常 2=维修中 3=闲置 4=待报废',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1=有效 0=已出库/已退还',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user` (`user_id`,`status`),
  KEY `idx_type` (`asset_type`,`status`),
  KEY `idx_status` (`asset_status`),
  KEY `idx_source` (`source_type`,`source_id`),
  KEY `idx_purchase_order_id` (`purchase_order_id`),
  KEY `idx_warehouse_in_id` (`warehouse_in_id`),
  KEY `idx_supplier_id` (`supplier_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COMMENT='个人资产表';

CREATE TABLE `pick_apply` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `apply_no` varchar(50) NOT NULL DEFAULT '',
  `user_id` int(11) NOT NULL DEFAULT '0',
  `user_name` varchar(50) NOT NULL DEFAULT '',
  `department_id` int(11) NOT NULL DEFAULT '0',
  `department_name` varchar(100) NOT NULL DEFAULT '',
  `material_id` int(11) NOT NULL DEFAULT '0',
  `material_code` varchar(50) NOT NULL DEFAULT '',
  `material_name` varchar(200) NOT NULL DEFAULT '',
  `specification` varchar(100) NOT NULL DEFAULT '',
  `unit` varchar(20) NOT NULL DEFAULT '',
  `apply_quantity` decimal(15,2) NOT NULL DEFAULT '0.00',
  `work_order_no` varchar(50) NOT NULL DEFAULT '',
  `purpose` varchar(500) NOT NULL DEFAULT '',
  `purchase_order_id` int(11) DEFAULT NULL COMMENT '关联采购订单ID',
  `purchase_order_no` varchar(50) DEFAULT NULL COMMENT '关联采购订单编号',
  `supplier_name` varchar(100) DEFAULT NULL COMMENT '供应商名称',
  `remark` varchar(200) NOT NULL DEFAULT '',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0草稿 1待审批 2已通过 3已驳回 4已取消',
  `approval_instance_id` int(11) NOT NULL DEFAULT '0' COMMENT '审批中心实例ID',
  `approver_id` int(11) NOT NULL DEFAULT '0',
  `approve_time` datetime DEFAULT NULL,
  `approve_remark` varchar(255) NOT NULL DEFAULT '',
  `reject_reason` varchar(255) NOT NULL DEFAULT '',
  `pick_order_id` int(11) NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_apply_no` (`apply_no`),
  KEY `idx_user` (`user_id`,`status`),
  KEY `idx_status` (`status`),
  KEY `idx_material` (`material_id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COMMENT='配件领用申请表';

CREATE TABLE `platform_active_versions` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `platform` varchar(20) NOT NULL DEFAULT '' COMMENT '平台标识',
  `version_id` int(11) NOT NULL DEFAULT '0' COMMENT '当前生效版本ID',
  `version_code` varchar(20) NOT NULL DEFAULT '' COMMENT '版本号',
  `gray_ratio` int(11) NOT NULL DEFAULT '100' COMMENT '当前灰度比例',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_platform` (`platform`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COMMENT='各端当前生效版本表';

CREATE TABLE `positions` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `department_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '所属部门ID',
  `name` varchar(100) NOT NULL COMMENT '岗位名称',
  `code` varchar(50) NOT NULL COMMENT '岗位编码',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0禁用1启用',
  `description` varchar(255) DEFAULT '' COMMENT '岗位描述',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_dept` (`department_id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COMMENT='岗位表';

CREATE TABLE `production_dispatch` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `dispatch_no` varchar(50) NOT NULL DEFAULT '' COMMENT '派工单编号 DP+YYYYMMDD+4位流水',
  `work_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工单ID',
  `work_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '工单编号（冗余）',
  `dispatch_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '派工类型：1个人派工 2班组派工',
  `dispatcher_id` int(11) NOT NULL DEFAULT '0' COMMENT '派工人ID（车间主任/班组长）',
  `dispatcher_name` varchar(50) NOT NULL DEFAULT '' COMMENT '派工人姓名（冗余）',
  `dispatch_date` date DEFAULT NULL COMMENT '派工日期',
  `planned_start_date` date DEFAULT NULL COMMENT '计划开始日期',
  `planned_end_date` date DEFAULT NULL COMMENT '计划完成日期',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '派工状态：0草稿 1已派工 2执行中 3已完成 4已撤销',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dispatch_no` (`dispatch_no`),
  KEY `idx_dispatch_wo` (`work_order_id`),
  KEY `idx_dispatch_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='工单派工主表';

CREATE TABLE `production_dispatch_task` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `dispatch_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联派工主表ID',
  `work_order_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工单明细ID（工序任务）',
  `process_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工序ID',
  `process_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工序名称（冗余）',
  `workstation_id` int(11) NOT NULL DEFAULT '0' COMMENT '指定工位ID',
  `workstation_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工位名称（冗余）',
  `device_id` int(11) NOT NULL DEFAULT '0' COMMENT '指定设备ID',
  `device_name` varchar(100) NOT NULL DEFAULT '' COMMENT '设备名称（冗余）',
  `worker_id` int(11) NOT NULL DEFAULT '0' COMMENT '被派工人ID（个人派工）',
  `worker_name` varchar(50) NOT NULL DEFAULT '' COMMENT '被派工人姓名（冗余）',
  `team_id` int(11) NOT NULL DEFAULT '0' COMMENT '被派班组ID（班组派工）',
  `team_name` varchar(50) NOT NULL DEFAULT '' COMMENT '班组名称（冗余）',
  `planned_quantity` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '计划完成数量',
  `completed_quantity` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '已完成数量',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '任务状态：0待执行 1执行中 2已完成',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT '执行顺序',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_task_dispatch` (`dispatch_id`),
  KEY `idx_task_process` (`process_id`),
  KEY `idx_task_worker` (`worker_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='派工任务明细表';

CREATE TABLE `production_order` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '工单编号 PO+YYYYMMDD+4位流水',
  `order_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '工单类型：1生产工单 2维修工单',
  `source_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '来源类型：1销售订单 2维修订单 0手工',
  `source_id` int(11) NOT NULL DEFAULT '0' COMMENT '来源单据ID',
  `source_no` varchar(50) NOT NULL DEFAULT '' COMMENT '来源单据编号（冗余）',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID（business_products）',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称（冗余）',
  `product_spec` varchar(100) NOT NULL DEFAULT '' COMMENT '产品规格型号（冗余）',
  `process_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工序ID',
  `process_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工序名称（冗余）',
  `workstation_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工位ID',
  `workstation_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工位名称（冗余）',
  `customer_id` int(11) NOT NULL DEFAULT '0' COMMENT '客户ID（维修工单时必填）',
  `customer_name` varchar(50) NOT NULL DEFAULT '' COMMENT '客户名称（冗余）',
  `plan_quantity` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '计划数量',
  `completed_quantity` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '完成数量',
  `progress` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '进度百分比（完成/计划*100）',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0待派工 1已派工 2进行中 3待质检 4已完成 5已关闭',
  `priority` tinyint(1) NOT NULL DEFAULT '1' COMMENT '优先级：1普通 2紧急 3特急',
  `planned_start_date` date DEFAULT NULL COMMENT '计划开始日期',
  `planned_end_date` date DEFAULT NULL COMMENT '计划完成日期',
  `actual_start_date` date DEFAULT NULL COMMENT '实际开始日期',
  `actual_end_date` date DEFAULT NULL COMMENT '实际完成日期',
  `responsible_person_id` int(11) NOT NULL DEFAULT '0' COMMENT '负责人ID',
  `responsible_person_name` varchar(50) NOT NULL DEFAULT '' COMMENT '负责人姓名（冗余）',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '负责部门ID',
  `department_name` varchar(50) NOT NULL DEFAULT '' COMMENT '负责部门名称（冗余）',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_status` (`status`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_source_no` (`source_no`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COMMENT='生产/维修工单主表';

CREATE TABLE `production_order_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工单主表ID',
  `material_id` int(11) NOT NULL DEFAULT '0' COMMENT '物料ID（warehouse_material）',
  `process_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工序ID',
  `process_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工序名称（冗余）',
  `workstation_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工位ID',
  `workstation_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工位名称（冗余）',
  `work_duration` decimal(6,2) NOT NULL DEFAULT '0.00' COMMENT '计划工时（小时）',
  `material_code` varchar(50) NOT NULL DEFAULT '' COMMENT '物料编码（冗余）',
  `material_name` varchar(200) NOT NULL DEFAULT '' COMMENT '物料名称（冗余）',
  `specification` varchar(100) NOT NULL DEFAULT '' COMMENT '规格型号（冗余）',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位（冗余）',
  `plan_quantity` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '计划用量',
  `actual_quantity` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '实际用量',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='工单明细表（物料清单）';

CREATE TABLE `production_process` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `process_code` varchar(50) NOT NULL DEFAULT '' COMMENT '工序编码（唯一）',
  `process_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工序名称',
  `process_group` varchar(50) NOT NULL DEFAULT '' COMMENT '工序组',
  `product_type` varchar(50) NOT NULL DEFAULT '' COMMENT '适用产品类型',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT '工序执行顺序',
  `is_required` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否必须工序：1是 0否',
  `standard_score` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '工分定额',
  `standard_hours` decimal(6,2) NOT NULL DEFAULT '0.00' COMMENT '标准工时（小时）',
  `description` varchar(500) DEFAULT NULL COMMENT '工序描述',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_process_code` (`process_code`),
  KEY `idx_group` (`process_group`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COMMENT='工序表';

CREATE TABLE `production_process_workstation` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `process_id` int(11) NOT NULL DEFAULT '0' COMMENT '工序ID（production_process）',
  `workstation_id` int(11) NOT NULL DEFAULT '0' COMMENT '工位ID（production_workstation）',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认工序：1是 0否',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pw` (`process_id`,`workstation_id`),
  KEY `idx_pw_process` (`process_id`),
  KEY `idx_pw_workstation` (`workstation_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='工位-工序关联表';

CREATE TABLE `production_report` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `report_no` varchar(50) NOT NULL DEFAULT '' COMMENT '报工单编号 PR+YYYYMMDD+4位流水',
  `work_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工单ID',
  `work_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '工单编号（冗余）',
  `process_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工序ID',
  `process_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工序名称（冗余）',
  `workstation_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工位ID',
  `workstation_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工位名称（冗余）',
  `device_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联设备ID（device_assets）',
  `device_name` varchar(100) NOT NULL DEFAULT '' COMMENT '设备名称（冗余）',
  `device_code` varchar(50) NOT NULL DEFAULT '' COMMENT '设备编码（冗余）',
  `quantity` int(11) NOT NULL DEFAULT '1' COMMENT '完成数量（件）',
  `duration` decimal(6,1) NOT NULL DEFAULT '0.0' COMMENT '设备使用时长（小时）',
  `photos` json DEFAULT NULL COMMENT '作业照片URL数组',
  `calculated_score` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '自动计算工分（工序定额×数量）',
  `report_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '报工模式：1个人报工 2团队协作',
  `task_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '任务类型：1拆解 2焊接 3维修 4组装 5喷漆 6质检 7其他',
  `task_description` varchar(500) DEFAULT NULL COMMENT '任务描述',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '部门ID',
  `department_name` varchar(50) NOT NULL DEFAULT '' COMMENT '部门名称（冗余）',
  `reporter_id` int(11) NOT NULL DEFAULT '0' COMMENT '报工人ID',
  `reporter_name` varchar(50) NOT NULL DEFAULT '' COMMENT '报工人姓名（冗余）',
  `report_date` date DEFAULT NULL COMMENT '报工日期',
  `total_score` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '总工分数',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0草稿 1待审核 2已通过 3已驳回 4已撤销',
  `auditor_id` int(11) NOT NULL DEFAULT '0' COMMENT '审核人ID',
  `auditor_name` varchar(50) NOT NULL DEFAULT '' COMMENT '审核人姓名（冗余）',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核备注',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_report_no` (`report_no`),
  KEY `idx_work_order_id` (`work_order_id`),
  KEY `idx_status` (`status`),
  KEY `idx_report_date` (`report_date`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='生产报工主表';

CREATE TABLE `production_report_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `report_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联报工主表ID',
  `worker_id` int(11) NOT NULL DEFAULT '0' COMMENT '工人ID',
  `worker_name` varchar(50) NOT NULL DEFAULT '' COMMENT '工人姓名（冗余）',
  `allocated_score` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '分配工分数',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_report_id` (`report_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='报工分配明细表';

CREATE TABLE `production_report_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `report_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联报工主表ID',
  `action` tinyint(1) NOT NULL DEFAULT '1' COMMENT '操作类型：1提交 2审核通过 3审核驳回 4撤销',
  `action_label` varchar(20) NOT NULL DEFAULT '' COMMENT '操作类型标签',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `before_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作前状态',
  `after_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作后状态',
  `remark` varchar(500) DEFAULT NULL COMMENT '操作备注',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_report_id` (`report_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='报工审核日志表';

CREATE TABLE `production_report_material` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `report_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联报工主表ID',
  `material_id` int(11) NOT NULL DEFAULT '0' COMMENT '物料ID（warehouse_material）',
  `personal_asset_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联个人资产ID',
  `material_code` varchar(50) NOT NULL DEFAULT '' COMMENT '物料编码（冗余）',
  `material_name` varchar(200) NOT NULL DEFAULT '' COMMENT '物料名称（冗余）',
  `specification` varchar(100) NOT NULL DEFAULT '' COMMENT '规格型号（冗余）',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位（冗余）',
  `quantity` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '使用数量',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_rm_report` (`report_id`),
  KEY `idx_personal_asset_id` (`personal_asset_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报工材料明细表';

CREATE TABLE `production_schedule` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `dispatch_task_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联派工任务明细ID',
  `work_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工单ID',
  `work_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '工单编号（冗余）',
  `process_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工序ID',
  `process_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工序名称（冗余）',
  `workstation_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工位ID',
  `workstation_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工位名称（冗余）',
  `device_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联设备ID',
  `device_name` varchar(100) NOT NULL DEFAULT '' COMMENT '设备名称（冗余）',
  `planned_start_time` datetime DEFAULT NULL COMMENT '计划开始时间',
  `planned_end_time` datetime DEFAULT NULL COMMENT '计划结束时间',
  `actual_start_time` datetime DEFAULT NULL COMMENT '实际开始时间（报工后回写）',
  `actual_end_time` datetime DEFAULT NULL COMMENT '实际结束时间（报工后回写）',
  `duration_hours` decimal(6,1) NOT NULL DEFAULT '0.0' COMMENT '计划工时（小时）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '排程状态：0未排程 1已排程 2执行中 3已完成',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT '同一工位上的执行顺序',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_schedule_task` (`dispatch_task_id`),
  KEY `idx_schedule_wo` (`work_order_id`),
  KEY `idx_schedule_ws` (`workstation_id`),
  KEY `idx_schedule_status` (`status`),
  KEY `idx_schedule_time` (`planned_start_time`,`planned_end_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='生产排程记录表';

CREATE TABLE `production_workstation` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `workstation_code` varchar(50) NOT NULL DEFAULT '' COMMENT '工位编码（唯一）',
  `workstation_name` varchar(100) NOT NULL DEFAULT '' COMMENT '工位名称',
  `workstation_type` tinyint(1) NOT NULL DEFAULT '10' COMMENT '工位类型：1拆解 2清洗 3检测 4电镀 5加工 6组装 7测试 8喷漆 9质检 10其他',
  `workshop` varchar(50) NOT NULL DEFAULT '' COMMENT '所属车间',
  `responsible_person_id` int(11) NOT NULL DEFAULT '0' COMMENT '负责人ID',
  `responsible_person_name` varchar(50) NOT NULL DEFAULT '' COMMENT '负责人姓名（冗余）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `current_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '占用状态：0空闲 1占用中 2维护中',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ws_code` (`workstation_code`),
  KEY `idx_ws_type` (`workstation_type`),
  KEY `idx_ws_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COMMENT='工位表';

CREATE TABLE `production_workstation_device` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `workstation_id` int(11) NOT NULL DEFAULT '0' COMMENT '工位ID',
  `device_id` int(11) NOT NULL DEFAULT '0' COMMENT '设备ID（device_assets）',
  `device_code` varchar(50) NOT NULL DEFAULT '' COMMENT '设备编码（冗余）',
  `device_name` varchar(100) NOT NULL DEFAULT '' COMMENT '设备名称（冗余）',
  `device_spec` varchar(100) NOT NULL DEFAULT '' COMMENT '设备规格型号（冗余）',
  `is_primary` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否主设备：1是 0否',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_wsd_ws` (`workstation_id`),
  KEY `idx_wsd_device` (`device_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='工位设备关联表';

CREATE TABLE `production_workstation_staff` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `workstation_id` int(11) NOT NULL DEFAULT '0' COMMENT '工位ID',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '员工ID（users）',
  `user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '员工姓名（冗余）',
  `role_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '角色类型：1主操作员 2副操作员 3辅助人员',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_wss_ws` (`workstation_id`),
  KEY `idx_wss_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='工位员工关联表';

CREATE TABLE `quality_inspection` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `inspection_no` varchar(50) NOT NULL DEFAULT '' COMMENT '检验单编号 QI+YYYYMMDD+4位流水',
  `work_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工单ID',
  `work_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '工单编号（冗余）',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联产品ID',
  `product_name` varchar(100) NOT NULL DEFAULT '' COMMENT '产品名称（冗余）',
  `standard_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联质检标准ID',
  `inspector_id` int(11) NOT NULL DEFAULT '0' COMMENT '质检员ID',
  `inspector_name` varchar(50) NOT NULL DEFAULT '' COMMENT '质检员姓名（冗余）',
  `inspection_date` date DEFAULT NULL COMMENT '检验日期',
  `inspection_time` datetime DEFAULT NULL COMMENT '检验时间（执行时写入）',
  `result` tinyint(1) NOT NULL DEFAULT '3' COMMENT '检验结果：1合格 2不合格 3待判定',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0待检验 1检验中 2已完成',
  `conclusion` varchar(500) DEFAULT NULL COMMENT '检验结论',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_inspection_no` (`inspection_no`),
  KEY `idx_inspection_wo` (`work_order_id`),
  KEY `idx_inspection_status` (`status`),
  KEY `idx_inspection_date` (`inspection_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='检验记录表';

CREATE TABLE `quality_inspection_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `inspection_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联检验记录ID',
  `item_name` varchar(100) NOT NULL DEFAULT '' COMMENT '检验项目名称',
  `item_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '项目类型：1文本 2数值 3布尔',
  `standard_value` varchar(200) DEFAULT NULL COMMENT '标准值',
  `upper_limit` decimal(12,4) DEFAULT NULL COMMENT '上限值（数值类型）',
  `lower_limit` decimal(12,4) DEFAULT NULL COMMENT '下限值（数值类型）',
  `unit` varchar(20) DEFAULT NULL COMMENT '单位',
  `measured_value` varchar(200) DEFAULT NULL COMMENT '实测值',
  `is_qualified` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否合格：1是 0否',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_item_inspection` (`inspection_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='检验明细表';

CREATE TABLE `quality_reject` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `reject_no` varchar(50) NOT NULL DEFAULT '' COMMENT '处理单编号 QR+YYYYMMDD+4位流水',
  `inspection_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联检验记录ID',
  `work_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工单ID',
  `work_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '工单编号（冗余）',
  `product_name` varchar(100) NOT NULL DEFAULT '' COMMENT '产品名称（冗余）',
  `reject_items` json DEFAULT NULL COMMENT '不合格项目列表',
  `reject_type` tinyint(1) NOT NULL DEFAULT '5' COMMENT '不合格类型：1外观缺陷 2尺寸超差 3性能不达标 4材质问题 5其他',
  `severity` tinyint(1) NOT NULL DEFAULT '1' COMMENT '严重程度：1轻微 2一般 3严重',
  `handle_method` tinyint(1) NOT NULL DEFAULT '0' COMMENT '处理方式：1返修 2报废 3退货 4让步接收',
  `handle_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '处理状态：0待处理 1处理中 2已处理 3已关闭',
  `handler_id` int(11) NOT NULL DEFAULT '0' COMMENT '处理人ID',
  `handler_name` varchar(50) NOT NULL DEFAULT '' COMMENT '处理人姓名',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `handle_result` varchar(500) DEFAULT NULL COMMENT '处理结果',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_reject_no` (`reject_no`),
  KEY `idx_reject_wo` (`work_order_id`),
  KEY `idx_reject_status` (`handle_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='不合格品处理表';

CREATE TABLE `quality_reject_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `reject_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联处理单ID',
  `action` varchar(30) NOT NULL DEFAULT '' COMMENT '操作类型：create/handle/close',
  `action_label` varchar(30) NOT NULL DEFAULT '' COMMENT '操作类型标签',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `before_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作前状态',
  `after_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作后状态',
  `remark` varchar(500) DEFAULT NULL COMMENT '操作备注',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_log_reject` (`reject_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='不合格品处理日志表';

CREATE TABLE `quality_standard` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `standard_code` varchar(50) NOT NULL DEFAULT '' COMMENT '标准编码 QS-001',
  `standard_name` varchar(100) NOT NULL DEFAULT '' COMMENT '标准名称',
  `product_type` varchar(50) NOT NULL DEFAULT '' COMMENT '适用产品类型',
  `process_type` varchar(50) NOT NULL DEFAULT '' COMMENT '适用工序类型',
  `inspection_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '检验类型：1外观 2尺寸 3性能 4材质',
  `items` json DEFAULT NULL COMMENT '检验项目列表（JSON数组）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_standard_code` (`standard_code`),
  KEY `idx_standard_type` (`inspection_type`),
  KEY `idx_standard_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='质检标准表';

CREATE TABLE `recruit_interview` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `resume_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联简历ID',
  `resume_no` varchar(50) NOT NULL DEFAULT '' COMMENT '简历编号（冗余）',
  `candidate_name` varchar(50) NOT NULL DEFAULT '' COMMENT '应聘者姓名（冗余）',
  `position_id` int(11) NOT NULL DEFAULT '0' COMMENT '应聘职位ID（冗余）',
  `position_name` varchar(100) NOT NULL DEFAULT '' COMMENT '职位名称（冗余）',
  `interview_round` tinyint(1) NOT NULL DEFAULT '1' COMMENT '面试轮次：1初试 2复试 3终试',
  `interview_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '面试类型：1现场 2电话 3视频',
  `interview_time` datetime DEFAULT NULL COMMENT '面试时间',
  `interview_duration` int(11) NOT NULL DEFAULT '60' COMMENT '面试时长（分钟）',
  `interviewer_id` int(11) NOT NULL DEFAULT '0' COMMENT '面试官ID',
  `interviewer_name` varchar(50) NOT NULL DEFAULT '' COMMENT '面试官姓名（冗余）',
  `interview_location` varchar(200) DEFAULT NULL COMMENT '面试地点',
  `interview_remark` varchar(500) DEFAULT NULL COMMENT '面试备注',
  `result` tinyint(1) NOT NULL DEFAULT '0' COMMENT '面试结果：0待评价 1通过 2不通过 3待定',
  `evaluation` text COMMENT '面试评价',
  `score` decimal(3,1) NOT NULL DEFAULT '0.0' COMMENT '评分（1-5分）',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '记录状态：0已安排 1已完成 2已取消',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_resume` (`resume_id`),
  KEY `idx_interviewer` (`interviewer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='面试记录表';

CREATE TABLE `recruit_offer` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `offer_no` varchar(50) NOT NULL DEFAULT '' COMMENT '录用编号 OF+YYYYMMDD+4位流水',
  `resume_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联简历ID',
  `resume_no` varchar(50) NOT NULL DEFAULT '' COMMENT '简历编号（冗余）',
  `candidate_name` varchar(50) NOT NULL DEFAULT '' COMMENT '应聘者姓名（冗余）',
  `position_id` int(11) NOT NULL DEFAULT '0' COMMENT '录用职位ID',
  `position_name` varchar(100) NOT NULL DEFAULT '' COMMENT '录用职位名称（冗余）',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '录用部门ID',
  `department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '录用部门名称（冗余）',
  `offer_salary` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '录用薪资（元/月）',
  `offer_date` date DEFAULT NULL COMMENT '录用日期',
  `expected_join_date` date DEFAULT NULL COMMENT '预计入职日期',
  `probation_period` int(11) NOT NULL DEFAULT '3' COMMENT '试用期（月）',
  `probation_salary` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '试用期薪资',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '录用状态：0草稿 1待审批 2已通过 3已驳回 4已接受 5已拒绝',
  `approval_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联统一审批实例ID',
  `approval_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approval_remark` varchar(500) DEFAULT NULL COMMENT '审批备注',
  `notice_time` datetime DEFAULT NULL COMMENT '录用通知发送时间',
  `accept_time` datetime DEFAULT NULL COMMENT '接受时间（生成档案后）',
  `reject_time` datetime DEFAULT NULL COMMENT '拒绝时间',
  `reject_reason` varchar(500) DEFAULT NULL COMMENT '拒绝原因',
  `employee_profile_id` int(11) NOT NULL DEFAULT '0' COMMENT '生成员工档案ID',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_offer_no` (`offer_no`),
  KEY `idx_resume` (`resume_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='录用审批表';

CREATE TABLE `recruit_position` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `position_no` varchar(50) NOT NULL DEFAULT '' COMMENT '职位编号 POS+YYYYMMDD+4位流水',
  `requirement_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联招聘需求ID（可选）',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '所属部门ID',
  `department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '部门名称（冗余）',
  `position_name` varchar(100) NOT NULL DEFAULT '' COMMENT '职位名称',
  `position_category` tinyint(1) NOT NULL DEFAULT '5' COMMENT '岗位类别：1工人 2技术员 3业务员 4管理人员 5其他',
  `recruit_count` int(11) NOT NULL DEFAULT '1' COMMENT '招聘人数',
  `hired_count` int(11) NOT NULL DEFAULT '0' COMMENT '已录用人数',
  `work_location` varchar(100) DEFAULT NULL COMMENT '工作地点',
  `job_description` text COMMENT '职位描述',
  `requirements` text COMMENT '任职要求',
  `salary_range_min` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '薪资范围-最低',
  `salary_range_max` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '薪资范围-最高',
  `publish_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '发布状态：0未发布 1已发布 2已下架 3已关闭',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `expire_time` datetime DEFAULT NULL COMMENT '过期时间',
  `channel` varchar(50) DEFAULT NULL COMMENT '发布渠道',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_position_no` (`position_no`),
  KEY `idx_publish` (`publish_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='招聘职位表';

CREATE TABLE `recruit_requirement` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `requirement_no` varchar(50) NOT NULL DEFAULT '' COMMENT '需求编号 RQ+YYYYMMDD+4位流水',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '需求部门ID',
  `department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '需求部门名称（冗余）',
  `position_name` varchar(100) NOT NULL DEFAULT '' COMMENT '招聘岗位名称',
  `position_category` tinyint(1) NOT NULL DEFAULT '5' COMMENT '岗位类别：1工人 2技术员 3业务员 4管理人员 5其他',
  `position_count` int(11) NOT NULL DEFAULT '1' COMMENT '招聘人数',
  `urgency` tinyint(1) NOT NULL DEFAULT '1' COMMENT '紧急程度：1普通 2紧急 3特急',
  `reason` varchar(500) DEFAULT NULL COMMENT '招聘原因',
  `requirements` text COMMENT '岗位要求（技能、经验、学历等）',
  `salary_range_min` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '薪资范围-最低',
  `salary_range_max` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '薪资范围-最高',
  `expected_join_date` date DEFAULT NULL COMMENT '期望到岗日期',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '需求状态：0草稿 1待审批 2已通过 3已驳回 4已关闭',
  `approval_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联统一审批实例ID',
  `approval_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approval_remark` varchar(500) DEFAULT NULL COMMENT '审批备注',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_requirement_no` (`requirement_no`),
  KEY `idx_status` (`status`),
  KEY `idx_dept` (`department_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='招聘需求表';

CREATE TABLE `recruit_resume` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `resume_no` varchar(50) NOT NULL DEFAULT '' COMMENT '简历编号 RS+YYYYMMDD+4位流水',
  `position_id` int(11) NOT NULL DEFAULT '0' COMMENT '应聘职位ID',
  `position_name` varchar(100) NOT NULL DEFAULT '' COMMENT '职位名称（冗余）',
  `candidate_name` varchar(50) NOT NULL DEFAULT '' COMMENT '应聘者姓名',
  `candidate_phone` varchar(20) NOT NULL DEFAULT '' COMMENT '联系电话',
  `candidate_email` varchar(100) DEFAULT NULL COMMENT '电子邮箱',
  `candidate_gender` tinyint(1) NOT NULL DEFAULT '0' COMMENT '性别：1男 2女',
  `candidate_age` int(11) NOT NULL DEFAULT '0' COMMENT '年龄',
  `education` tinyint(1) NOT NULL DEFAULT '0' COMMENT '学历：1初中及以下 2高中/中专 3大专 4本科 5硕士及以上',
  `school` varchar(100) DEFAULT NULL COMMENT '毕业院校',
  `major` varchar(100) DEFAULT NULL COMMENT '专业',
  `graduation_year` int(11) NOT NULL DEFAULT '0' COMMENT '毕业年份',
  `work_experience` int(11) NOT NULL DEFAULT '0' COMMENT '工作年限（年）',
  `expected_salary` varchar(50) DEFAULT NULL COMMENT '期望薪资（H5投递选填）',
  `self_introduction` varchar(500) DEFAULT NULL COMMENT '自荐语/备注（H5投递选填）',
  `last_company` varchar(100) DEFAULT NULL COMMENT '上一份工作单位',
  `last_position` varchar(100) DEFAULT NULL COMMENT '上一份工作岗位',
  `skills` text COMMENT '技能特长',
  `resume_file` varchar(500) DEFAULT NULL COMMENT '简历附件文件路径',
  `source` tinyint(1) NOT NULL DEFAULT '1' COMMENT '简历来源：1招聘网站 2内部推荐 3校园招聘 4人才市场 5自主投递 6其他',
  `recommender` varchar(50) DEFAULT NULL COMMENT '推荐人姓名（内部推荐时填写）',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '简历状态：0待筛选 1待面试 2待复试 3已录用 4淘汰 5已放弃',
  `screening_remark` varchar(500) DEFAULT NULL COMMENT '筛选备注',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_resume_no` (`resume_no`),
  KEY `idx_status` (`status`),
  KEY `idx_position` (`position_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='简历表';

CREATE TABLE `return_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `return_no` varchar(50) NOT NULL DEFAULT '' COMMENT '退还单号 RT+日期+流水',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '申请人ID',
  `user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '申请人姓名',
  `personal_asset_id` int(11) NOT NULL DEFAULT '0' COMMENT '个人资产ID',
  `asset_name` varchar(100) NOT NULL DEFAULT '' COMMENT '资产名称(冗余)',
  `asset_code` varchar(50) NOT NULL DEFAULT '' COMMENT '资产编码(冗余)',
  `specification` varchar(100) NOT NULL DEFAULT '' COMMENT '规格型号(冗余)',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位(冗余)',
  `asset_type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '资产类型 1配件 2固定资产 3工具',
  `asset_archive_id` int(11) NOT NULL DEFAULT '0' COMMENT '资产档案ID',
  `return_quantity` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '退还数量',
  `reason` varchar(255) NOT NULL DEFAULT '' COMMENT '退还原因',
  `photo` varchar(255) NOT NULL DEFAULT '' COMMENT '资产照片URL',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0=待审批 1=已退还 2=已驳回',
  `approval_instance_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联审批实例ID',
  `return_time` datetime DEFAULT NULL COMMENT '退还完成时间',
  `reject_reason` varchar(255) NOT NULL DEFAULT '' COMMENT '驳回原因',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_return_no` (`return_no`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_status` (`status`),
  KEY `idx_approval_instance_id` (`approval_instance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='资产退还记录表';

CREATE TABLE `role_permissions` (
  `role_id` int(11) unsigned NOT NULL,
  `permission_id` int(11) unsigned NOT NULL,
  PRIMARY KEY (`role_id`,`permission_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色权限关联表';

CREATE TABLE `roles` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '角色名称',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT '角色编码',
  `description` varchar(255) DEFAULT NULL COMMENT '角色描述',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1启用 0禁用',
  `is_system` tinyint(4) NOT NULL DEFAULT '0' COMMENT '1系统内置',
  `data_scope` tinyint(4) NOT NULL DEFAULT '4' COMMENT '1全部 2本部门及下级 3本部门 4仅本人 5自定义',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`,`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='角色表';

CREATE TABLE `safety_accident` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `accident_code` varchar(50) NOT NULL COMMENT '事故编号 A-YYYYMMDD-XXXX',
  `accident_name` varchar(200) NOT NULL COMMENT '事故名称',
  `accident_type` varchar(30) NOT NULL COMMENT '事故类型 personal_injury/equipment_damage/fire/explosion/leakage/other',
  `accident_level` varchar(20) NOT NULL COMMENT '事故等级 general/major/serious/critical',
  `happen_time` datetime NOT NULL COMMENT '发生时间',
  `happen_location` varchar(200) NOT NULL COMMENT '发生地点',
  `happen_department` int(11) DEFAULT NULL COMMENT '发生部门ID',
  `happen_department_name` varchar(100) DEFAULT NULL COMMENT '发生部门名称(冗余)',
  `accident_process` text NOT NULL COMMENT '事故经过',
  `accident_cause` text NOT NULL COMMENT '事故原因',
  `death_count` int(11) NOT NULL DEFAULT '0' COMMENT '死亡人数',
  `serious_injury_count` int(11) NOT NULL DEFAULT '0' COMMENT '重伤人数',
  `minor_injury_count` int(11) NOT NULL DEFAULT '0' COMMENT '轻伤人数',
  `economic_loss` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '直接经济损失(万元)',
  `responsible_person` varchar(50) DEFAULT NULL COMMENT '责任人姓名',
  `responsible_department` varchar(100) DEFAULT NULL COMMENT '责任人部门',
  `responsible_position` varchar(100) DEFAULT NULL COMMENT '责任人岗位',
  `handle_opinion` varchar(500) DEFAULT NULL COMMENT '处理意见',
  `registrant_id` int(11) NOT NULL COMMENT '登记人ID',
  `registrant_name` varchar(50) NOT NULL COMMENT '登记人姓名',
  `attachments` json DEFAULT NULL COMMENT '附件列表',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态 pending/investigating/closed/archived',
  `remark` text COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_accident_code` (`accident_code`),
  KEY `idx_accident_type` (`accident_type`),
  KEY `idx_accident_level` (`accident_level`),
  KEY `idx_happen_time` (`happen_time`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='事故登记';

CREATE TABLE `safety_accident_investigation` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `accident_id` int(11) NOT NULL COMMENT '事故ID',
  `investigation_code` varchar(50) NOT NULL COMMENT '调查编号 I-YYYYMMDD-XXXX',
  `investigator_id` int(11) DEFAULT NULL COMMENT '调查人ID',
  `investigator_name` varchar(50) DEFAULT NULL COMMENT '调查人姓名',
  `investigation_deadline` date DEFAULT NULL COMMENT '调查期限',
  `assigned_at` datetime DEFAULT NULL COMMENT '分配时间',
  `started_at` datetime DEFAULT NULL COMMENT '开始调查时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成调查时间',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '调查状态 pending/investigating/closed',
  `direct_cause` text COMMENT '直接原因',
  `indirect_cause` text COMMENT '间接原因',
  `root_cause` text COMMENT '根本原因',
  `responsible_person` varchar(50) DEFAULT NULL COMMENT '责任人',
  `responsible_department` varchar(100) DEFAULT NULL COMMENT '责任部门',
  `responsibility_opinion` text COMMENT '责任认定',
  `handle_suggestion` text COMMENT '处理建议',
  `corrective_measures` json DEFAULT NULL COMMENT '整改措施列表',
  `conclusion` text COMMENT '调查结论',
  `attachments` json DEFAULT NULL COMMENT '附件列表',
  `submit_status` varchar(20) NOT NULL DEFAULT 'draft' COMMENT '审批状态 draft/pending/approved/rejected',
  `approver_id` int(11) DEFAULT NULL COMMENT '审批人ID',
  `approver_name` varchar(50) DEFAULT NULL COMMENT '审批人姓名',
  `approved_at` datetime DEFAULT NULL COMMENT '审批时间',
  `reject_reason` varchar(500) DEFAULT NULL COMMENT '驳回原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_investigation_code` (`investigation_code`),
  KEY `idx_accident_id` (`accident_id`),
  KEY `idx_investigator_id` (`investigator_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='事故调查';

CREATE TABLE `safety_accident_timeline` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `accident_id` int(11) NOT NULL COMMENT '事故ID',
  `action` varchar(30) NOT NULL COMMENT '操作类型 assigned/started/submitted/approved/rejected/completed',
  `operator_id` int(11) NOT NULL COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL COMMENT '操作人姓名',
  `description` varchar(255) NOT NULL COMMENT '操作描述',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_accident_id` (`accident_id`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='事故调查时间线';

CREATE TABLE `safety_certificate_template` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `template_code` varchar(50) NOT NULL COMMENT '模板编号 TPL-YYYYMMDD-XXXX',
  `template_name` varchar(100) NOT NULL COMMENT '模板名称',
  `training_type_id` int(11) DEFAULT NULL COMMENT '适用培训类型ID',
  `certificate_name` varchar(100) NOT NULL COMMENT '证书名称',
  `validity_years` int(11) NOT NULL DEFAULT '0' COMMENT '有效年限，0=长期有效',
  `template_data` json DEFAULT NULL COMMENT '模板数据（样式配置）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态 1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_code` (`template_code`),
  KEY `idx_training_type_id` (`training_type_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='证书模板';

CREATE TABLE `safety_exam_answer` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `exam_id` int(11) NOT NULL COMMENT '考试记录ID',
  `user_id` int(11) NOT NULL COMMENT '员工ID',
  `user_name` varchar(50) NOT NULL COMMENT '员工姓名（冗余）',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0未开始 1进行中 2已交卷',
  `start_time` datetime DEFAULT NULL COMMENT '考生开始考试时间',
  `answers` json DEFAULT NULL COMMENT '答案列表 [{question_id,question_type,selected,is_correct}]',
  `score` int(11) NOT NULL DEFAULT '0' COMMENT '得分',
  `is_pass` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否合格',
  `attempt` tinyint(1) NOT NULL DEFAULT '1' COMMENT '考试次数(1=首次,2=第1次补考)',
  `submit_time` datetime DEFAULT NULL COMMENT '交卷时间',
  `exam_duration` int(11) NOT NULL DEFAULT '0' COMMENT '答题耗时（秒）',
  `extend_minutes` int(11) NOT NULL DEFAULT '0' COMMENT '延长考试分钟数',
  `id_card_verified` tinyint(1) NOT NULL DEFAULT '0' COMMENT '身份证后6位校验是否通过',
  `face_verified` tinyint(1) NOT NULL DEFAULT '0' COMMENT '人脸验证是否通过',
  `face_score` decimal(5,1) DEFAULT NULL COMMENT '人脸相似度分数',
  `identity_verified_at` datetime DEFAULT NULL COMMENT '身份证校验时间',
  `face_verified_at` datetime DEFAULT NULL COMMENT '人脸验证时间',
  `is_marked` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否已批改（自动）',
  `review_time` datetime DEFAULT NULL COMMENT '查看错题时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_exam_id` (`exam_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_is_pass` (`is_pass`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COMMENT='考生答卷';

CREATE TABLE `safety_exam_paper` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `paper_code` varchar(50) NOT NULL COMMENT '试卷编号 P-YYYYMMDD-XXXX',
  `paper_name` varchar(100) NOT NULL COMMENT '试卷名称',
  `training_type_id` int(11) DEFAULT NULL COMMENT '关联培训类型ID',
  `total_questions` int(11) NOT NULL DEFAULT '0' COMMENT '题目总数',
  `total_score` int(11) NOT NULL DEFAULT '100' COMMENT '总分',
  `pass_score` int(11) NOT NULL DEFAULT '60' COMMENT '及格分数',
  `duration_minutes` int(11) NOT NULL DEFAULT '60' COMMENT '考试时长（分钟）',
  `question_ids` json DEFAULT NULL COMMENT '题目ID数组',
  `question_config` json DEFAULT NULL COMMENT '组卷配置(自动组卷:题型数量/难度比例)',
  `status` varchar(20) NOT NULL DEFAULT 'draft' COMMENT '状态 draft草稿 published已发布',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_paper_code` (`paper_code`),
  KEY `idx_training_type_id` (`training_type_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='培训考试试卷';

CREATE TABLE `safety_exam_question` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `question_code` varchar(50) NOT NULL COMMENT '题目编号 Q-YYYYMMDD-XXXX',
  `question_type` varchar(20) NOT NULL COMMENT '题型 single/multiple/judge',
  `question_text` text NOT NULL COMMENT '题目内容',
  `options` json NOT NULL COMMENT '选项列表 [{"label":"A","text":"..."}]',
  `answer` varchar(50) NOT NULL COMMENT '正确答案（单选A/多选A,B/判断"正确"或"错误"）',
  `analysis` text COMMENT '题目解析',
  `difficulty` varchar(20) NOT NULL DEFAULT 'normal' COMMENT '难度 easy/normal/hard',
  `category_id` int(11) DEFAULT NULL COMMENT '分类ID（培训类型）',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态 1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_question_code` (`question_code`),
  KEY `idx_question_type` (`question_type`),
  KEY `idx_difficulty` (`difficulty`),
  KEY `idx_status` (`status`),
  KEY `idx_category_id` (`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COMMENT='培训考试题库';

CREATE TABLE `safety_exam_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `exam_code` varchar(50) NOT NULL COMMENT '考试编号 E-YYYYMMDD-XXXX',
  `exam_name` varchar(100) DEFAULT NULL COMMENT '考试名称',
  `paper_id` int(11) NOT NULL COMMENT '试卷ID',
  `paper_name` varchar(100) NOT NULL COMMENT '试卷名称（冗余）',
  `pass_score` int(11) NOT NULL DEFAULT '60' COMMENT '及格分数(冗余自试卷)',
  `retake_limit` tinyint(1) NOT NULL DEFAULT '0' COMMENT '允许补考次数(0=不允许)',
  `training_record_id` int(11) DEFAULT NULL COMMENT '培训记录ID',
  `exam_type` varchar(20) NOT NULL DEFAULT 'formal' COMMENT '考试类型 formal正式 practice练习',
  `start_time` datetime NOT NULL COMMENT '考试开始时间',
  `end_time` datetime NOT NULL COMMENT '考试结束时间',
  `duration_minutes` int(11) NOT NULL DEFAULT '60' COMMENT '考试时长（分钟）',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态 pending/in_progress/ended',
  `total_participants` int(11) NOT NULL DEFAULT '0' COMMENT '应考人数',
  `actual_participants` int(11) NOT NULL DEFAULT '0' COMMENT '实考人数',
  `pass_count` int(11) NOT NULL DEFAULT '0' COMMENT '通过人数',
  `exam_notice` text COMMENT '考试须知',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_exam_code` (`exam_code`),
  KEY `idx_paper_id` (`paper_id`),
  KEY `idx_training_record_id` (`training_record_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COMMENT='培训考试记录';

CREATE TABLE `safety_hazards` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `hazard_code` varchar(50) NOT NULL COMMENT '隐患编号（唯一）HAZ-YYYYMMDD-XXXX',
  `hazard_name` varchar(200) NOT NULL COMMENT '隐患名称',
  `hazard_type` varchar(30) NOT NULL DEFAULT 'equipment' COMMENT '隐患类型（字典safety_hazard_type）',
  `hazard_level` varchar(20) NOT NULL DEFAULT 'general' COMMENT '隐患等级（字典safety_hazard_level）',
  `source_type` varchar(30) NOT NULL DEFAULT 'manual' COMMENT '来源类型（字典safety_hazard_source）',
  `source_id` int(11) unsigned DEFAULT NULL COMMENT '来源记录ID',
  `location` varchar(200) NOT NULL DEFAULT '' COMMENT '发现位置',
  `discovered_by` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '发现人ID',
  `discovered_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '发现人姓名',
  `discovered_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发现时间',
  `hazard_desc` text NOT NULL COMMENT '隐患描述',
  `hazard_images` json DEFAULT NULL COMMENT '隐患图片',
  `assigned_to` int(11) unsigned DEFAULT NULL COMMENT '指派人ID',
  `assigned_to_name` varchar(50) NOT NULL DEFAULT '' COMMENT '指派人姓名',
  `handler_id` int(11) unsigned DEFAULT NULL COMMENT '整改人ID',
  `handler_name` varchar(50) NOT NULL DEFAULT '' COMMENT '整改人姓名',
  `handler_deadline` date DEFAULT NULL COMMENT '整改期限',
  `handle_measure` text COMMENT '整改措施',
  `handle_attachments` json DEFAULT NULL COMMENT '整改附件',
  `handle_completed_at` datetime DEFAULT NULL COMMENT '整改完成时间',
  `verified_by` int(11) unsigned DEFAULT NULL COMMENT '验证人ID',
  `verified_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '验证人姓名',
  `verified_at` datetime DEFAULT NULL COMMENT '验证时间',
  `verify_opinion` varchar(500) NOT NULL DEFAULT '' COMMENT '验证意见',
  `verify_result` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '验证结果（字典verify_result）',
  `reject_reason` varchar(500) NOT NULL DEFAULT '' COMMENT '驳回原因',
  `reject_count` int(11) NOT NULL DEFAULT '0' COMMENT '驳回次数',
  `reject_history` json DEFAULT NULL COMMENT '驳回历史',
  `verify_attachments` json DEFAULT NULL COMMENT '验证附件',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态（字典safety_hazard_status）',
  `remark` text COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hazard_code` (`hazard_code`),
  KEY `idx_status` (`status`),
  KEY `idx_hazard_level` (`hazard_level`),
  KEY `idx_discovered_at` (`discovered_at`),
  KEY `idx_handler_id` (`handler_id`),
  KEY `idx_verified_by` (`verified_by`),
  KEY `idx_source_type` (`source_type`),
  KEY `idx_discovered_by` (`discovered_by`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COMMENT='隐患管理表';

CREATE TABLE `safety_inspection_issue` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `task_id` int(11) NOT NULL COMMENT '检查任务ID',
  `plan_id` int(11) DEFAULT NULL COMMENT '检查计划ID',
  `item_name` varchar(100) NOT NULL COMMENT '检查项目名称',
  `issue_description` text NOT NULL COMMENT '问题描述',
  `suggest` text COMMENT '整改建议',
  `severity` varchar(20) NOT NULL DEFAULT 'minor' COMMENT '严重程度：minor一般 major严重 critical紧急',
  `hazard_id` int(11) DEFAULT NULL COMMENT '关联隐患ID（safety_hazards.id）',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态：pending待处理 resolved已处理',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_task_id` (`task_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='安全检查问题记录';

CREATE TABLE `safety_inspection_plan` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `plan_code` varchar(50) NOT NULL COMMENT '计划编号 SIP-YYYYMMDD-XXXX',
  `plan_name` varchar(100) NOT NULL COMMENT '计划名称',
  `inspection_type_id` int(11) NOT NULL COMMENT '检查类型ID',
  `area` varchar(100) DEFAULT NULL COMMENT '检查区域',
  `template_id` int(11) DEFAULT NULL COMMENT '模板ID',
  `cycle_type` varchar(20) NOT NULL COMMENT '周期类型：day/week/month/quarter/year',
  `cycle_value` int(11) NOT NULL COMMENT '周期值',
  `start_date` date DEFAULT NULL COMMENT '计划开始日期',
  `end_date` date DEFAULT NULL COMMENT '计划结束日期',
  `last_execute_date` date DEFAULT NULL COMMENT '上次执行日期',
  `next_execute_date` date DEFAULT NULL COMMENT '下次执行日期',
  `leader_id` int(11) DEFAULT NULL COMMENT '负责人ID',
  `leader_name` varchar(50) DEFAULT NULL COMMENT '负责人姓名',
  `executor_ids` varchar(500) DEFAULT NULL COMMENT '执行人ID列表，逗号分隔',
  `status` varchar(20) NOT NULL DEFAULT 'active' COMMENT '状态：active启用 inactive停用 expired过期',
  `remark` text COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plan_code` (`plan_code`),
  KEY `idx_inspection_type_id` (`inspection_type_id`),
  KEY `idx_status` (`status`),
  KEY `idx_next_execute_date` (`next_execute_date`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COMMENT='安全检查计划';

CREATE TABLE `safety_inspection_task` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `task_code` varchar(50) NOT NULL COMMENT '任务编号 SIT-YYYYMMDD-XXXX',
  `plan_id` int(11) NOT NULL COMMENT '检查计划ID',
  `plan_name` varchar(100) DEFAULT NULL COMMENT '计划名称（冗余）',
  `inspection_type_id` int(11) NOT NULL COMMENT '检查类型ID',
  `inspection_type_name` varchar(50) DEFAULT NULL COMMENT '检查类型名称（冗余）',
  `area` varchar(100) DEFAULT NULL COMMENT '检查区域',
  `template_id` int(11) DEFAULT NULL COMMENT '检查标准模板ID',
  `leader_id` int(11) DEFAULT NULL COMMENT '负责人ID（users.id）',
  `leader_name` varchar(50) DEFAULT NULL COMMENT '负责人姓名',
  `executor_id` int(11) DEFAULT NULL COMMENT '执行人ID（users.id）',
  `executor_name` varchar(50) DEFAULT NULL COMMENT '执行人姓名',
  `plan_execute_date` date NOT NULL COMMENT '计划执行日期',
  `actual_execute_date` datetime DEFAULT NULL COMMENT '实际执行日期',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态：pending待执行 in_progress执行中 completed已完成 overdue已逾期 cancelled已取消',
  `execute_start_time` datetime DEFAULT NULL COMMENT '执行开始时间',
  `execute_end_time` datetime DEFAULT NULL COMMENT '执行结束时间',
  `execute_duration` int(11) DEFAULT NULL COMMENT '执行耗时（分钟）',
  `result` json DEFAULT NULL COMMENT '检查项目执行结果 [{item_name,result,remark}]',
  `summary` text COMMENT '检查总结',
  `issue_count` int(11) NOT NULL DEFAULT '0' COMMENT '问题数量',
  `is_notified` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已发送到期提醒',
  `remind_count` int(11) NOT NULL DEFAULT '0' COMMENT '提醒次数',
  `cancel_reason` varchar(255) DEFAULT NULL COMMENT '取消原因',
  `remark` text COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_code` (`task_code`),
  KEY `idx_plan_id` (`plan_id`),
  KEY `idx_executor_id` (`executor_id`),
  KEY `idx_status` (`status`),
  KEY `idx_plan_execute_date` (`plan_execute_date`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='安全检查任务';

CREATE TABLE `safety_inspection_template` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `template_code` varchar(50) NOT NULL COMMENT '模板编号 TPL-YYYYMMDD-XXXX',
  `template_name` varchar(100) NOT NULL COMMENT '模板名称',
  `inspection_type_id` int(11) DEFAULT NULL COMMENT '适用检查类型ID',
  `items` json NOT NULL COMMENT '检查项目列表[{item_name,check_standard,check_method,is_required,deduct_score,sort}]',
  `status` varchar(20) NOT NULL DEFAULT 'active' COMMENT '状态：active启用 inactive停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_code` (`template_code`),
  KEY `idx_inspection_type_id` (`inspection_type_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COMMENT='检查标准模板';

CREATE TABLE `safety_inspection_type` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `type_code` varchar(30) NOT NULL COMMENT '类型编码，如 DAILY/SPECIAL/HOLIDAY',
  `type_name` varchar(50) NOT NULL COMMENT '类型名称，如日常检查/专项检查/节假日检查',
  `default_cycle_type` varchar(20) DEFAULT NULL COMMENT '默认周期类型：day/week/month/quarter/year',
  `default_cycle_value` int(11) DEFAULT NULL COMMENT '默认周期值',
  `default_leader_role` varchar(50) DEFAULT NULL COMMENT '默认负责人角色',
  `description` varchar(255) DEFAULT NULL COMMENT '描述说明',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_type_code` (`type_code`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='安全检查类型';

CREATE TABLE `safety_risk` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `risk_code` varchar(50) NOT NULL COMMENT '风险编号 R-YYYYMMDD-XXXX',
  `risk_name` varchar(200) NOT NULL COMMENT '风险名称',
  `risk_type` varchar(30) NOT NULL COMMENT '风险类型 physical/chemical/biological/ergonomic/management/other',
  `risk_level` varchar(20) NOT NULL DEFAULT 'low' COMMENT '风险等级 low/general/major/critical',
  `area` varchar(200) NOT NULL COMMENT '所属区域',
  `department_id` int(11) DEFAULT NULL COMMENT '所属部门ID',
  `department_name` varchar(100) DEFAULT NULL COMMENT '所属部门名称(冗余)',
  `responsible_person_id` int(11) DEFAULT NULL COMMENT '责任人ID',
  `responsible_person_name` varchar(50) DEFAULT NULL COMMENT '责任人姓名(冗余)',
  `hazard_source` text NOT NULL COMMENT '危险源描述',
  `consequence` text NOT NULL COMMENT '可能导致的后果',
  `impact_scope` varchar(500) DEFAULT NULL COMMENT '影响范围',
  `current_controls` text COMMENT '现有控制措施',
  `control_effectiveness` varchar(20) DEFAULT NULL COMMENT '控制措施有效性 effective/partial/ineffective',
  `l_score` decimal(3,1) DEFAULT NULL COMMENT '可能性评分',
  `e_score` decimal(3,1) DEFAULT NULL COMMENT '暴露频率评分',
  `c_score` decimal(5,1) DEFAULT NULL COMMENT '后果严重性评分',
  `d_score` decimal(5,1) DEFAULT NULL COMMENT '风险值(LEC)',
  `assessor_id` int(11) DEFAULT NULL COMMENT '评估人ID',
  `assessor_name` varchar(50) DEFAULT NULL COMMENT '评估人姓名',
  `assess_date` date DEFAULT NULL COMMENT '评估日期',
  `review_date` date DEFAULT NULL COMMENT '下次复评日期',
  `identifier_id` int(11) NOT NULL COMMENT '辨识人ID',
  `identifier_name` varchar(50) NOT NULL COMMENT '辨识人姓名',
  `identify_date` date NOT NULL COMMENT '辨识日期',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态 pending/assessed/controlled',
  `attachments` json DEFAULT NULL COMMENT '附件列表',
  `remark` text COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_risk_code` (`risk_code`),
  KEY `idx_risk_type` (`risk_type`),
  KEY `idx_risk_level` (`risk_level`),
  KEY `idx_status` (`status`),
  KEY `idx_identify_date` (`identify_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='风险辨识';

CREATE TABLE `safety_risk_assessment_history` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `risk_id` int(11) NOT NULL COMMENT '风险ID',
  `assessment_code` varchar(50) NOT NULL COMMENT '评估编号 RA-YYYYMMDD-XXXX',
  `l_score` decimal(3,1) NOT NULL COMMENT '可能性评分',
  `e_score` decimal(3,1) NOT NULL COMMENT '暴露频率评分',
  `c_score` decimal(5,1) NOT NULL COMMENT '后果严重性评分',
  `d_score` decimal(5,1) NOT NULL COMMENT '风险值',
  `risk_level` varchar(20) NOT NULL COMMENT '风险等级 low/general/major/critical',
  `assessor_id` int(11) NOT NULL COMMENT '评估人ID',
  `assessor_name` varchar(50) NOT NULL COMMENT '评估人姓名',
  `assess_date` date NOT NULL COMMENT '评估日期',
  `review_date` date DEFAULT NULL COMMENT '下次复评日期',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_assessment_code` (`assessment_code`),
  KEY `idx_risk_id` (`risk_id`),
  KEY `idx_assess_date` (`assess_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='风险评估历史';

CREATE TABLE `safety_risk_control` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `measure_code` varchar(50) NOT NULL COMMENT '措施编号 MC-YYYYMMDD-XXXX',
  `risk_id` int(11) NOT NULL COMMENT '风险ID',
  `measure_type` varchar(30) NOT NULL COMMENT '措施类型 engineering/management_control/personal_protection/emergency',
  `measure_content` text NOT NULL COMMENT '措施内容',
  `responsible_person_id` int(11) NOT NULL COMMENT '责任人ID',
  `responsible_person_name` varchar(50) NOT NULL COMMENT '责任人姓名(冗余)',
  `deadline` date NOT NULL COMMENT '完成期限',
  `implement_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '实施状态 pending/in_progress/completed/invalid',
  `verify_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '验证状态 pending/effective/ineffective',
  `implement_start_time` datetime DEFAULT NULL COMMENT '实施开始时间',
  `implement_complete_time` datetime DEFAULT NULL COMMENT '实施完成时间',
  `invalid_reason` varchar(500) DEFAULT NULL COMMENT '失效原因',
  `progress_remark` varchar(500) DEFAULT NULL COMMENT '进度备注',
  `verify_by` int(11) DEFAULT NULL COMMENT '验证人ID',
  `verify_by_name` varchar(50) DEFAULT NULL COMMENT '验证人姓名',
  `verify_time` datetime DEFAULT NULL COMMENT '验证时间',
  `verify_opinion` varchar(500) DEFAULT NULL COMMENT '验证意见',
  `remark` text COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_measure_code` (`measure_code`),
  KEY `idx_risk_id` (`risk_id`),
  KEY `idx_measure_type` (`measure_type`),
  KEY `idx_implement_status` (`implement_status`),
  KEY `idx_verify_status` (`verify_status`),
  KEY `idx_responsible_person_id` (`responsible_person_id`),
  KEY `idx_deadline` (`deadline`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='风险管控措施';

CREATE TABLE `safety_training_attendee` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `record_id` int(11) NOT NULL COMMENT '培训记录ID',
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `user_name` varchar(50) NOT NULL COMMENT '用户姓名（冗余）',
  `department` varchar(100) DEFAULT NULL COMMENT '所属部门（冗余）',
  `position` varchar(100) DEFAULT NULL COMMENT '岗位（冗余）',
  `is_trained` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已完成培训：1完成 0未完成（线上培训）',
  `checkin_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '签到状态 pending未签到/signed已签到',
  `checkin_time` datetime DEFAULT NULL COMMENT '签到时间',
  `checkin_lat` decimal(10,7) DEFAULT NULL COMMENT '实际签到纬度',
  `checkin_lng` decimal(10,7) DEFAULT NULL COMMENT '实际签到经度',
  `checkin_address` varchar(255) DEFAULT NULL COMMENT '实际签到地址',
  `checkin_deviation` int(11) DEFAULT NULL COMMENT '偏差距离（米）',
  `watch_progress` int(11) NOT NULL DEFAULT '0' COMMENT '观看进度百分比（线上培训）',
  `complete_time` datetime DEFAULT NULL COMMENT '完成时间',
  `signout_time` datetime DEFAULT NULL COMMENT '签退时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_record_id` (`record_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_checkin_status` (`checkin_status`),
  KEY `idx_is_trained` (`is_trained`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COMMENT='培训参训人员';

CREATE TABLE `safety_training_certificate` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `certificate_code` varchar(50) NOT NULL COMMENT '证书编号 CERT-YYYYMMDD-XXXX',
  `user_id` int(11) NOT NULL COMMENT '员工ID',
  `user_name` varchar(50) NOT NULL COMMENT '员工姓名（冗余）',
  `user_idcard` varchar(18) DEFAULT NULL COMMENT '员工身份证号（冗余）',
  `user_employee_no` varchar(50) DEFAULT NULL COMMENT '员工工号（冗余）',
  `user_department` varchar(100) DEFAULT NULL COMMENT '所属部门（冗余）',
  `user_position` varchar(100) DEFAULT NULL COMMENT '岗位（冗余）',
  `record_id` int(11) NOT NULL COMMENT '培训记录ID',
  `training_name` varchar(100) NOT NULL COMMENT '培训名称（冗余）',
  `training_type_id` int(11) NOT NULL COMMENT '培训类型ID',
  `training_type_name` varchar(50) DEFAULT NULL COMMENT '培训类型名称（冗余）',
  `training_content` text COMMENT '培训内容（冗余）',
  `training_duration` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '培训时长（冗余）',
  `training_mode` varchar(20) DEFAULT NULL COMMENT '培训方式（冗余）',
  `certificate_name` varchar(100) NOT NULL COMMENT '证书名称',
  `issue_date` date NOT NULL COMMENT '颁发日期',
  `expire_date` date DEFAULT NULL COMMENT '有效期截止日期（NULL=长期）',
  `validity_years` int(11) NOT NULL DEFAULT '0' COMMENT '有效年限，0=长期有效',
  `issue_authority` varchar(100) DEFAULT '' COMMENT '颁发机构',
  `status` varchar(20) NOT NULL DEFAULT 'valid' COMMENT '状态 valid有效 expired过期',
  `certificate_data` json DEFAULT NULL COMMENT '证书数据',
  `file_path` varchar(255) DEFAULT NULL COMMENT '证书文件路径',
  `verify_url` varchar(255) DEFAULT NULL COMMENT '验证查询网址',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_certificate_code` (`certificate_code`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_record_id` (`record_id`),
  KEY `idx_status` (`status`),
  KEY `idx_expire_date` (`expire_date`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='培训证书';

CREATE TABLE `safety_training_courseware` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `courseware_code` varchar(50) NOT NULL COMMENT '课件编号 CW-YYYYMMDD-XXXX',
  `courseware_name` varchar(100) NOT NULL COMMENT '课件名称',
  `file_type` varchar(20) NOT NULL COMMENT '文件类型 pdf/ppt/word/video/other',
  `file_path` varchar(255) NOT NULL COMMENT '文件路径',
  `mime_type` varchar(100) DEFAULT NULL COMMENT '文件MIME类型',
  `file_size` int(11) DEFAULT NULL COMMENT '文件大小（KB）',
  `description` varchar(255) DEFAULT NULL COMMENT '描述说明',
  `uploader_id` int(11) DEFAULT NULL COMMENT '上传人ID',
  `uploader_name` varchar(50) DEFAULT NULL COMMENT '上传人姓名',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_courseware_code` (`courseware_code`),
  KEY `idx_courseware_name` (`courseware_name`),
  KEY `idx_file_type` (`file_type`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='安全培训课件';

CREATE TABLE `safety_training_plan` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `plan_code` varchar(50) NOT NULL COMMENT '计划编号 STP-YYYYMMDD-XXXX',
  `plan_name` varchar(100) NOT NULL COMMENT '计划名称',
  `training_type_id` int(11) NOT NULL COMMENT '培训类型ID',
  `training_mode` varchar(20) NOT NULL COMMENT '培训方式 online/offline/mixed',
  `location` varchar(200) DEFAULT NULL COMMENT '培训地点',
  `content` text COMMENT '培训内容',
  `target_type` varchar(20) NOT NULL DEFAULT 'all' COMMENT '培训对象类型 all/department/position/user',
  `target_ids` varchar(500) DEFAULT NULL COMMENT '培训对象ID列表（部门/岗位/用户ID，逗号分隔）',
  `target_count` int(11) NOT NULL DEFAULT '0' COMMENT '计划培训人数',
  `completed_count` int(11) NOT NULL DEFAULT '0' COMMENT '已完成培训人数',
  `teacher_ids` varchar(500) DEFAULT NULL COMMENT '讲师ID列表，逗号分隔',
  `courseware_ids` varchar(500) DEFAULT NULL COMMENT '课件ID列表，逗号分隔',
  `plan_start_date` date DEFAULT NULL COMMENT '计划开始日期',
  `plan_end_date` date DEFAULT NULL COMMENT '计划结束日期',
  `actual_start_date` date DEFAULT NULL COMMENT '实际开始日期',
  `actual_end_date` date DEFAULT NULL COMMENT '实际结束日期',
  `responsible_id` int(11) DEFAULT NULL COMMENT '负责人ID',
  `responsible_name` varchar(50) DEFAULT NULL COMMENT '负责人姓名',
  `duration_hours` int(11) NOT NULL DEFAULT '0' COMMENT '计划培训时长（小时）',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态 pending待执行/in_progress执行中/completed已完成/cancelled已取消',
  `cancel_reason` varchar(255) DEFAULT NULL COMMENT '取消原因',
  `remark` text COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plan_code` (`plan_code`),
  KEY `idx_training_type_id` (`training_type_id`),
  KEY `idx_status` (`status`),
  KEY `idx_plan_start_date` (`plan_start_date`),
  KEY `idx_responsible_id` (`responsible_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COMMENT='安全培训计划';

CREATE TABLE `safety_training_record` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `record_code` varchar(50) NOT NULL COMMENT '记录编号 STR-YYYYMMDD-XXXX',
  `plan_id` int(11) NOT NULL COMMENT '培训计划ID',
  `plan_name` varchar(100) NOT NULL COMMENT '计划名称（冗余）',
  `training_type_id` int(11) NOT NULL COMMENT '培训类型ID',
  `training_type_name` varchar(50) DEFAULT NULL COMMENT '培训类型名称（冗余）',
  `training_mode` varchar(20) NOT NULL COMMENT '培训方式 online/offline/mixed',
  `is_online` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否线上培训：1线上 0线下',
  `location` varchar(200) DEFAULT NULL COMMENT '培训地点',
  `content` text COMMENT '培训内容',
  `teacher_ids` varchar(500) DEFAULT NULL COMMENT '讲师ID列表，逗号分隔',
  `teacher_names` varchar(500) DEFAULT NULL COMMENT '讲师姓名列表（冗余）',
  `courseware_ids` varchar(500) DEFAULT NULL COMMENT '课件ID列表，逗号分隔',
  `courseware_names` varchar(500) DEFAULT NULL COMMENT '课件名称列表（冗余）',
  `plan_count` int(11) NOT NULL DEFAULT '0' COMMENT '计划培训人数（冗余）',
  `actual_count` int(11) NOT NULL DEFAULT '0' COMMENT '实际参训人数',
  `training_date` date DEFAULT NULL COMMENT '培训日期',
  `training_start_time` datetime DEFAULT NULL COMMENT '培训开始时间',
  `training_end_time` datetime DEFAULT NULL COMMENT '培训结束时间',
  `checkin_start_time` datetime DEFAULT NULL COMMENT '签到开始时间',
  `checkin_end_time` datetime DEFAULT NULL COMMENT '签到结束时间',
  `checkin_location` varchar(200) DEFAULT NULL COMMENT '签到地点名称',
  `checkin_lat` decimal(10,7) DEFAULT NULL COMMENT '签到地点纬度',
  `checkin_lng` decimal(10,7) DEFAULT NULL COMMENT '签到地点经度',
  `checkin_radius` int(11) NOT NULL DEFAULT '100' COMMENT '签到范围（米）',
  `duration_hours` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '培训时长（小时）',
  `responsible_id` int(11) DEFAULT NULL COMMENT '负责人ID',
  `responsible_name` varchar(50) DEFAULT NULL COMMENT '负责人姓名（冗余）',
  `evaluation_score` int(11) DEFAULT NULL COMMENT '评估得分 0-100',
  `evaluation_level` varchar(20) DEFAULT NULL COMMENT '评估等级 excellent/good/general/poor',
  `evaluation_opinion` varchar(500) DEFAULT NULL COMMENT '评估意见',
  `summary` text COMMENT '培训总结',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态 pending待执行/completed已完成',
  `remark` text COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_record_code` (`record_code`),
  KEY `idx_plan_id` (`plan_id`),
  KEY `idx_training_type_id` (`training_type_id`),
  KEY `idx_training_date` (`training_date`),
  KEY `idx_status` (`status`),
  KEY `idx_is_online` (`is_online`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COMMENT='安全培训记录';

CREATE TABLE `safety_training_teacher` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `teacher_code` varchar(50) NOT NULL COMMENT '讲师编号 TCH-YYYYMMDD-XXXX',
  `teacher_name` varchar(50) NOT NULL COMMENT '讲师姓名',
  `department` varchar(100) DEFAULT NULL COMMENT '所属部门',
  `expertise` varchar(255) DEFAULT NULL COMMENT '擅长领域',
  `phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `intro` text COMMENT '讲师简介',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像图片路径',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_teacher_code` (`teacher_code`),
  KEY `idx_teacher_name` (`teacher_name`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='安全培训讲师';

CREATE TABLE `safety_training_type` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `type_code` varchar(30) NOT NULL COMMENT '类型编码 INDUCTION/REGULAR/SPECIAL/EMERGENCY',
  `type_name` varchar(50) NOT NULL COMMENT '类型名称',
  `default_mode` varchar(20) DEFAULT NULL COMMENT '默认培训方式 online/offline/mixed',
  `default_duration` int(11) DEFAULT NULL COMMENT '默认培训时长（小时）',
  `description` varchar(255) DEFAULT NULL COMMENT '描述说明',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_type_code` (`type_code`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COMMENT='安全培训类型';

CREATE TABLE `safety_training_watch_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `record_id` int(11) NOT NULL COMMENT '培训记录ID',
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `courseware_id` int(11) NOT NULL COMMENT '课件ID',
  `watch_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '观看状态 pending/watching/completed',
  `watch_duration` int(11) NOT NULL DEFAULT '0' COMMENT '已观看时长（秒）',
  `total_duration` int(11) NOT NULL DEFAULT '0' COMMENT '总时长（秒）',
  `watch_percent` int(11) NOT NULL DEFAULT '0' COMMENT '观看百分比',
  `first_watch_time` datetime DEFAULT NULL COMMENT '首次观看时间',
  `last_watch_time` datetime DEFAULT NULL COMMENT '最后观看时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_record_id` (`record_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_courseware_id` (`courseware_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='培训课件观看记录';

CREATE TABLE `salary_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_name` varchar(50) NOT NULL DEFAULT '' COMMENT '配置名称（如：2026年1月工资配置）',
  `config_year` int(11) NOT NULL DEFAULT '0' COMMENT '适用年份',
  `config_month` int(11) NOT NULL DEFAULT '0' COMMENT '适用月份',
  `config_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=草稿 1=生效 2=历史',
  `standard_work_days` int(11) NOT NULL DEFAULT '22' COMMENT '标准出勤天数',
  `overtime_rates` json DEFAULT NULL COMMENT '加班费率（周六/周日/节假日）',
  `seniority_thresholds` json DEFAULT NULL COMMENT '工龄工资阶梯',
  `insurance_rates` json DEFAULT NULL COMMENT '社保公积金费率',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_year_month` (`config_year`,`config_month`),
  KEY `idx_status` (`config_status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='工资配置主表';

CREATE TABLE `salary_config_items` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联配置ID（0=系统默认模板）',
  `item_code` varchar(30) NOT NULL DEFAULT '' COMMENT '项目编码（如 basic_wage）',
  `item_name` varchar(50) NOT NULL DEFAULT '' COMMENT '项目名称（如 基本工资）',
  `item_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=收入项 2=扣除项',
  `category` varchar(30) NOT NULL DEFAULT '' COMMENT '分类：basic_wage/allowance/piece/assessment/insurance/other/tax',
  `calculation_type` varchar(20) NOT NULL DEFAULT 'manual' COMMENT 'fixed(固定值)/ratio(比例)/formula(公式)/manual(手动录入)',
  `formula_expression` text COMMENT '公式表达式（JSON）',
  `depends_on` json DEFAULT NULL COMMENT '依赖的项目列表',
  `default_value` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '默认值',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '显示排序',
  `is_visible` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=隐藏 1=显示',
  `is_editable` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=不可编辑 1=可编辑',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=停用 1=启用',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_config_id` (`config_id`),
  KEY `idx_item_code` (`item_code`)
) ENGINE=InnoDB AUTO_INCREMENT=109 DEFAULT CHARSET=utf8mb4 COMMENT='工资项目配置表';

CREATE TABLE `salary_detail` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sheet_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联工资表ID',
  `year` int(11) NOT NULL DEFAULT '0' COMMENT '年份',
  `month` int(11) NOT NULL DEFAULT '0' COMMENT '月份',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '员工ID',
  `employee_no` varchar(30) DEFAULT NULL COMMENT '工号',
  `employee_name` varchar(50) NOT NULL DEFAULT '' COMMENT '姓名',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '部门ID',
  `department_name` varchar(100) DEFAULT '' COMMENT '部门',
  `position_level` varchar(30) DEFAULT NULL COMMENT '定级级别/岗位编码',
  `position_name` varchar(50) DEFAULT NULL COMMENT '岗位名称',
  `work_days` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '月出勤（天数）',
  `overtime_sat` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '周六加班',
  `overtime_sun` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '周日加班',
  `overtime_holiday` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '节假日加班',
  `overtime_other` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '其它加班',
  `leave_days` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '调休',
  `basic_wage_standard` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '基本工资标准',
  `position_wage_standard` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '职务/岗位工资',
  `daily_assessment_standard` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '日常考核工资',
  `actual_basic_wage` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '当月基本工资',
  `overtime_pay` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '双休日/节假日/其它加班工资',
  `actual_position_wage` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '当月职务/岗位工资',
  `actual_daily_assessment` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '当月日常考核',
  `entry_date` date DEFAULT NULL COMMENT '参加工作时间',
  `seniority_years` int(11) NOT NULL DEFAULT '0' COMMENT '工龄年限',
  `seniority_wage` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '工龄工资',
  `education_subsidy` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '学历补助',
  `title_subsidy` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '职称补助',
  `night_shift_subsidy` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '夜班补助',
  `duty_subsidy` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '值班补助',
  `driver_allowance` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '司机津贴',
  `other_allowance` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '其它补助',
  `washing_fee` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '洗理费',
  `assessment_score` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '扣分/加分',
  `assessment_deduction` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '考核扣款/奖励',
  `piece_points` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '本月累计工分',
  `piece_unit_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '工分单价（元/分）',
  `piece_wage` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '计件金额',
  `supplement` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '补差',
  `total_income` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '应税收入合计',
  `insurance_pension` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '基本养老保险费',
  `insurance_medical` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '基本医疗保险费',
  `insurance_unemployment` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '失业保险费',
  `insurance_housing_fund` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '住房公积金',
  `insurance_annuity` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '年金',
  `insurance_company` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '代扣社保集体部分（预留）',
  `union_fee` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '会员费',
  `serious_illness` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '大病',
  `income_tax` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '个税',
  `net_pay` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '实发工资',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=草稿 1=已确认',
  `detail_json` json DEFAULT NULL COMMENT '计算明细快照',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sheet_id` (`sheet_id`),
  KEY `idx_user_month` (`user_id`,`year`,`month`),
  KEY `idx_year_month` (`year`,`month`)
) ENGINE=InnoDB AUTO_INCREMENT=176 DEFAULT CHARSET=utf8mb4 COMMENT='工资计算明细表（与Excel模板一致）';

CREATE TABLE `salary_grade_standard` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联配置ID（0=系统默认模板）',
  `grade_code` varchar(30) NOT NULL DEFAULT '' COMMENT '等级编码（如 A-01）',
  `grade_name` varchar(50) NOT NULL DEFAULT '' COMMENT '等级名称（如 一类科长（B））',
  `basic_wage` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '基本工资标准',
  `position_wage` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '岗位工资标准',
  `daily_assessment_wage` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '日常考核工资标准',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_config_id` (`config_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='工资等级标准表';

CREATE TABLE `salary_insurance_import_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sheet_id` int(11) NOT NULL DEFAULT '0' COMMENT '工资表ID',
  `year` int(11) NOT NULL DEFAULT '0',
  `month` int(11) NOT NULL DEFAULT '0',
  `file_name` varchar(255) DEFAULT NULL COMMENT '导入文件名',
  `import_count` int(11) NOT NULL DEFAULT '0' COMMENT '导入条数',
  `import_by` int(11) NOT NULL DEFAULT '0' COMMENT '导入人ID',
  `import_at` datetime DEFAULT NULL COMMENT '导入时间',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COMMENT='社保导入记录表';

CREATE TABLE `salary_insurance_temp` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `year` int(11) NOT NULL DEFAULT '0',
  `month` int(11) NOT NULL DEFAULT '0',
  `employee_name` varchar(50) NOT NULL DEFAULT '' COMMENT '员工姓名',
  `insurance_pension` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '养老保险',
  `insurance_medical` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '医疗保险',
  `insurance_unemployment` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '失业保险',
  `insurance_housing_fund` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '住房公积金',
  `insurance_annuity` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '年金',
  `insurance_company` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '代扣社保集体',
  `income_tax` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT '个税',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_name_month` (`year`,`month`,`employee_name`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COMMENT='社保公积金暂存表';

CREATE TABLE `salary_standard` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `position_code` varchar(20) NOT NULL COMMENT '岗位编码',
  `position_name` varchar(50) NOT NULL COMMENT '岗位名称',
  `category` varchar(10) DEFAULT NULL COMMENT '等级类别（A/B）',
  `basic_wage` decimal(15,2) DEFAULT '0.00' COMMENT '基本工资（元/月）',
  `position_wage` decimal(15,2) DEFAULT '0.00' COMMENT '岗位工资（元/月）',
  `daily_assessment` decimal(15,2) DEFAULT '0.00' COMMENT '日常考核工资（元/月）',
  `score_price` decimal(10,2) DEFAULT '0.00' COMMENT '工分单价（分/元）',
  `effective_year` int(11) NOT NULL COMMENT '生效年份',
  `sort` int(11) DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) DEFAULT '1' COMMENT '0=停用 1=启用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_position_code_year` (`position_code`,`effective_year`),
  KEY `idx_effective_year` (`effective_year`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COMMENT='薪酬标准表';

CREATE TABLE `sales_ship_notice` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `notice_no` varchar(50) NOT NULL DEFAULT '' COMMENT '通知单编号 SN+YYYYMMDD+4位流水',
  `notice_name` varchar(100) NOT NULL DEFAULT '' COMMENT '通知单名称',
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联销售订单ID',
  `order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '销售订单编号（冗余）',
  `customer_id` int(11) NOT NULL DEFAULT '0' COMMENT '客户ID',
  `customer_name` varchar(200) NOT NULL DEFAULT '' COMMENT '客户名称（冗余）',
  `receiver` varchar(50) NOT NULL DEFAULT '' COMMENT '收货人',
  `receiver_phone` varchar(20) NOT NULL DEFAULT '' COMMENT '收货电话',
  `receiver_address` varchar(255) DEFAULT NULL COMMENT '收货地址',
  `ship_date` date DEFAULT NULL COMMENT '发货日期',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '通知状态：0草稿 1待审核 2已审核 3已下推 4已取消',
  `approval_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联统一审批实例ID',
  `auditor_id` int(11) NOT NULL DEFAULT '0' COMMENT '审核人ID',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核备注',
  `push_out_id` int(11) NOT NULL DEFAULT '0' COMMENT '下推生成出库单ID',
  `push_out_no` varchar(50) DEFAULT NULL COMMENT '下推生成出库单编号',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_notice_no` (`notice_no`),
  KEY `idx_order` (`order_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='发货通知主表';

CREATE TABLE `sales_ship_notice_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `notice_id` int(11) NOT NULL DEFAULT '0' COMMENT '通知单ID',
  `order_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联销售订单明细ID',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `product_code` varchar(50) NOT NULL DEFAULT '' COMMENT '产品编码（冗余）',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称（冗余）',
  `specification` varchar(100) DEFAULT NULL COMMENT '规格型号（冗余）',
  `unit` varchar(20) DEFAULT NULL COMMENT '单位（冗余）',
  `notice_quantity` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '通知数量',
  `out_quantity` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '实际出库数量（出库后回写）',
  `suggest_location_id` int(11) NOT NULL DEFAULT '0' COMMENT '存放货位建议ID',
  `suggest_location_name` varchar(100) DEFAULT NULL COMMENT '存放货位建议名称',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_notice` (`notice_id`),
  KEY `idx_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='发货通知明细表';

CREATE TABLE `sales_ship_notice_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `notice_id` int(11) NOT NULL DEFAULT '0' COMMENT '通知单ID',
  `action` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作类型',
  `action_label` varchar(20) NOT NULL DEFAULT '' COMMENT '操作类型标签',
  `before_status` tinyint(1) DEFAULT NULL COMMENT '操作前状态',
  `after_status` tinyint(1) DEFAULT NULL COMMENT '操作后状态',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `operator_time` datetime DEFAULT NULL COMMENT '操作时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '操作备注',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_notice_id` (`notice_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='发货通知操作日志表';

CREATE TABLE `sales_ship_order` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `ship_no` varchar(50) NOT NULL DEFAULT '' COMMENT '发货单编号 SH+YYYYMMDD+4位流水',
  `out_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联出库单ID',
  `out_no` varchar(50) NOT NULL DEFAULT '' COMMENT '出库单编号（冗余）',
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联销售订单ID',
  `order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '销售订单编号（冗余）',
  `customer_id` int(11) NOT NULL DEFAULT '0' COMMENT '客户ID',
  `customer_name` varchar(200) NOT NULL DEFAULT '' COMMENT '客户名称（冗余）',
  `receiver` varchar(50) NOT NULL DEFAULT '' COMMENT '收货人',
  `receiver_phone` varchar(20) NOT NULL DEFAULT '' COMMENT '收货电话',
  `receiver_address` varchar(255) DEFAULT NULL COMMENT '收货地址',
  `ship_date` date DEFAULT NULL COMMENT '发货日期',
  `logistics_company` varchar(100) DEFAULT NULL COMMENT '物流公司',
  `tracking_no` varchar(100) DEFAULT NULL COMMENT '物流单号',
  `ship_method` tinyint(1) NOT NULL DEFAULT '1' COMMENT '发货方式：1物流 2自提 3快递',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '发货状态：0草稿 1已发货 2已签收 3已取消 4异常',
  `signer` varchar(50) DEFAULT NULL COMMENT '签收人',
  `sign_time` datetime DEFAULT NULL COMMENT '签收时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ship_no` (`ship_no`),
  KEY `idx_out` (`out_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='发货单主表';

CREATE TABLE `sales_ship_order_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `ship_id` int(11) NOT NULL DEFAULT '0' COMMENT '发货单ID',
  `out_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联出库单明细ID',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `product_code` varchar(50) NOT NULL DEFAULT '' COMMENT '产品编码（冗余）',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称（冗余）',
  `specification` varchar(100) DEFAULT NULL COMMENT '规格型号（冗余）',
  `unit` varchar(20) DEFAULT NULL COMMENT '单位（冗余）',
  `ship_quantity` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '发货数量',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ship` (`ship_id`),
  KEY `idx_product` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='发货单明细表';

CREATE TABLE `settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `key` varchar(100) NOT NULL COMMENT '配置键名',
  `value` text COMMENT '配置值（JSON格式）',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `key_unique` (`key`)
) ENGINE=InnoDB AUTO_INCREMENT=423 DEFAULT CHARSET=utf8mb4 COMMENT='系统配置表';

CREATE TABLE `settings_company` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `company_name` varchar(200) NOT NULL DEFAULT '' COMMENT '公司全称',
  `company_short_name` varchar(50) DEFAULT NULL COMMENT '公司简称',
  `company_en_name` varchar(200) DEFAULT NULL COMMENT '英文名称',
  `legal_person` varchar(50) DEFAULT NULL COMMENT '法定代表人',
  `credit_code` varchar(50) DEFAULT NULL COMMENT '统一社会信用代码（18位）',
  `registered_capital` varchar(50) DEFAULT NULL COMMENT '注册资本',
  `establish_date` date DEFAULT NULL COMMENT '成立日期',
  `business_term_start` date DEFAULT NULL COMMENT '营业期限起始',
  `business_term_end` date DEFAULT NULL COMMENT '营业期限截止',
  `business_status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '经营状态（字典 company_business_status：1在营2注销3吊销4迁出5停业）',
  `company_type` varchar(50) DEFAULT NULL COMMENT '公司类型（字典 company_type code）',
  `industry` varchar(100) DEFAULT NULL COMMENT '所属行业',
  `business_scope` text COMMENT '经营范围',
  `phone` varchar(50) DEFAULT NULL COMMENT '联系电话',
  `hotline` varchar(50) DEFAULT NULL COMMENT '客服热线',
  `fax` varchar(50) DEFAULT NULL COMMENT '传真号码',
  `email` varchar(100) DEFAULT NULL COMMENT '电子邮箱',
  `website` varchar(200) DEFAULT NULL COMMENT '企业官网',
  `zipcode` varchar(20) DEFAULT NULL COMMENT '邮政编码',
  `address` varchar(255) DEFAULT NULL COMMENT '公司地址',
  `bank_name` varchar(100) DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(50) DEFAULT NULL COMMENT '银行账号',
  `account_type` varchar(50) DEFAULT NULL COMMENT '账户类型',
  `bank_branch_code` varchar(100) DEFAULT NULL COMMENT '开户行联行号',
  `agent` varchar(50) DEFAULT NULL COMMENT '委托代理人',
  `business_license` json DEFAULT NULL COMMENT '营业执照',
  `org_code_cert` json DEFAULT NULL COMMENT '组织机构代码证',
  `tax_cert` json DEFAULT NULL COMMENT '税务登记证',
  `account_permit` json DEFAULT NULL COMMENT '开户许可证',
  `safety_production_cert` json DEFAULT NULL COMMENT '安全生产许可证',
  `iso9001_cert` json DEFAULT NULL COMMENT '质量管理体系认证证书',
  `iso14001_cert` json DEFAULT NULL COMMENT '环境管理体系认证证书',
  `ohsas_cert` json DEFAULT NULL COMMENT '职业健康安全管理体系认证证书',
  `other_certs` json DEFAULT NULL COMMENT '其他资质证书（多图）',
  `logo` json DEFAULT NULL COMMENT '公司Logo',
  `favicon` json DEFAULT NULL COMMENT '网站Favicon',
  `brand_slogan` varchar(200) DEFAULT NULL COMMENT '品牌标语',
  `brand_color` varchar(100) DEFAULT NULL COMMENT '品牌色（主色/辅色）',
  `promo_video` varchar(500) DEFAULT NULL COMMENT '公司宣传片（视频链接）',
  `wechat_name` varchar(100) DEFAULT NULL COMMENT '微信公众号',
  `wechat_appid` varchar(100) DEFAULT NULL COMMENT '微信AppID',
  `weibo_url` varchar(300) DEFAULT NULL COMMENT '微博链接',
  `douyin_url` varchar(300) DEFAULT NULL COMMENT '抖音链接',
  `wecom_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '企业微信是否开通',
  `wecom_id` varchar(100) DEFAULT NULL COMMENT '企业微信ID',
  `wecom_secret` varchar(200) DEFAULT NULL COMMENT '企业微信Secret',
  `icp_no` varchar(100) DEFAULT NULL COMMENT 'ICP备案号',
  `police_record_no` varchar(100) DEFAULT NULL COMMENT '公安备案号',
  `copyright` varchar(300) DEFAULT NULL COMMENT '版权信息',
  `filing_subject` varchar(200) DEFAULT NULL COMMENT '备案主体名称',
  `filing_subject_type` varchar(50) DEFAULT NULL COMMENT '备案主体性质（字典）',
  `intro` text COMMENT '公司简介（富文本HTML）',
  `geo_lng` varchar(30) DEFAULT NULL COMMENT '经度',
  `geo_lat` varchar(30) DEFAULT NULL COMMENT '纬度',
  `map_location` varchar(255) DEFAULT NULL COMMENT '地图位置',
  `traffic_guide` varchar(255) DEFAULT NULL COMMENT '交通指引',
  `status` varchar(20) NOT NULL DEFAULT 'draft' COMMENT '状态：draft草稿 published已发布',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `updated_by` int(11) NOT NULL DEFAULT '0' COMMENT '最后更新人ID',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='公司信息配置表（我方，单行 id=1）';

CREATE TABLE `settings_company_partner` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `party_name` varchar(200) DEFAULT NULL COMMENT '甲方名称',
  `party_address` varchar(255) DEFAULT NULL COMMENT '甲方地址',
  `party_legal_person` varchar(50) DEFAULT NULL COMMENT '法定代表人',
  `party_agent` varchar(50) DEFAULT NULL COMMENT '委托代理人',
  `party_phone` varchar(50) DEFAULT NULL COMMENT '联系电话',
  `party_fax` varchar(50) DEFAULT NULL COMMENT '传真号码',
  `bank_name` varchar(100) DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(50) DEFAULT NULL COMMENT '银行账号',
  `account_type` varchar(50) DEFAULT NULL COMMENT '账户类型（字典 account_type）',
  `bank_branch_code` varchar(100) DEFAULT NULL COMMENT '开户行联行号',
  `tax_no` varchar(50) DEFAULT NULL COMMENT '税号',
  `vat_type` varchar(50) DEFAULT NULL COMMENT '纳税人类型（字典 vat_type）',
  `vat_rate` varchar(20) DEFAULT NULL COMMENT '增值税税率（字典 vat_rate）',
  `invoice_types` varchar(200) DEFAULT NULL COMMENT '发票类型（字典 invoice_type，逗号分隔）',
  `invoice_address` varchar(255) DEFAULT NULL COMMENT '发票邮寄地址',
  `finance_contact` varchar(50) DEFAULT NULL COMMENT '财务联系人',
  `finance_phone` varchar(50) DEFAULT NULL COMMENT '财务联系电话',
  `finance_email` varchar(100) DEFAULT NULL COMMENT '财务邮箱',
  `seal_company` json DEFAULT NULL COMMENT '公章',
  `seal_contract` json DEFAULT NULL COMMENT '合同专用章',
  `seal_finance` json DEFAULT NULL COMMENT '财务专用章',
  `seal_invoice` json DEFAULT NULL COMMENT '发票专用章',
  `seal_legal` json DEFAULT NULL COMMENT '法定代表人章',
  `default_contract_template` varchar(300) DEFAULT NULL COMMENT '默认合同模板文件',
  `payment_methods` varchar(200) DEFAULT NULL COMMENT '付款方式（字典 payment_method，逗号分隔）',
  `payment_conditions` varchar(500) DEFAULT NULL COMMENT '付款条件',
  `warranty_months` varchar(50) DEFAULT NULL COMMENT '质保期',
  `delivery_methods` varchar(200) DEFAULT NULL COMMENT '交货方式（字典 delivery_method，逗号分隔）',
  `primary_contact` varchar(50) DEFAULT NULL COMMENT '主要联系人',
  `primary_contact_title` varchar(50) DEFAULT NULL COMMENT '主要联系人职务',
  `primary_contact_phone` varchar(50) DEFAULT NULL COMMENT '主要联系人手机',
  `primary_contact_email` varchar(100) DEFAULT NULL COMMENT '主要联系人邮箱',
  `primary_contact_wechat` varchar(100) DEFAULT NULL COMMENT '主要联系人微信',
  `primary_contact_wecom` varchar(100) DEFAULT NULL COMMENT '主要联系人企业微信',
  `backup_contact` varchar(50) DEFAULT NULL COMMENT '备用联系人',
  `backup_contact_title` varchar(50) DEFAULT NULL COMMENT '备用联系人职务',
  `backup_contact_phone` varchar(50) DEFAULT NULL COMMENT '备用联系人手机',
  `backup_contact_email` varchar(100) DEFAULT NULL COMMENT '备用联系人邮箱',
  `credit_level` varchar(20) DEFAULT NULL COMMENT '信用等级（字典 credit_level）',
  `credit_limit` varchar(50) DEFAULT NULL COMMENT '授信额度',
  `credit_term` varchar(20) DEFAULT NULL COMMENT '信用期限',
  `cooperation_years` varchar(20) DEFAULT NULL COMMENT '合作年限',
  `cooperation_comment` text COMMENT '历史合作评价',
  `first_coop_date` varchar(50) DEFAULT NULL COMMENT '首次合作日期',
  `last_trade_date` varchar(50) DEFAULT NULL COMMENT '最近交易日期',
  `total_amount` varchar(50) DEFAULT NULL COMMENT '累计交易额',
  `total_orders` varchar(50) DEFAULT NULL COMMENT '累计订单数',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='客户/合作方默认信息表（单行 id=1）';

CREATE TABLE `settings_dingtalk` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `corp_id` varchar(100) NOT NULL DEFAULT '' COMMENT '企业CorpId',
  `app_key` varchar(100) NOT NULL DEFAULT '' COMMENT 'AppKey',
  `app_secret` varchar(200) NOT NULL DEFAULT '' COMMENT 'AppSecret',
  `agent_id` varchar(50) DEFAULT NULL COMMENT '应用AgentId',
  `service_name` varchar(50) NOT NULL DEFAULT '钉钉服务' COMMENT '服务名称',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `sync_enabled` tinyint(4) NOT NULL DEFAULT '0' COMMENT '同步开关 1启用 0停用',
  `sync_frequency` varchar(20) NOT NULL DEFAULT 'daily' COMMENT 'hourly/daily/weekly',
  `sync_time` varchar(10) DEFAULT NULL COMMENT '同步时间 HH:mm',
  `sync_data_types` varchar(200) DEFAULT NULL COMMENT '同步数据类型(逗号分隔)',
  `sync_start_date` date DEFAULT NULL COMMENT '同步起始日期',
  `access_token` varchar(500) DEFAULT NULL COMMENT '缓存AccessToken',
  `token_expire_time` datetime DEFAULT NULL COMMENT 'Token过期时间',
  `last_sync_time` datetime DEFAULT NULL COMMENT '最后同步时间',
  `sync_status` varchar(20) NOT NULL DEFAULT 'idle' COMMENT 'idle/syncing/success/failed',
  `sync_error` text COMMENT '同步错误信息',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_service_name` (`service_name`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='钉钉服务配置';

CREATE TABLE `settings_dingtalk_sync_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `sync_type` varchar(30) NOT NULL DEFAULT 'manual' COMMENT 'manual手动 auto自动',
  `data_type` varchar(30) NOT NULL COMMENT 'attendance/leave/outing/travel/car_apply',
  `start_time` datetime DEFAULT NULL,
  `end_time` datetime DEFAULT NULL,
  `total_count` int(11) NOT NULL DEFAULT '0',
  `success_count` int(11) NOT NULL DEFAULT '0',
  `fail_count` int(11) NOT NULL DEFAULT '0',
  `error_msg` text COMMENT '错误信息',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1成功 0失败',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sync_type` (`sync_type`),
  KEY `idx_data_type` (`data_type`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='钉钉同步日志';

CREATE TABLE `settings_dingtalk_user_map` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `dingtalk_userid` varchar(100) NOT NULL COMMENT '钉钉用户ID',
  `system_user_id` int(11) NOT NULL COMMENT '系统用户ID(users.id)',
  `system_user_name` varchar(50) NOT NULL COMMENT '系统用户姓名(冗余)',
  `employee_id` int(11) DEFAULT NULL COMMENT '员工档案ID(employee_profiles.id)',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `bind_time` datetime DEFAULT NULL COMMENT '绑定时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dingtalk_userid` (`dingtalk_userid`),
  KEY `idx_system_user_id` (`system_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='钉钉用户映射';

CREATE TABLE `settings_esign` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `service_name` varchar(50) NOT NULL DEFAULT '腾讯电子签服务' COMMENT '服务名称',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '服务状态：1启用 0停用',
  `environment` varchar(20) NOT NULL DEFAULT 'test' COMMENT '环境：test测试 production生产',
  `secret_id` varchar(100) NOT NULL DEFAULT '' COMMENT '腾讯云API密钥ID',
  `secret_key` varchar(200) NOT NULL DEFAULT '' COMMENT '腾讯云API密钥（加密存储）',
  `app_id` varchar(100) NOT NULL DEFAULT '' COMMENT '电子签应用ID',
  `space_id` varchar(100) NOT NULL DEFAULT '' COMMENT '空间ID',
  `endpoint` varchar(200) NOT NULL DEFAULT '' COMMENT '接口域名（按环境自动填充）',
  `callback_url` varchar(200) NOT NULL DEFAULT '' COMMENT '回调地址',
  `encrypt_key` varchar(100) NOT NULL DEFAULT '' COMMENT '回调消息加密Key（加密存储）',
  `default_sign_type` varchar(20) NOT NULL DEFAULT 'manual' COMMENT '默认签署方式：silent静默 manual手动',
  `sign_expire_days` int(11) NOT NULL DEFAULT '7' COMMENT '签署到期天数',
  `notify_channels` json DEFAULT NULL COMMENT '签署通知渠道',
  `seal_id` varchar(100) DEFAULT NULL COMMENT '企业印章ID',
  `operator_user_id` varchar(100) DEFAULT NULL COMMENT '操作人UserId',
  `last_test_time` datetime DEFAULT NULL COMMENT '最后测试时间',
  `test_status` varchar(20) DEFAULT NULL COMMENT '测试状态：success/failed',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_service_name` (`service_name`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='腾讯电子签服务配置';

CREATE TABLE `settings_esign_templates` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `template_id` varchar(100) NOT NULL DEFAULT '' COMMENT '模板ID（电子签平台）',
  `template_name` varchar(200) NOT NULL DEFAULT '' COMMENT '模板名称',
  `template_type` varchar(50) DEFAULT NULL COMMENT '模板类型',
  `description` varchar(500) DEFAULT NULL COMMENT '描述说明',
  `sync_time` datetime DEFAULT NULL COMMENT '同步时间',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_id` (`template_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='电子签模板表';

CREATE TABLE `settings_face` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `service_name` varchar(50) NOT NULL DEFAULT '腾讯云人脸识别服务' COMMENT '服务名称',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '服务状态：1启用 0停用',
  `region` varchar(50) NOT NULL DEFAULT 'ap-guangzhou' COMMENT '服务地域',
  `secret_id` varchar(100) NOT NULL DEFAULT '' COMMENT '腾讯云API密钥ID',
  `secret_key` varchar(200) NOT NULL DEFAULT '' COMMENT '腾讯云API密钥（加密存储）',
  `group_id` varchar(100) NOT NULL DEFAULT '' COMMENT '人员库ID（控制台创建）',
  `similarity_threshold` decimal(5,2) NOT NULL DEFAULT '80.00' COMMENT '相似度阈值（分）',
  `max_face_num` int(11) NOT NULL DEFAULT '1' COMMENT '最多识别的人脸数',
  `max_person_num` int(11) NOT NULL DEFAULT '1' COMMENT '最多返回的人员数',
  `last_test_time` datetime DEFAULT NULL COMMENT '最后测试时间',
  `test_status` varchar(20) DEFAULT NULL COMMENT '测试状态：success/failed',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='腾讯云人脸识别服务配置';

CREATE TABLE `settings_fido2` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `enabled` tinyint(1) DEFAULT '0' COMMENT '全局开关：0停用 1启用',
  `rp_id` varchar(100) DEFAULT NULL COMMENT 'RP ID（域名，空则取请求域名）',
  `rp_name` varchar(100) DEFAULT 'SC Admin' COMMENT 'RP显示名称',
  `user_verification` varchar(20) DEFAULT 'required' COMMENT '用户验证策略：required/preferred',
  `allow_remember_device` tinyint(1) DEFAULT '1' COMMENT '是否允许记住设备',
  `remember_days` int(11) DEFAULT '7' COMMENT '记住设备天数',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='FIDO2系统配置';

CREATE TABLE `settings_fido2_forced` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `target_type` varchar(20) NOT NULL COMMENT '目标类型：user/role/department',
  `target_id` int(11) NOT NULL COMMENT '目标ID（用户ID/角色ID/部门ID）',
  `reason` varchar(100) DEFAULT NULL COMMENT '强制原因说明',
  `created_at` datetime DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL COMMENT '创建人ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_target` (`target_type`,`target_id`),
  KEY `idx_target_type` (`target_type`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COMMENT='FIDO2强制启用对象表';

CREATE TABLE `settings_logistics` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `provider_code` varchar(30) NOT NULL DEFAULT '' COMMENT '服务商标识：kdniao/kuaidi100/aliyun_express/aliyun_cainiao',
  `provider_name` varchar(50) NOT NULL DEFAULT '' COMMENT '服务商名称（显示用）',
  `app_key` varchar(200) NOT NULL DEFAULT '' COMMENT 'API Key（加密存储）',
  `app_secret` varchar(200) NOT NULL DEFAULT '' COMMENT 'API Secret（加密存储）',
  `app_code` varchar(200) NOT NULL DEFAULT '' COMMENT '阿里云市场AppCode（仅阿里云服务商，加密存储）',
  `api_url` varchar(255) NOT NULL DEFAULT '' COMMENT 'API请求地址',
  `callback_url` varchar(255) NOT NULL DEFAULT '' COMMENT '订阅推送回调地址（系统自动生成）',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否默认服务商：1是 0否',
  `is_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用：1启用 0停用',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_provider` (`provider_code`),
  KEY `idx_default` (`is_default`),
  KEY `idx_enabled` (`is_enabled`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='物流服务配置表';

CREATE TABLE `settings_u8_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `service_name` varchar(50) NOT NULL DEFAULT 'U8服务' COMMENT '服务名称',
  `base_url` varchar(200) NOT NULL DEFAULT 'https://api.yonyouup.com' COMMENT 'U8接口地址',
  `from_account` varchar(100) NOT NULL DEFAULT '' COMMENT '调用方ID',
  `to_account` varchar(100) NOT NULL DEFAULT '' COMMENT '提供方ID',
  `app_key` varchar(100) NOT NULL DEFAULT '' COMMENT 'AppKey',
  `app_secret` varchar(300) NOT NULL DEFAULT '' COMMENT 'AppSecret(加密存储)',
  `ds_sequence` int(11) NOT NULL DEFAULT '1' COMMENT '数据源序号',
  `eai_url` varchar(200) DEFAULT NULL COMMENT 'EAI接口地址',
  `eai_system_code` varchar(50) DEFAULT NULL COMMENT 'EAI系统编码',
  `eai_default_user` varchar(50) DEFAULT NULL COMMENT 'EAI默认登录账号',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `sync_enabled` tinyint(4) NOT NULL DEFAULT '0' COMMENT '同步开关',
  `sync_frequency` varchar(20) NOT NULL DEFAULT 'daily' COMMENT 'hourly/daily/weekly',
  `sync_time` varchar(10) DEFAULT NULL COMMENT '同步时间 HH:mm',
  `sync_data_types` varchar(200) DEFAULT NULL COMMENT '同步数据类型(逗号分隔)',
  `callback_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'U8主动回调开关：0关闭 1开启',
  `callback_secret` varchar(255) NOT NULL DEFAULT '' COMMENT 'U8回调签名密钥（加密存储）',
  `access_token` varchar(500) DEFAULT NULL COMMENT '缓存AccessToken',
  `token_expire_time` datetime DEFAULT NULL COMMENT 'Token过期时间',
  `last_sync_time` datetime DEFAULT NULL COMMENT '最后同步时间',
  `sync_status` varchar(20) NOT NULL DEFAULT 'idle' COMMENT 'idle/syncing/success/failed',
  `sync_error` text COMMENT '同步错误信息',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_service_name` (`service_name`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='U8服务配置';

CREATE TABLE `supplier` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT '供应商名称',
  `contact` varchar(50) NOT NULL DEFAULT '' COMMENT '联系人',
  `phone` varchar(20) NOT NULL DEFAULT '' COMMENT '联系电话',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1启用 0禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='供应商表';

CREATE TABLE `system_audit_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `log_id` varchar(32) NOT NULL DEFAULT '' COMMENT '日志唯一标识(UUID)',
  `user_id` int(11) DEFAULT NULL COMMENT '操作人ID',
  `user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名（冗余）',
  `user_ip` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人IP',
  `user_agent` varchar(500) NOT NULL DEFAULT '' COMMENT 'User-Agent',
  `module` varchar(30) NOT NULL DEFAULT 'other' COMMENT '操作模块：system/chat/agent/knowledge/tool/workflow/app/apikey/user/role/permission/menu/device/safety/hr/warehouse/other',
  `action` varchar(20) NOT NULL DEFAULT 'other' COMMENT '操作类型：create/update/delete/query/login/logout/export/import/approve/other',
  `resource_type` varchar(50) NOT NULL DEFAULT '' COMMENT '资源类型',
  `resource_id` varchar(50) NOT NULL DEFAULT '' COMMENT '资源ID',
  `resource_name` varchar(255) NOT NULL DEFAULT '' COMMENT '资源名称',
  `description` varchar(500) NOT NULL DEFAULT '' COMMENT '操作描述',
  `request_method` varchar(10) NOT NULL DEFAULT '' COMMENT '请求方法',
  `request_path` varchar(255) NOT NULL DEFAULT '' COMMENT '请求路径',
  `request_params` json DEFAULT NULL COMMENT '请求参数（敏感字段脱敏）',
  `old_data` json DEFAULT NULL COMMENT '变更前数据',
  `new_data` json DEFAULT NULL COMMENT '变更后数据',
  `result` varchar(20) NOT NULL DEFAULT 'success' COMMENT '操作结果：success/error',
  `error_message` text COMMENT '错误信息',
  `duration` int(11) DEFAULT NULL COMMENT '耗时（毫秒）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_log_id` (`log_id`),
  KEY `idx_user_create` (`user_id`,`create_time`),
  KEY `idx_module_create` (`module`,`create_time`),
  KEY `idx_action_create` (`action`,`create_time`),
  KEY `idx_result_create` (`result`,`create_time`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=173 DEFAULT CHARSET=utf8mb4 COMMENT='系统操作审计日志表';

CREATE TABLE `system_hot_update_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `version_id` int(11) NOT NULL DEFAULT '0' COMMENT '版本ID',
  `stage` tinyint(1) NOT NULL DEFAULT '1' COMMENT '执行阶段：1前端资源 2后端代码 3数据库迁移 4OpCache清除 5通知发送',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '执行状态：0待执行 1执行中 2成功 3失败',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `detail` text COMMENT '执行详情（JSON）',
  `error` varchar(1000) DEFAULT NULL COMMENT '错误信息',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_version_id` (`version_id`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COMMENT='热更新执行日志表';

CREATE TABLE `system_ip_whitelist` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `ip_address` varchar(50) NOT NULL COMMENT 'IP或CIDR网段（如 192.168.1.0/24）',
  `description` varchar(255) DEFAULT NULL COMMENT '描述说明',
  `user_id` int(11) DEFAULT NULL COMMENT '关联用户ID（空为全局白名单）',
  `expire_time` datetime DEFAULT NULL COMMENT '过期时间（空为永不过期）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用0停用',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ip_address` (`ip_address`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='IP白名单表';

CREATE TABLE `system_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `log_type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1=操作日志 2=登录日志 3=系统运行日志',
  `user_id` int(11) DEFAULT NULL COMMENT '操作用户ID',
  `username` varchar(32) DEFAULT '' COMMENT '操作用户名',
  `real_name` varchar(50) DEFAULT '' COMMENT '操作用户真实姓名',
  `user_role` varchar(50) DEFAULT '' COMMENT '用户角色快照',
  `ip` varchar(45) DEFAULT '' COMMENT '操作IP',
  `user_agent` varchar(500) DEFAULT '' COMMENT '用户代理',
  `module` varchar(50) DEFAULT '' COMMENT '操作模块',
  `action` varchar(50) DEFAULT '' COMMENT '操作动作',
  `target_type` varchar(50) DEFAULT '' COMMENT '操作对象类型',
  `target_id` int(11) DEFAULT NULL COMMENT '操作对象ID',
  `target_name` varchar(200) DEFAULT '' COMMENT '操作对象名称',
  `request_method` varchar(10) DEFAULT '' COMMENT '请求方法',
  `request_url` varchar(500) DEFAULT '' COMMENT '请求URL',
  `request_params` longtext COMMENT '请求参数(JSON)',
  `response_code` int(11) DEFAULT '0' COMMENT '响应状态码',
  `response_msg` varchar(255) DEFAULT '' COMMENT '响应消息',
  `response_data` longtext COMMENT '响应数据(JSON)',
  `execution_time` decimal(10,2) DEFAULT '0.00' COMMENT '执行耗时(毫秒)',
  `memory_usage` int(11) DEFAULT '0' COMMENT '内存消耗(KB)',
  `db_queries` int(11) DEFAULT '0' COMMENT 'DB查询次数',
  `cache_hits` int(11) DEFAULT '0' COMMENT '缓存命中次数',
  `detail` text COMMENT '操作详细描述',
  `before_data` longtext COMMENT '操作前数据快照',
  `after_data` longtext COMMENT '操作后数据快照',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '日志时间',
  PRIMARY KEY (`id`),
  KEY `idx_log_type` (`log_type`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_module` (`module`),
  KEY `idx_action` (`action`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_response_code` (`response_code`),
  KEY `idx_ip` (`ip`)
) ENGINE=InnoDB AUTO_INCREMENT=8399 DEFAULT CHARSET=utf8mb4 COMMENT='系统日志表';

