CREATE TABLE `system_notification` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `msg_id` varchar(32) NOT NULL COMMENT '消息唯一标识',
  `to_user_id` int(11) NOT NULL COMMENT '接收人ID',
  `from_user_id` int(11) NOT NULL DEFAULT '0' COMMENT '发送人ID(0=系统)',
  `msg_type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1系统公告 2任务指派 3审批通知 4预警提醒 5培训通知 6工单通知',
  `title` varchar(200) NOT NULL COMMENT '消息标题',
  `content` text NOT NULL COMMENT '消息内容(支持HTML)',
  `link_url` varchar(500) DEFAULT NULL COMMENT '跳转链接',
  `link_text` varchar(50) DEFAULT NULL COMMENT '链接文字',
  `attachments` json DEFAULT NULL COMMENT '附件列表',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0未读 1已读 2已删除',
  `read_at` datetime DEFAULT NULL COMMENT '阅读时间',
  `send_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发送时间',
  `expire_time` datetime DEFAULT NULL COMMENT '过期时间',
  `is_top` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否置顶',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_msg_id` (`msg_id`),
  KEY `idx_user_status_time` (`to_user_id`,`status`,`send_time`),
  KEY `idx_send_time` (`send_time`),
  KEY `idx_msg_type` (`msg_type`)
) ENGINE=InnoDB AUTO_INCREMENT=1136 DEFAULT CHARSET=utf8mb4 COMMENT='系统消息通知';

CREATE TABLE `system_notification_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `log_id` varchar(32) NOT NULL COMMENT '日志唯一标识',
  `msg_id` int(11) NOT NULL DEFAULT '0' COMMENT '消息ID(关联system_notification)',
  `to_user_id` int(11) NOT NULL COMMENT '接收人ID',
  `to_user_name` varchar(50) NOT NULL COMMENT '接收人姓名(冗余)',
  `to_user_email` varchar(100) DEFAULT NULL COMMENT '接收人邮箱(冗余)',
  `to_user_phone` varchar(20) DEFAULT NULL COMMENT '接收人手机号(冗余)',
  `msg_type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '消息类型 1-6',
  `title` varchar(200) NOT NULL COMMENT '消息标题(冗余)',
  `channel` varchar(20) NOT NULL COMMENT '发送渠道 inbox/email/sms/wechat/dingtalk/workwx',
  `send_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0待发送 1发送中 2成功 3失败',
  `send_time` datetime DEFAULT NULL COMMENT '发送时间',
  `response_code` varchar(20) DEFAULT NULL COMMENT '响应码',
  `response_msg` text COMMENT '响应信息',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '重试次数',
  `content_snapshot` text COMMENT '消息内容快照',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_log_id` (`log_id`),
  KEY `idx_msg_id` (`msg_id`),
  KEY `idx_to_user_id` (`to_user_id`),
  KEY `idx_channel` (`channel`),
  KEY `idx_send_status` (`send_status`),
  KEY `idx_send_time` (`send_time`)
) ENGINE=InnoDB AUTO_INCREMENT=1163 DEFAULT CHARSET=utf8mb4 COMMENT='消息发送记录';

CREATE TABLE `system_notification_preference` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `msg_types` json NOT NULL COMMENT '消息类型开关',
  `channels` json NOT NULL COMMENT '渠道开关',
  `quiet_start` varchar(5) DEFAULT NULL COMMENT '免打扰开始时间 HH:mm',
  `quiet_end` varchar(5) DEFAULT NULL COMMENT '免打扰结束时间 HH:mm',
  `sound_enabled` tinyint(4) NOT NULL DEFAULT '1' COMMENT '声音开关',
  `desktop_enabled` tinyint(4) NOT NULL DEFAULT '1' COMMENT '桌面通知开关',
  `desktop_summary` tinyint(4) NOT NULL DEFAULT '1' COMMENT '桌面通知摘要开关',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='消息偏好设置';

CREATE TABLE `system_notification_template` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `template_code` varchar(50) NOT NULL COMMENT '模板编号(NT-YYYYMMDD-XXXX)',
  `template_name` varchar(100) NOT NULL COMMENT '模板名称',
  `template_type` tinyint(4) NOT NULL COMMENT '1系统公告 2任务指派 3审批通知 4预警提醒 5培训通知 6工单通知',
  `purpose` varchar(255) DEFAULT NULL COMMENT '模板用途',
  `title_template` varchar(200) NOT NULL COMMENT '消息标题模板(支持变量占位符)',
  `content_template` text NOT NULL COMMENT '消息内容模板(支持变量占位符和HTML)',
  `variables` json DEFAULT NULL COMMENT '实际使用变量列表',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_code` (`template_code`),
  KEY `idx_template_type` (`template_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='消息模板';

CREATE TABLE `system_params` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `param_key` varchar(100) NOT NULL COMMENT '参数键',
  `param_value` text COMMENT '参数值',
  `name` varchar(100) NOT NULL COMMENT '参数名称',
  `param_group` varchar(50) NOT NULL DEFAULT 'system' COMMENT '分组编码',
  `param_type` varchar(20) NOT NULL DEFAULT 'text' COMMENT 'text/number/switch/select/textarea',
  `description` varchar(500) DEFAULT '' COMMENT '参数说明',
  `options` text COMMENT '下拉选项JSON',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `is_sensitive` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否敏感',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0禁用1启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_param_key` (`param_key`),
  KEY `idx_group` (`param_group`)
) ENGINE=InnoDB AUTO_INCREMENT=262 DEFAULT CHARSET=utf8mb4 COMMENT='系统参数表';

CREATE TABLE `system_rollback_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `from_version` varchar(20) NOT NULL DEFAULT '' COMMENT '原版本号（回滚前）',
  `to_version` varchar(20) NOT NULL DEFAULT '' COMMENT '目标版本号（回滚后）',
  `rollback_reason` varchar(500) DEFAULT NULL COMMENT '回滚原因',
  `rollback_scope` text COMMENT '回滚范围（JSON数组：code/database/frontend）',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `result` tinyint(1) NOT NULL DEFAULT '1' COMMENT '回滚结果：1成功 0失败',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='版本回滚日志表';

CREATE TABLE `system_rollback_tasks` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `task_id` varchar(40) NOT NULL DEFAULT '' COMMENT '回滚任务ID',
  `version_id` int(11) NOT NULL DEFAULT '0' COMMENT '目标版本ID',
  `from_version` varchar(20) NOT NULL DEFAULT '' COMMENT '原版本号',
  `to_version` varchar(20) NOT NULL DEFAULT '' COMMENT '目标版本号',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '任务状态：pending/running/success/failed',
  `total_stages` tinyint(1) NOT NULL DEFAULT '4' COMMENT '总阶段数',
  `completed_stages` tinyint(1) NOT NULL DEFAULT '0' COMMENT '已完成阶段数',
  `current_stage` tinyint(1) NOT NULL DEFAULT '0' COMMENT '当前阶段',
  `stages` text COMMENT '阶段进度（JSON数组）',
  `error` varchar(1000) DEFAULT NULL COMMENT '错误信息',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_id` (`task_id`),
  KEY `idx_version_id` (`version_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='版本回滚任务表';

CREATE TABLE `system_security_policies` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `policy_key` varchar(100) NOT NULL COMMENT '策略键（如 password_min_length）',
  `policy_name` varchar(100) NOT NULL COMMENT '策略名称',
  `policy_value` text COMMENT '策略值（复杂配置用JSON存储）',
  `policy_type` varchar(20) NOT NULL DEFAULT 'string' COMMENT '策略类型：string/number/boolean/json/text',
  `group` varchar(30) NOT NULL DEFAULT 'other' COMMENT '策略分组：password/login/session/ip_whitelist/data/ai/notification/other',
  `description` varchar(255) DEFAULT NULL COMMENT '策略描述',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `is_system` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否系统内置：1是0否',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用0停用',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_policy_key` (`policy_key`),
  KEY `idx_group` (`group`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COMMENT='安全策略配置表';

CREATE TABLE `system_sensitive_words` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `word` varchar(100) NOT NULL COMMENT '敏感词',
  `category` varchar(30) DEFAULT NULL COMMENT '分类：political/porn/violence/ad/other',
  `severity` varchar(20) NOT NULL DEFAULT 'medium' COMMENT '严重程度：low/medium/high/critical',
  `replace_with` varchar(100) DEFAULT NULL COMMENT '替换词（为空则替换为***）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用0停用',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_word` (`word`),
  KEY `idx_category` (`category`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COMMENT='敏感词表';

CREATE TABLE `system_seq` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `seq_key` varchar(50) NOT NULL COMMENT '序号键（编号前缀）',
  `seq_value` int(11) NOT NULL DEFAULT '0' COMMENT '当前序号值',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_seq_key` (`seq_key`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COMMENT='系统序号表';

CREATE TABLE `system_update_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `version_id` int(11) NOT NULL DEFAULT '0' COMMENT '版本ID',
  `change_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '变更类型：1新增功能 2功能优化 3Bug修复 4性能优化 5安全更新 6数据库变更',
  `change_content` text COMMENT '变更内容',
  `impact_scope` varchar(500) DEFAULT NULL COMMENT '影响范围',
  `file_list` text COMMENT '变更文件列表（JSON数组）',
  `db_migrations` text COMMENT '数据库迁移文件（JSON数组）',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_version_id` (`version_id`)
) ENGINE=InnoDB AUTO_INCREMENT=184 DEFAULT CHARSET=utf8mb4 COMMENT='版本更新日志表';

CREATE TABLE `system_version_config` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `config_key` varchar(100) NOT NULL DEFAULT '' COMMENT '配置键（唯一）',
  `config_value` text COMMENT '配置值',
  `group_name` varchar(50) NOT NULL DEFAULT '' COMMENT '配置分组',
  `description` varchar(255) DEFAULT NULL COMMENT '配置描述',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_config_key` (`config_key`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COMMENT='版本管理配置表';

CREATE TABLE `system_versions` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `platform` varchar(20) NOT NULL DEFAULT 'admin' COMMENT '平台：admin/h5/miniprogram/api',
  `platform_name` varchar(50) DEFAULT NULL COMMENT '平台显示名称',
  `version_no` varchar(20) NOT NULL DEFAULT '' COMMENT '版本号，语义化 vX.Y.Z',
  `version_name` varchar(100) NOT NULL DEFAULT '' COMMENT '版本名称',
  `version_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '版本类型：1正式版 2测试版 3热修复版',
  `env` tinyint(1) NOT NULL DEFAULT '3' COMMENT '环境标识：1开发 2测试 3生产',
  `release_time` datetime DEFAULT NULL COMMENT '发布时间',
  `release_note` text COMMENT '发布说明',
  `build_url` varchar(255) DEFAULT NULL COMMENT '构建产物地址',
  `build_hash` varchar(40) DEFAULT NULL COMMENT 'Git commit hash',
  `file_size` bigint(20) DEFAULT NULL COMMENT '产物大小（字节）',
  `release_by` int(11) NOT NULL DEFAULT '0' COMMENT '发布人ID',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0草稿 1已发布 2已归档',
  `gray_ratio` int(11) DEFAULT '0' COMMENT '灰度比例 0-100',
  `min_supported_version` varchar(20) DEFAULT NULL COMMENT '最低兼容版本',
  `is_force_update` tinyint(1) DEFAULT '0' COMMENT '是否强制更新',
  `approve_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '审批状态：0无需审批 1待审批 2已审批 3已驳回',
  `approve_by` int(11) NOT NULL DEFAULT '0' COMMENT '审批人ID',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_remark` varchar(500) DEFAULT NULL COMMENT '审批备注',
  `prev_version_id` int(11) NOT NULL DEFAULT '0' COMMENT '前置版本ID（追溯版本链）',
  `is_current` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否当前版本：1是 0否',
  `hot_update_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '热更新状态 0待执行 1执行中 2已生效 3失败',
  `hot_update_time` datetime DEFAULT NULL COMMENT '热更新执行时间',
  `hot_update_log` text COMMENT '热更新执行日志（JSON数组）',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_version_no` (`version_no`),
  KEY `idx_status` (`status`),
  KEY `idx_env` (`env`),
  KEY `idx_is_current` (`is_current`),
  KEY `idx_prev_version` (`prev_version_id`),
  KEY `idx_platform` (`platform`)
) ENGINE=InnoDB AUTO_INCREMENT=132 DEFAULT CHARSET=utf8mb4 COMMENT='系统版本表';

CREATE TABLE `theme_schemes` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '方案名称',
  `description` varchar(500) NOT NULL DEFAULT '' COMMENT '方案描述',
  `config` longtext COMMENT '完整配置JSON',
  `is_active` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否激活',
  `created_by` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '创建人',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='界面配置方案表';

CREATE TABLE `title_subsidy_standard` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title_level` varchar(30) NOT NULL COMMENT '职称等级',
  `title_code` varchar(20) NOT NULL COMMENT '职称编码',
  `subsidy_amount` decimal(15,2) DEFAULT '0.00' COMMENT '补助金额（元/月）',
  `effective_year` int(11) NOT NULL COMMENT '生效年份',
  `sort` int(11) DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) DEFAULT '1' COMMENT '0=停用 1=启用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_title_code_year` (`title_code`,`effective_year`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='职称补助标准表';

CREATE TABLE `u8_callback_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `tradeid` varchar(64) NOT NULL DEFAULT '',
  `biz_type` varchar(30) NOT NULL DEFAULT '',
  `biz_no` varchar(64) NOT NULL DEFAULT '',
  `errcode` int(11) NOT NULL DEFAULT '0',
  `errmsg` varchar(255) NOT NULL DEFAULT '',
  `payload` text,
  `sign_result` tinyint(1) NOT NULL DEFAULT '1',
  `process_status` varchar(20) NOT NULL DEFAULT 'processing',
  `handle_msg` varchar(255) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tradeid` (`tradeid`),
  KEY `idx_biz_type` (`biz_type`),
  KEY `idx_process_status` (`process_status`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='U8主动回调日志';

CREATE TABLE `u8_document` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `biz_type` varchar(30) NOT NULL DEFAULT '',
  `biz_no` varchar(64) NOT NULL DEFAULT '',
  `doc_status` varchar(20) NOT NULL DEFAULT 'submitted',
  `u8_errcode` int(11) NOT NULL DEFAULT '0',
  `u8_errmsg` varchar(255) NOT NULL DEFAULT '',
  `u8_tradeid` varchar(64) NOT NULL DEFAULT '',
  `u8_callback_time` datetime DEFAULT NULL,
  `remark` varchar(255) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_biz` (`biz_type`,`biz_no`),
  KEY `idx_doc_status` (`doc_status`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='U8单据状态台账';

CREATE TABLE `user_password_histories` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `password_hash` varchar(255) NOT NULL DEFAULT '' COMMENT '历史密码哈希',
  `created_at` datetime DEFAULT NULL COMMENT '记录时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='用户密码历史表（安全策略-密码历史限制）';

CREATE TABLE `user_roles` (
  `user_id` int(11) unsigned NOT NULL,
  `role_id` int(11) unsigned NOT NULL,
  PRIMARY KEY (`user_id`,`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户角色关联表';

CREATE TABLE `user_webauthn_credentials` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `credential_id` varchar(255) NOT NULL COMMENT '凭证ID',
  `public_key` text NOT NULL COMMENT '公钥（base64）',
  `sign_counter` int(11) DEFAULT '0' COMMENT '签名计数器',
  `device_name` varchar(100) DEFAULT '鸿蒙手机' COMMENT '设备名称',
  `device_type` varchar(30) DEFAULT NULL COMMENT '设备类型：yubikey/harmony_passkey/other',
  `aaguid` varchar(36) DEFAULT NULL COMMENT '认证器GUID',
  `transports` varchar(100) DEFAULT 'usb' COMMENT '传输方式',
  `last_used_at` datetime DEFAULT NULL COMMENT '最后使用时间',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_credential_id` (`credential_id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COMMENT='WebAuthn凭证表';

CREATE TABLE `users` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL DEFAULT '' COMMENT '登录账号',
  `password` varchar(255) DEFAULT NULL COMMENT 'bcrypt密码',
  `real_name` varchar(50) NOT NULL DEFAULT '' COMMENT '真实姓名',
  `phone` varchar(11) NOT NULL DEFAULT '' COMMENT '手机号',
  `employee_id` varchar(50) DEFAULT NULL COMMENT '工号',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `user_type` tinyint(4) NOT NULL DEFAULT '3' COMMENT '1后台用户 2普通员工 3两者皆是',
  `allow_login` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1允许 0禁止登录后台',
  `fido2_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已绑定手机密钥',
  `fido2_require` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否强制启用（命中强制规则时落库标记）',
  `fido2_require_reason` varchar(100) DEFAULT NULL COMMENT '强制启用原因',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1启用 0禁用',
  `is_super_admin` tinyint(4) NOT NULL DEFAULT '0' COMMENT '1超级管理员',
  `department_id` int(11) unsigned DEFAULT NULL COMMENT '部门ID',
  `position_id` int(11) unsigned DEFAULT NULL,
  `wx_mini_openid` varchar(100) DEFAULT NULL COMMENT '小程序openid',
  `wx_mp_openid` varchar(100) DEFAULT NULL COMMENT '公众号openid',
  `wx_unionid` varchar(100) DEFAULT NULL COMMENT '微信unionid',
  `position` varchar(50) DEFAULT NULL COMMENT '岗位',
  `rank_id` int(11) NOT NULL DEFAULT '0' COMMENT '岗位等级ID（关联hr_rank）',
  `leader_id` int(11) DEFAULT NULL COMMENT '直属上级ID',
  `gender` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0未知 1男 2女',
  `birthday` date DEFAULT NULL,
  `hire_date` date DEFAULT NULL,
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像URL',
  `last_login_at` datetime DEFAULT NULL COMMENT '最后登录时间',
  `last_login_ip` varchar(45) DEFAULT NULL COMMENT '最后登录IP',
  `password_changed_at` datetime DEFAULT NULL COMMENT '最近一次密码修改时间（空=未自行修改）',
  `wechat_oa_openid` varchar(64) DEFAULT NULL COMMENT '微信公众号openid',
  `wechat_mini_openid` varchar(64) DEFAULT NULL COMMENT '微信小程序openid',
  `wechat_unionid` varchar(64) DEFAULT NULL COMMENT '微信开放平台unionid',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`,`deleted_at`),
  UNIQUE KEY `uk_phone` (`phone`,`deleted_at`),
  UNIQUE KEY `uk_email` (`email`,`deleted_at`),
  UNIQUE KEY `uk_employee_id` (`employee_id`,`deleted_at`),
  UNIQUE KEY `uk_wechat_oa` (`wechat_oa_openid`,`deleted_at`),
  UNIQUE KEY `uk_wechat_mini` (`wechat_mini_openid`,`deleted_at`),
  KEY `idx_department` (`department_id`),
  KEY `idx_wx_unionid` (`wx_unionid`)
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb4 COMMENT='用户表';

CREATE TABLE `version_publish_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `version_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联版本ID',
  `platform` varchar(20) NOT NULL DEFAULT '' COMMENT '平台标识',
  `action` varchar(20) NOT NULL DEFAULT '' COMMENT 'publish/gray/rollback/delete',
  `before_status` tinyint(1) DEFAULT NULL,
  `after_status` tinyint(1) DEFAULT NULL,
  `gray_ratio_before` int(11) DEFAULT NULL,
  `gray_ratio_after` int(11) DEFAULT NULL,
  `operator_id` int(11) NOT NULL DEFAULT '0',
  `operator_name` varchar(50) DEFAULT '' COMMENT '操作人',
  `remark` varchar(255) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_version_id` (`version_id`),
  KEY `idx_platform` (`platform`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='版本发布操作日志表';

CREATE TABLE `voice_command_logs` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作用户ID',
  `raw_input` varchar(500) NOT NULL DEFAULT '' COMMENT '用户原始输入',
  `intent` varchar(20) DEFAULT NULL COMMENT '识别意图',
  `entities` json DEFAULT NULL COMMENT '提取的实体',
  `confidence` decimal(5,4) DEFAULT NULL COMMENT '置信度',
  `matched_template_id` int(11) DEFAULT NULL COMMENT '匹配的模板ID',
  `execution_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=成功 1=失败',
  `error_message` text COMMENT '错误信息',
  `response_time` int(11) DEFAULT NULL COMMENT '响应时间（毫秒）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_intent` (`intent`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='自然语言指令日志表';

CREATE TABLE `voice_execution_history` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `command_log_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联指令日志ID',
  `tool_name` varchar(50) DEFAULT NULL COMMENT '调用的工具名称',
  `tool_params` json DEFAULT NULL COMMENT '工具参数',
  `tool_result` json DEFAULT NULL COMMENT '工具返回结果',
  `executed_at` datetime NOT NULL COMMENT '执行时间',
  PRIMARY KEY (`id`),
  KEY `idx_command_log_id` (`command_log_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='自然语言执行历史表';

CREATE TABLE `voice_feedback` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `command_log_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联指令日志ID',
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '反馈用户ID',
  `feedback_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=有用 2=无用',
  `feedback_content` text COMMENT '反馈内容',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_command_log_id` (`command_log_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='自然语言用户反馈表';

CREATE TABLE `voice_intent_templates` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `trigger_pattern` varchar(200) NOT NULL DEFAULT '' COMMENT '触发语句（支持{参数}占位符）',
  `intent_type` varchar(20) NOT NULL DEFAULT 'query' COMMENT 'query/navigate/operate/analyze/knowledge',
  `target_action` varchar(50) DEFAULT NULL COMMENT '目标动作（工具名或路由）',
  `param_mapping` json DEFAULT NULL COMMENT '参数映射',
  `response_template` text COMMENT '响应模板',
  `use_count` int(11) NOT NULL DEFAULT '0' COMMENT '使用次数',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=禁用 1=启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COMMENT='自然语言指令模板表';

CREATE TABLE `warehouse` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `warehouse_code` varchar(30) NOT NULL DEFAULT '' COMMENT '仓库编码 WH001',
  `warehouse_name` varchar(100) NOT NULL DEFAULT '' COMMENT '仓库名称',
  `warehouse_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '仓库类型：1原材料仓 2半成品仓 3成品仓 4备件仓 5待检仓 6报废仓',
  `address` varchar(200) DEFAULT NULL COMMENT '仓库地址',
  `manager_id` int(11) NOT NULL DEFAULT '0' COMMENT '负责人ID',
  `manager_name` varchar(50) NOT NULL DEFAULT '' COMMENT '负责人姓名（冗余）',
  `phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_warehouse_code` (`warehouse_code`),
  KEY `idx_type` (`warehouse_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='仓库表';

CREATE TABLE `warehouse_device_receipt` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `receipt_no` varchar(30) NOT NULL DEFAULT '' COMMENT '入库单编号 DR0001',
  `receive_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '入库来源：1维修完成 2调拨 3盘盈 4其他',
  `receive_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联产品接收单ID（/business/receive）',
  `receive_no` varchar(30) NOT NULL DEFAULT '' COMMENT '关联产品接收单编号（冗余）',
  `repair_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联维修工单ID',
  `repair_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '关联维修工单编号',
  `customer_id` int(11) NOT NULL DEFAULT '0' COMMENT '客户ID',
  `customer_name` varchar(100) NOT NULL DEFAULT '' COMMENT '客户名称',
  `warehouse_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库仓库ID',
  `warehouse_name` varchar(100) NOT NULL DEFAULT '' COMMENT '入库仓库名称',
  `warehouse_keeper_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库人ID',
  `warehouse_keeper_name` varchar(50) NOT NULL DEFAULT '' COMMENT '入库人姓名',
  `receive_date` date DEFAULT NULL COMMENT '入库日期',
  `quantity` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '入库数量',
  `price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '入库单价（成本）',
  `total` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '入库总价',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0草稿 1待审核 2已审核 3已入库 4已驳回 5已撤销',
  `auditor_id` int(11) NOT NULL DEFAULT '0' COMMENT '审核人ID',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核备注',
  `reason` varchar(500) DEFAULT NULL COMMENT '入库原因',
  `remark` varchar(500) DEFAULT NULL COMMENT '整体备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_receipt_no` (`receipt_no`),
  KEY `idx_receive_id` (`receive_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='产品入库单主表';

CREATE TABLE `warehouse_device_receipt_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `receipt_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库单ID',
  `receive_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联产品接收明细ID',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `product_code` varchar(30) NOT NULL DEFAULT '' COMMENT '产品编码',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称',
  `spec` varchar(200) DEFAULT NULL COMMENT '规格型号',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位',
  `quantity` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '入库数量',
  `price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '入库单价',
  `total` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '入库总价',
  `device_no` varchar(100) DEFAULT NULL COMMENT '设备编号/序列号',
  `location_id` int(11) NOT NULL DEFAULT '0' COMMENT '存放货位ID',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_receipt_id` (`receipt_id`),
  KEY `idx_receive_item_id` (`receive_item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='产品入库明细表';

CREATE TABLE `warehouse_device_receipt_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `receipt_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库单ID',
  `action_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作类型：1创建 2编辑 3提交审核 4审核通过 5审核驳回 6确认入库 7撤销 8删除',
  `action_label` varchar(30) NOT NULL DEFAULT '' COMMENT '操作类型标签',
  `from_status` tinyint(1) DEFAULT NULL COMMENT '操作前状态',
  `to_status` tinyint(1) DEFAULT NULL COMMENT '操作后状态',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `action_time` datetime DEFAULT NULL COMMENT '操作时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '操作备注',
  `field_snapshot` json DEFAULT NULL COMMENT '变更字段快照（JSON）',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_receipt_id` (`receipt_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='产品入库操作日志表';

CREATE TABLE `warehouse_in_attachment` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `in_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库单ID',
  `file_name` varchar(255) NOT NULL DEFAULT '' COMMENT '文件名',
  `file_path` varchar(500) NOT NULL DEFAULT '' COMMENT '文件路径',
  `file_size` int(11) NOT NULL DEFAULT '0' COMMENT '文件大小（字节）',
  `file_type` varchar(50) NOT NULL DEFAULT '' COMMENT '文件类型（扩展名）',
  `uploader_id` int(11) NOT NULL DEFAULT '0' COMMENT '上传人ID',
  `uploader_name` varchar(50) NOT NULL DEFAULT '' COMMENT '上传人姓名',
  `upload_time` datetime DEFAULT NULL COMMENT '上传时间',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_in_id` (`in_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='入库单附件表';

CREATE TABLE `warehouse_location` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `warehouse_id` int(11) NOT NULL DEFAULT '0' COMMENT '仓库ID',
  `location_code` varchar(50) NOT NULL DEFAULT '' COMMENT '货位编码 WH001-A-01（同一仓库内唯一）',
  `location_name` varchar(100) NOT NULL DEFAULT '' COMMENT '货位名称',
  `location_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '货位类型：1普通货位 2货架 3堆场 4托盘位',
  `area` varchar(30) DEFAULT NULL COMMENT '区域（A区/B区/C区）',
  `capacity` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '承载能力（kg）',
  `occupancy_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '占用状态：0空闲 1部分占用 2已满（系统自动维护）',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_warehouse_id` (`warehouse_id`),
  KEY `idx_type` (`location_type`),
  KEY `idx_occupancy` (`occupancy_status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='货位表';

CREATE TABLE `warehouse_material` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `material_code` varchar(30) NOT NULL DEFAULT '' COMMENT '物料编码 M001',
  `material_name` varchar(200) NOT NULL DEFAULT '' COMMENT '物料名称',
  `category_id` int(11) NOT NULL DEFAULT '0' COMMENT '物料分类ID',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联产品ID（产品同步物料）',
  `specification` varchar(200) DEFAULT NULL COMMENT '规格型号',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位',
  `material_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '物料类型：1原材料 2半成品 3成品 4备件 5辅料',
  `safety_stock` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '安全库存量',
  `max_stock` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '最高库存量',
  `min_stock` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '最低库存量',
  `purchase_cycle` int(11) NOT NULL DEFAULT '0' COMMENT '采购周期（天）',
  `reference_price` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '参考采购单价（元）',
  `reference_cost` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '参考成本单价（元）',
  `costing_method` tinyint(1) NOT NULL DEFAULT '1' COMMENT '计价方式：1移动加权平均 2先进先出',
  `avg_cost_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '当前加权平均单价（元）',
  `alert_ignored` tinyint(1) NOT NULL DEFAULT '0' COMMENT '预警忽略：0否 1是',
  `alert_ignore_reason` varchar(255) DEFAULT NULL COMMENT '预警忽略原因',
  `default_supplier_id` int(11) NOT NULL DEFAULT '0' COMMENT '默认供应商ID',
  `location_id` int(11) NOT NULL DEFAULT '0' COMMENT '存放货位ID',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `images` json DEFAULT NULL COMMENT '物料图片URL数组',
  `qrcode_url` varchar(255) DEFAULT '',
  `qrcode_generated_at` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_material_code` (`material_code`),
  KEY `idx_category` (`category_id`),
  KEY `idx_type` (`material_type`),
  KEY `idx_location` (`location_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=1132 DEFAULT CHARSET=utf8mb4 COMMENT='物料表';

CREATE TABLE `warehouse_material_category` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` int(11) NOT NULL DEFAULT '0' COMMENT '父分类ID（0为顶级）',
  `category_name` varchar(100) NOT NULL DEFAULT '' COMMENT '分类名称',
  `category_code` varchar(30) NOT NULL DEFAULT '' COMMENT '分类编码',
  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0停用',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COMMENT='物料分类表';

CREATE TABLE `warehouse_pick` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `pick_no` varchar(30) NOT NULL DEFAULT '' COMMENT '领料单编号 PK+YYYYMMDD+XXXX',
  `pick_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '领料类型：1生产领料 2维修领料 3研发领料 4其他领料',
  `production_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联生产工单ID',
  `production_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '关联生产工单编号（冗余）',
  `repair_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联维修工单ID',
  `repair_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '关联维修工单编号（冗余）',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联产品ID',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '领料部门ID',
  `department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '领料部门名称（冗余）',
  `picker_id` int(11) NOT NULL DEFAULT '0' COMMENT '领料人ID',
  `picker_name` varchar(50) NOT NULL DEFAULT '' COMMENT '领料人姓名（冗余）',
  `pick_date` date DEFAULT NULL COMMENT '领料日期',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '领料状态：0草稿 1待审核 2已审核 3已领料 4已驳回 5已撤销',
  `auditor_id` int(11) NOT NULL DEFAULT '0' COMMENT '审核人ID',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核备注/驳回原因',
  `purpose` varchar(500) NOT NULL DEFAULT '' COMMENT '用途说明',
  `version` int(11) NOT NULL DEFAULT '1' COMMENT '主版本号',
  `version_sub` int(11) NOT NULL DEFAULT '0' COMMENT '次版本号',
  `latest_version_id` int(11) NOT NULL DEFAULT '0' COMMENT '最新版本快照ID',
  `remark` varchar(500) DEFAULT NULL COMMENT '整体备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pick_no` (`pick_no`),
  KEY `idx_status` (`status`),
  KEY `idx_pick_date` (`pick_date`),
  KEY `idx_production_order` (`production_order_id`),
  KEY `idx_repair_order` (`repair_order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='配件领料单主表';

CREATE TABLE `warehouse_pick_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `pick_id` int(11) NOT NULL DEFAULT '0' COMMENT '领料单ID',
  `production_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联生产工单明细ID',
  `repair_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联维修工单明细ID',
  `material_id` int(11) NOT NULL DEFAULT '0' COMMENT '物料ID',
  `material_code` varchar(30) NOT NULL DEFAULT '' COMMENT '物料编码（冗余）',
  `material_name` varchar(200) NOT NULL DEFAULT '' COMMENT '物料名称（冗余）',
  `spec` varchar(200) DEFAULT NULL COMMENT '规格型号（冗余）',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位（冗余）',
  `apply_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '申请数量',
  `actual_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '实际领料数量',
  `out_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '出库单价（加权平均价）',
  `out_total` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '出库总价',
  `picker` varchar(50) DEFAULT NULL COMMENT '领取人',
  `pick_date` date DEFAULT NULL COMMENT '领取日期',
  `location_id` int(11) NOT NULL DEFAULT '0' COMMENT '存放货位ID（出库货位）',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pick_id` (`pick_id`),
  KEY `idx_material_id` (`material_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='配件领料明细表';

CREATE TABLE `warehouse_pick_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `pick_id` int(11) NOT NULL DEFAULT '0' COMMENT '领料单ID',
  `action_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作类型：1创建 2编辑 3提交审核 4审核通过 5审核驳回 6确认发料 7撤销 8删除 9版本恢复',
  `action_label` varchar(30) NOT NULL DEFAULT '' COMMENT '操作类型标签',
  `from_status` tinyint(1) DEFAULT NULL COMMENT '操作前状态',
  `to_status` tinyint(1) DEFAULT NULL COMMENT '操作后状态',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `action_time` datetime DEFAULT NULL COMMENT '操作时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '操作备注',
  `field_snapshot` json DEFAULT NULL COMMENT '变更字段快照',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pick_id` (`pick_id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COMMENT='配件领料单操作日志表';

CREATE TABLE `warehouse_pick_version` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `pick_id` int(11) NOT NULL DEFAULT '0' COMMENT '领料单ID',
  `version_no` varchar(10) NOT NULL DEFAULT '' COMMENT '版本号 V1.0',
  `snapshot` json DEFAULT NULL COMMENT '完整数据快照（主表+明细）',
  `change_fields` json DEFAULT NULL COMMENT '变更字段列表',
  `change_summary` varchar(500) DEFAULT NULL COMMENT '变更摘要',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pick_id` (`pick_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='配件领料单版本快照表';

CREATE TABLE `warehouse_product_in` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `in_no` varchar(30) NOT NULL DEFAULT '' COMMENT '入库单编号 IN0001',
  `source_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '来源类型：1产品接收单 2调拨 3盘盈 4其他',
  `source_id` int(11) NOT NULL DEFAULT '0' COMMENT '来源单据ID（产品接收单ID）',
  `source_no` varchar(30) NOT NULL DEFAULT '' COMMENT '来源单据编号（冗余）',
  `warehouse_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库仓库ID',
  `warehouse_name` varchar(100) NOT NULL DEFAULT '' COMMENT '入库仓库名称',
  `in_user_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库人ID',
  `in_user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '入库人姓名',
  `in_date` date DEFAULT NULL COMMENT '入库日期',
  `total_quantity` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '总数量',
  `total_amount` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '总金额',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0草稿 1待审核 2已审核 3已入库 4已驳回 5已撤销',
  `auditor_id` int(11) NOT NULL DEFAULT '0' COMMENT '审核人ID',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核备注',
  `remark` varchar(500) DEFAULT NULL COMMENT '整体备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_in_no` (`in_no`),
  KEY `idx_source_id` (`source_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='产品入库单主表';

CREATE TABLE `warehouse_product_in_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `in_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库单ID',
  `source_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '来源明细ID（产品接收明细）',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `product_code` varchar(50) NOT NULL DEFAULT '' COMMENT '产品编码',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称',
  `specification` varchar(200) DEFAULT NULL COMMENT '规格型号',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位',
  `quantity` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '入库数量',
  `unit_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '入库单价',
  `total_price` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '入库总价',
  `serial_number` varchar(100) DEFAULT NULL COMMENT '设备编号/序列号',
  `location_id` int(11) NOT NULL DEFAULT '0' COMMENT '存放货位ID',
  `location_name` varchar(100) NOT NULL DEFAULT '' COMMENT '存放货位名称（冗余）',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_in_id` (`in_id`),
  KEY `idx_source_item_id` (`source_item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='产品入库明细表';

CREATE TABLE `warehouse_product_in_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `in_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库单ID',
  `action` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作类型：1创建 2编辑 3提交审核 4审核通过 5审核驳回 6确认入库 7撤销 8删除',
  `action_label` varchar(20) NOT NULL DEFAULT '' COMMENT '操作类型标签',
  `before_status` tinyint(1) DEFAULT NULL COMMENT '操作前状态',
  `after_status` tinyint(1) DEFAULT NULL COMMENT '操作后状态',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `operator_time` datetime DEFAULT NULL COMMENT '操作时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '操作备注',
  `changed_fields` json DEFAULT NULL COMMENT '变更字段快照（JSON）',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_in_id` (`in_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='产品入库操作日志表';

CREATE TABLE `warehouse_product_out` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `out_no` varchar(30) NOT NULL DEFAULT '' COMMENT '出库单编号 OUT0001',
  `out_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '出库类型：1维修完成交付 2调拨出库 3销售出库 4其他出库',
  `source_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '来源类型：1维修工单 2销售订单 3调拨单 4其他',
  `source_id` int(11) NOT NULL DEFAULT '0' COMMENT '来源单据ID',
  `source_no` varchar(50) NOT NULL DEFAULT '' COMMENT '来源单据编号（冗余）',
  `repair_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联维修工单ID',
  `repair_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '维修工单编号（冗余）',
  `sales_order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联销售订单ID',
  `sales_order_no` varchar(50) NOT NULL DEFAULT '' COMMENT '销售订单编号（冗余）',
  `customer_id` int(11) NOT NULL DEFAULT '0' COMMENT '客户ID',
  `customer_name` varchar(100) NOT NULL DEFAULT '' COMMENT '客户名称',
  `delivery_address` varchar(200) DEFAULT NULL COMMENT '交付地址',
  `warehouse_id` int(11) NOT NULL DEFAULT '0' COMMENT '出库仓库ID',
  `warehouse_name` varchar(100) NOT NULL DEFAULT '' COMMENT '出库仓库名称',
  `out_user_id` int(11) NOT NULL DEFAULT '0' COMMENT '出库人ID',
  `out_user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '出库人姓名',
  `out_date` date DEFAULT NULL COMMENT '出库日期',
  `total_quantity` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '总数量',
  `total_amount` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '总金额（出库成本）',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0草稿 1待审核 2已审核 3已出库 4已驳回 5已撤销',
  `approval_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联统一审批实例ID',
  `auditor_id` int(11) NOT NULL DEFAULT '0' COMMENT '审核人ID',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核备注',
  `ship_method` tinyint(1) NOT NULL DEFAULT '0' COMMENT '发货方式：1物流 2自提 3快递',
  `ship_company` varchar(100) DEFAULT NULL COMMENT '物流公司',
  `ship_no` varchar(100) DEFAULT NULL COMMENT '物流单号',
  `ship_date` date DEFAULT NULL COMMENT '发货日期',
  `consignee` varchar(50) DEFAULT NULL COMMENT '收货人',
  `consignee_phone` varchar(20) DEFAULT NULL COMMENT '收货电话',
  `remark` varchar(500) DEFAULT NULL COMMENT '整体备注',
  `creator` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_out_no` (`out_no`),
  KEY `idx_repair_order_id` (`repair_order_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='产品出库单主表';

CREATE TABLE `warehouse_product_out_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `out_id` int(11) NOT NULL DEFAULT '0' COMMENT '出库单ID',
  `product_id` int(11) NOT NULL DEFAULT '0' COMMENT '产品ID',
  `product_code` varchar(50) NOT NULL DEFAULT '' COMMENT '产品编码',
  `product_name` varchar(200) NOT NULL DEFAULT '' COMMENT '产品名称',
  `specification` varchar(200) DEFAULT NULL COMMENT '规格型号',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位',
  `quantity` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '出库数量',
  `unit_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '出库单价（当前加权平均价）',
  `total_price` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '出库总价',
  `serial_number` varchar(100) DEFAULT NULL COMMENT '设备编号/序列号',
  `location_id` int(11) NOT NULL DEFAULT '0' COMMENT '出库货位ID',
  `location_name` varchar(100) NOT NULL DEFAULT '' COMMENT '出库货位名称（冗余）',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_out_id` (`out_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='产品出库明细表';

CREATE TABLE `warehouse_product_out_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `out_id` int(11) NOT NULL DEFAULT '0' COMMENT '出库单ID',
  `action` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作类型：1创建 2编辑 3提交审核 4审核通过 5审核驳回 6确认出库 7撤销 8删除',
  `action_label` varchar(20) NOT NULL DEFAULT '' COMMENT '操作类型标签',
  `before_status` tinyint(1) DEFAULT NULL COMMENT '操作前状态',
  `after_status` tinyint(1) DEFAULT NULL COMMENT '操作后状态',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `operator_time` datetime DEFAULT NULL COMMENT '操作时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '操作备注',
  `changed_fields` json DEFAULT NULL COMMENT '变更字段快照（JSON）',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_out_id` (`out_id`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COMMENT='产品出库操作日志表';

CREATE TABLE `warehouse_purchase_in` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `in_no` varchar(30) NOT NULL DEFAULT '' COMMENT '入库单编号 IN+YYYYMMDD+XXXX',
  `arrival_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联采购到货单ID',
  `arrival_no` varchar(30) NOT NULL DEFAULT '' COMMENT '关联到货单编号（冗余）',
  `order_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联采购订单ID（通过到货单）',
  `order_no` varchar(30) NOT NULL DEFAULT '' COMMENT '关联采购订单编号（冗余）',
  `supplier_id` int(11) NOT NULL DEFAULT '0' COMMENT '供应商ID',
  `supplier_name` varchar(200) NOT NULL DEFAULT '' COMMENT '供应商名称（冗余）',
  `in_date` date DEFAULT NULL COMMENT '入库日期',
  `warehouse_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库仓库ID',
  `warehouse_name` varchar(100) NOT NULL DEFAULT '' COMMENT '入库仓库名称（冗余）',
  `receiver_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库人ID',
  `receiver_name` varchar(50) NOT NULL DEFAULT '' COMMENT '入库人姓名（冗余）',
  `in_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '入库类型：1采购入库 2退货入库 3盘盈入库',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '入库状态：0草稿 1已入库 2已撤销',
  `confirm_time` datetime DEFAULT NULL COMMENT '确认入库时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '整体备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名（冗余）',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_in_no` (`in_no`),
  KEY `idx_arrival_id` (`arrival_id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_status` (`status`),
  KEY `idx_in_date` (`in_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购入库单主表';

CREATE TABLE `warehouse_purchase_in_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `in_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库单ID',
  `arrival_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联到货明细ID（行级追溯）',
  `material_id` int(11) NOT NULL DEFAULT '0' COMMENT '物料ID',
  `material_code` varchar(30) NOT NULL DEFAULT '' COMMENT '物料编码（冗余）',
  `material_name` varchar(200) NOT NULL DEFAULT '' COMMENT '物料名称（冗余）',
  `spec` varchar(200) DEFAULT NULL COMMENT '规格型号（冗余）',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位（冗余）',
  `in_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '入库数量',
  `in_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '入库单价（采购成本单价）',
  `in_total` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '入库总价（数量×单价）',
  `avg_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '确认入库时加权平均单价（移动加权平均法）',
  `batch_no` varchar(50) DEFAULT NULL COMMENT '生产批次',
  `produce_date` date DEFAULT NULL COMMENT '生产日期',
  `expire_date` date DEFAULT NULL COMMENT '有效期至',
  `location_id` int(11) NOT NULL DEFAULT '0' COMMENT '存放货位ID',
  `location_name` varchar(100) NOT NULL DEFAULT '' COMMENT '存放货位名称（冗余）',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_in_id` (`in_id`),
  KEY `idx_material_id` (`material_id`),
  KEY `idx_arrival_item_id` (`arrival_item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购入库明细表';

CREATE TABLE `warehouse_return` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `return_no` varchar(30) NOT NULL DEFAULT '' COMMENT '退库单编号 RT0001',
  `pick_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联领料单ID',
  `pick_no` varchar(30) NOT NULL DEFAULT '' COMMENT '关联领料单编号（冗余）',
  `return_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '退库类型：1生产 2维修 3质量 4其他',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '退库部门ID',
  `department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '退库部门名称（从领料单带出）',
  `returner_id` int(11) NOT NULL DEFAULT '0' COMMENT '退库人ID',
  `returner_name` varchar(50) NOT NULL DEFAULT '' COMMENT '退库人姓名',
  `return_date` date DEFAULT NULL COMMENT '退库日期',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0草稿 1待审核 2已审核 3已退库 4已驳回 5已撤销',
  `auditor_id` int(11) NOT NULL DEFAULT '0' COMMENT '审核人ID',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核备注',
  `return_reason` varchar(500) NOT NULL DEFAULT '' COMMENT '退库原因',
  `remark` varchar(500) DEFAULT NULL COMMENT '整体备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_return_no` (`return_no`),
  KEY `idx_pick_id` (`pick_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='配件退库单主表';

CREATE TABLE `warehouse_return_item` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `return_id` int(11) NOT NULL DEFAULT '0' COMMENT '退库单ID',
  `pick_item_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联领料单明细ID',
  `material_id` int(11) NOT NULL DEFAULT '0' COMMENT '物料ID',
  `material_code` varchar(30) NOT NULL DEFAULT '' COMMENT '物料编码',
  `material_name` varchar(200) NOT NULL DEFAULT '' COMMENT '物料名称',
  `spec` varchar(200) DEFAULT NULL COMMENT '规格型号',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位',
  `pick_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '领料数量（只读参考）',
  `returned_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '已退库数量（只读参考）',
  `return_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '本次退库数量',
  `return_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '退库单价（当前加权平均价）',
  `return_total` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '退库总价',
  `material_status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '物料状态：1完好 2待检 3报废',
  `location_id` int(11) NOT NULL DEFAULT '0' COMMENT '存放货位ID',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_return_id` (`return_id`),
  KEY `idx_pick_item_id` (`pick_item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='配件退库明细表';

CREATE TABLE `warehouse_return_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `return_id` int(11) NOT NULL DEFAULT '0' COMMENT '退库单ID',
  `action_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作类型：1创建 2编辑 3提交审核 4审核通过 5审核驳回 6确认退库 7撤销 8删除',
  `action_label` varchar(30) NOT NULL DEFAULT '' COMMENT '操作类型标签',
  `from_status` tinyint(1) DEFAULT NULL COMMENT '操作前状态',
  `to_status` tinyint(1) DEFAULT NULL COMMENT '操作后状态',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `action_time` datetime DEFAULT NULL COMMENT '操作时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '操作备注',
  `field_snapshot` json DEFAULT NULL COMMENT '变更字段快照（JSON）',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_return_id` (`return_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='配件退库操作日志表';

CREATE TABLE `warehouse_reverse_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `in_id` int(11) NOT NULL DEFAULT '0' COMMENT '入库单ID',
  `in_no` varchar(30) NOT NULL DEFAULT '' COMMENT '入库单编号（冗余）',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `reverse_time` datetime DEFAULT NULL COMMENT '冲销时间',
  `reason` varchar(500) DEFAULT NULL COMMENT '冲销原因',
  `snapshot` json DEFAULT NULL COMMENT '冲销前数据快照',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_in_id` (`in_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='入库冲销日志表';

CREATE TABLE `warehouse_scrap` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `scrap_no` varchar(30) NOT NULL DEFAULT '' COMMENT '报废单编号 SC0001',
  `pick_id` int(11) NOT NULL DEFAULT '0' COMMENT '关联领料单ID（可选）',
  `pick_no` varchar(30) NOT NULL DEFAULT '' COMMENT '关联领料单编号（冗余）',
  `scrap_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '报废类型：1质量 2过期 3技术淘汰 4事故损坏 5其他',
  `material_id` int(11) NOT NULL DEFAULT '0' COMMENT '物料ID',
  `material_code` varchar(30) NOT NULL DEFAULT '' COMMENT '物料编码',
  `material_name` varchar(200) NOT NULL DEFAULT '' COMMENT '物料名称',
  `spec` varchar(200) DEFAULT NULL COMMENT '规格型号',
  `unit` varchar(20) NOT NULL DEFAULT '' COMMENT '单位',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '报废部门ID',
  `department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '报废部门名称',
  `applicant_id` int(11) NOT NULL DEFAULT '0' COMMENT '报废申请人ID',
  `applicant_name` varchar(50) NOT NULL DEFAULT '' COMMENT '报废申请人姓名',
  `scrap_date` date DEFAULT NULL COMMENT '报废日期',
  `scrap_quantity` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '报废数量',
  `scrap_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '报废单价（当前加权平均价）',
  `scrap_total` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '报废总价',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：0草稿 1待审核 2已审核 3已报废 4已驳回 5已撤销',
  `auditor_id` int(11) NOT NULL DEFAULT '0' COMMENT '审核人ID',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核备注',
  `disposal_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '处理方式：1销毁 2退回供应商 3废品回收 4其他',
  `scrap_reason` varchar(500) NOT NULL DEFAULT '' COMMENT '报废原因',
  `remark` varchar(500) DEFAULT NULL COMMENT '整体备注',
  `created_by` int(11) NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_by_name` varchar(50) NOT NULL DEFAULT '' COMMENT '创建人姓名',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_scrap_no` (`scrap_no`),
  KEY `idx_material_id` (`material_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='报废出库单主表';

CREATE TABLE `warehouse_scrap_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `scrap_id` int(11) NOT NULL DEFAULT '0' COMMENT '报废单ID',
  `action_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作类型：1创建 2编辑 3提交审核 4审核通过 5审核驳回 6确认报废 7撤销 8删除',
  `action_label` varchar(30) NOT NULL DEFAULT '' COMMENT '操作类型标签',
  `from_status` tinyint(1) DEFAULT NULL COMMENT '操作前状态',
  `to_status` tinyint(1) DEFAULT NULL COMMENT '操作后状态',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `action_time` datetime DEFAULT NULL COMMENT '操作时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '操作备注',
  `field_snapshot` json DEFAULT NULL COMMENT '变更字段快照（JSON）',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_scrap_id` (`scrap_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='报废出库操作日志表';

CREATE TABLE `warehouse_stock_flow` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `material_id` int(11) NOT NULL DEFAULT '0' COMMENT '物料ID',
  `material_code` varchar(50) NOT NULL DEFAULT '' COMMENT '物料/产品编码（冗余）',
  `material_name` varchar(200) NOT NULL DEFAULT '' COMMENT '物料/产品名称（冗余）',
  `flow_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '变动类型：1采购入库 2生产领料 3成品入库 4销售出库 5调拨入库 6调拨出库 7盘盈 8盘亏 9报废出库',
  `flow_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '变动数量（正增负减）',
  `before_stock` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '变动前库存',
  `after_stock` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '变动后库存',
  `cost_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '成本单价（元）',
  `cost_total` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '成本总价（元）',
  `before_avg_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '变动前加权平均单价（元）',
  `after_avg_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '变动后加权平均单价（元）',
  `ref_type` varchar(30) NOT NULL DEFAULT '' COMMENT '关联单据类型',
  `ref_no` varchar(50) NOT NULL DEFAULT '' COMMENT '关联单据编号',
  `warehouse_id` int(11) NOT NULL DEFAULT '0' COMMENT '仓库ID',
  `location_id` int(11) NOT NULL DEFAULT '0' COMMENT '货位ID',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `flow_time` datetime DEFAULT NULL COMMENT '变动时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_material_id` (`material_id`),
  KEY `idx_warehouse_id` (`warehouse_id`),
  KEY `idx_flow_time` (`flow_time`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COMMENT='库存流水表（当前库存=SUM(flow_quantity)）';

CREATE TABLE `wechat_login_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `platform` tinyint(1) NOT NULL DEFAULT '0' COMMENT '平台:1=小程序 2=公众号',
  `openid` varchar(100) NOT NULL DEFAULT '' COMMENT 'openid',
  `login_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '方式:1=一键 2=扫码',
  `login_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态:1=成功 0=失败',
  `fail_reason` varchar(255) NOT NULL DEFAULT '' COMMENT '失败原因',
  `ip` varchar(45) NOT NULL DEFAULT '' COMMENT 'IP地址',
  `user_agent` varchar(255) NOT NULL DEFAULT '' COMMENT 'User-Agent',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_openid` (`openid`)
) ENGINE=InnoDB AUTO_INCREMENT=204 DEFAULT CHARSET=utf8mb4 COMMENT='微信登录日志表';

CREATE TABLE `work_report` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL DEFAULT '0' COMMENT '报工人ID',
  `user_name` varchar(50) NOT NULL DEFAULT '' COMMENT '报工人姓名（冗余）',
  `department_id` int(11) NOT NULL DEFAULT '0' COMMENT '部门ID',
  `department_name` varchar(100) NOT NULL DEFAULT '' COMMENT '部门名称（冗余）',
  `report_date` date DEFAULT NULL COMMENT '报工日期',
  `task_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '任务类型：1拆解 2焊接 3组装 4喷漆 5质检 6其他',
  `task_desc` varchar(500) DEFAULT NULL COMMENT '任务描述',
  `score` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '报工工分',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '审核状态：1待审核 2已通过 3已驳回',
  `auditor_id` int(11) NOT NULL DEFAULT '0' COMMENT '审核人ID',
  `auditor_name` varchar(50) NOT NULL DEFAULT '' COMMENT '审核人姓名（冗余）',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核备注',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `delete_time` datetime DEFAULT NULL COMMENT '软删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_report_date` (`report_date`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报工记录表';


